/* Vono exam prep question banks — 7 crafts of practice questions.
   Each: q = question, c = 4 choices, a = index of correct choice, why = explanation, t = topic.
   Practice items written to the public content outlines of the
   NIC (National-Interstate Council of State Boards of Cosmetology) exams and, for massage,
   the MBLEx outline. They are NOT actual exam items. To edit, change text below; keep exactly
   4 choices and set "a" to the right choice number (0 = first). Bump ?v= in index.html after editing. */
window.VONO_EXAMS={"barber":[{"q":"What must be done to an implement BEFORE it is placed in a disinfectant solution?","c":["Dry it with a clean towel and set it aside","Spray it with a light fragrance spray","Clean it with soap and water to remove debris","Wrap it in a clean cloth to store it"],"a":2,"why":"Visible debris prevents disinfectant from reaching the surface, so tools must be cleaned first.","t":"Infection Control"},{"q":"Which level of decontamination destroys ALL microbial life, including bacterial spores?","c":["Sterilization","Disinfection","Sanitation","Antisepsis"],"a":0,"why":"Sterilization is the highest level and kills every living microorganism, including spores.","t":"Infection Control"},{"q":"Which type of chemical is used on tools and nonporous surfaces but is NOT safe to apply to skin?","c":["Antiseptics","Detergents","Astringents","Disinfectants"],"a":3,"why":"Disinfectants are too harsh for skin; antiseptics are the milder products made for skin use.","t":"Infection Control"},{"q":"Which item must be thrown away after one use because it is porous and cannot be properly disinfected?","c":["Stainless steel shears","Cardboard emery board","Plastic cape clip","Hard rubber comb"],"a":1,"why":"Porous items absorb contaminants and cannot be disinfected, so they are single-use.","t":"Infection Control"},{"q":"How long must implements stay immersed in an EPA-registered disinfectant?","c":["Exactly 30 minutes for every product made","For the contact time stated on the product label","Until the solution begins to look cloudy","Five minutes for any disinfectant product"],"a":1,"why":"Manufacturers set the required contact time, and the label must always be followed.","t":"Infection Control"},{"q":"Which of the following is a bloodborne pathogen?","c":["Tinea barbae","Pediculosis capitis","Impetigo","Hepatitis B virus"],"a":3,"why":"Hepatitis B, hepatitis C and HIV are the best-known bloodborne pathogens.","t":"Bloodborne Pathogens & OSHA"},{"q":"Which document gives hazard, safe handling and first-aid information for a chemical product?","c":["Safety Data Sheet (SDS)","Client intake card","Product price list","Service release form"],"a":0,"why":"An SDS describes a product's hazards, handling, storage, spill response and first aid.","t":"Bloodborne Pathogens & OSHA"},{"q":"Who is responsible for supplying the Safety Data Sheet for a professional product?","c":["The state board","The client","The product manufacturer","The local fire department"],"a":2,"why":"Manufacturers and distributors provide SDSs, and the shop must keep them accessible.","t":"Bloodborne Pathogens & OSHA"},{"q":"Round-shaped bacteria are classified as which of the following?","c":["Cocci","Bacilli","Spirilla","Flagella"],"a":0,"why":"Cocci are round; bacilli are rod-shaped and spirilla are spiral-shaped.","t":"Bacteria & Viruses"},{"q":"Which bacterial structure is a whip-like extension that allows the organism to move?","c":["Spore","Capsule","Flagellum","Nucleus"],"a":2,"why":"Motile bacteria use flagella (or cilia) to move through liquids.","t":"Bacteria & Viruses"},{"q":"When conditions are unfavorable, some bacteria form which protective, inactive structure?","c":["Flagella","Spores","Colonies","Toxins"],"a":1,"why":"Spores are tough, dormant forms that resist heat and disinfectants until conditions improve.","t":"Bacteria & Viruses"},{"q":"Which statement about viruses is correct?","c":["Antibiotics reliably cure all viral infections","They reproduce well outside of any living host","They are far larger than most bacteria are","They must live inside a host cell to reproduce"],"a":3,"why":"Viruses are much smaller than bacteria and can only reproduce inside living host cells.","t":"Bacteria & Viruses"},{"q":"Ringworm of the scalp (tinea capitis) is caused by which type of organism?","c":["A bacterium","Head lice","A virus","A fungus"],"a":3,"why":"Tinea conditions are fungal infections, not worm infestations.","t":"Parasites & Fungi"},{"q":"Pediculosis capitis is caused by which of the following?","c":["Itch mites","Head lice","A fungus","A bacterium"],"a":1,"why":"Pediculosis capitis is an infestation of head lice; itch mites cause scabies.","t":"Parasites & Fungi"},{"q":"A client sits in your chair and you see live lice and nits in his hair. What should you do?","c":["Proceed with the service using a fresh cape","Spray the scalp with a disinfectant first","Decline service and recommend treatment","Cut the hair very short to remove all nits"],"a":2,"why":"Lice are contagious, so service is declined and the client is referred for treatment; the area is then disinfected.","t":"Parasites & Fungi"},{"q":"Nonpathogenic bacteria are best described as which of the following?","c":["Generally harmless and often helpful","Responsible for causing infectious disease","Found only inside infected skin wounds","Unable to survive on healthy human skin"],"a":0,"why":"Most bacteria are nonpathogenic; only pathogenic bacteria cause disease.","t":"Bacteria & Viruses"},{"q":"Which layer of skin contains blood vessels, nerves, sweat glands and oil glands?","c":["Epidermis","Stratum corneum","Dermis","Stratum germinativum"],"a":2,"why":"The dermis is the thick living layer beneath the epidermis that houses these structures.","t":"Anatomy of Skin & Hair"},{"q":"The outermost layer of the epidermis, made of flattened dead cells that are constantly shed, is called the:","c":["Stratum corneum","Stratum germinativum","Papillary layer","Reticular layer"],"a":0,"why":"The stratum corneum is the horny protective surface layer.","t":"Anatomy of Skin & Hair"},{"q":"Which glands produce sebum, the oil that lubricates the skin and hair?","c":["Sudoriferous glands","Eccrine glands","Lymph glands","Sebaceous glands"],"a":3,"why":"Sebaceous (oil) glands secrete sebum into the hair follicle; sudoriferous glands produce sweat.","t":"Anatomy of Skin & Hair"},{"q":"From the outside in, what are the three layers of a hair strand?","c":["Medulla, cortex, cuticle","Cuticle, cortex, medulla","Cortex, cuticle, medulla","Cuticle, medulla, cortex"],"a":1,"why":"The cuticle is outermost, the cortex is in the middle, and the medulla is the innermost core.","t":"Anatomy of Skin & Hair"},{"q":"Which layer of the hair provides most of its strength and elasticity and holds the natural pigment?","c":["Cuticle","Cortex","Medulla","Papilla"],"a":1,"why":"The cortex makes up most of the strand and contains melanin and the keratin protein.","t":"Anatomy of Skin & Hair"},{"q":"Which phase of the hair growth cycle is the resting phase, after which the old hair is shed?","c":["Anagen","Catagen","Keratinization","Telogen"],"a":3,"why":"In telogen the follicle rests before a new hair begins to grow and the old hair sheds.","t":"Hair Growth Cycle"},{"q":"The brief transitional phase when the follicle shrinks and detaches from the papilla is called:","c":["Catagen","Anagen","Telogen","Dormancy"],"a":0,"why":"Catagen separates the club hair from its blood supply between growth and rest.","t":"Hair Growth Cycle"},{"q":"Which structure at the base of the follicle supplies the nourishment needed for hair growth?","c":["Arrector pili","Sebaceous gland","Dermal papilla","Cuticle"],"a":2,"why":"The dermal papilla contains the blood supply that feeds the growing hair.","t":"Anatomy of Skin & Hair"},{"q":"Which type of electrical current flows steadily in one direction only?","c":["Direct current","Alternating current","Surge current","Induced current"],"a":0,"why":"Direct current (DC), such as from batteries, flows in a single direction; AC reverses direction.","t":"Chemistry & Electricity"},{"q":"What is alopecia areata?","c":["A bacterial infection of the scalp follicles","Excess hair growth on the face and chest","Sudden loss of hair in patches","A fungal infection that spreads in the beard"],"a":2,"why":"Alopecia areata causes sudden patchy hair loss and is not an infection.","t":"Hair & Scalp Disorders"},{"q":"Excessive hair growth in areas where hair is normally absent or very fine is called:","c":["Alopecia","Hypertrichosis","Trichoptilosis","Canities"],"a":1,"why":"Hypertrichosis (hirsutism) is abnormal, excessive hair growth.","t":"Hair & Scalp Disorders"},{"q":"Trichoptilosis is the technical term for which hair condition?","c":["Gray hair","Knotted hair","Beaded hair","Split ends"],"a":3,"why":"Trichoptilosis is splitting of the hair at the ends.","t":"Hair & Scalp Disorders"},{"q":"What is the approximate pH range of healthy skin and hair?","c":["Exactly 7.0","7.5 to 8.5","9 to 10","4.5 to 5.5"],"a":3,"why":"Healthy skin and hair are slightly acidic, with a pH of about 4.5 to 5.5.","t":"Chemistry & Electricity"},{"q":"A flat, discolored spot on the skin, such as a freckle, is called a:","c":["Papule","Macule","Vesicle","Nodule"],"a":1,"why":"A macule is a flat spot with no elevation, like a freckle.","t":"Skin Disorders"},{"q":"A small, raised lesion filled with clear fluid, such as a blister, is called a:","c":["Pustule","Papule","Vesicle","Tubercle"],"a":2,"why":"Vesicles are fluid-filled; pustules contain pus.","t":"Skin Disorders"},{"q":"Which condition is a highly contagious bacterial skin infection marked by honey-colored crusts?","c":["Impetigo","Eczema","Psoriasis","Rosacea"],"a":0,"why":"Impetigo is a contagious bacterial infection; eczema, psoriasis and rosacea are not contagious.","t":"Skin Disorders"},{"q":"Which term refers to ringworm of the beard?","c":["Tinea capitis","Tinea pedis","Tinea barbae","Tinea unguium"],"a":2,"why":"Tinea barbae is the fungal infection of the bearded areas of the face and neck.","t":"Skin Disorders"},{"q":"Each whole-number step on the pH scale represents what kind of change?","c":["A tenfold change in acidity or alkalinity","A twofold change in acidity or alkalinity","A ten percent change in product strength","A change of one unit in concentration only"],"a":0,"why":"The pH scale is logarithmic, so each whole number is a tenfold change.","t":"Chemistry & Electricity"},{"q":"Why are outlets near sinks and shampoo bowls protected by a GFCI?","c":["It increases the voltage supplied to tools","It stores extra electrical current for tools","It makes heating tools warm up faster","It cuts power when a ground fault occurs"],"a":3,"why":"A ground fault circuit interrupter shuts off power quickly to reduce shock risk around water.","t":"Chemistry & Electricity"},{"q":"What is the best way to keep clipper blades cutting smoothly during a busy day?","c":["Soak them in water between each client","Oil them lightly and brush off hair often","Spray them with hair spray for protection","Tighten the blade screws as much as you can"],"a":1,"why":"Regular brushing and light lubrication reduce friction and heat and prolong blade life.","t":"Implements & Equipment"},{"q":"Before disinfecting a clipper blade, you should first do which of the following?","c":["Submerge the running clipper in disinfectant","Brush off the hair and clean away debris","Wipe it with a dry paper tissue only","Dip it in hot water for one second"],"a":1,"why":"Debris must be removed before the disinfectant can work, and the motor is never submerged.","t":"Implements & Equipment"},{"q":"Which part of a pair of shears adjusts how loosely or tightly the blades move together?","c":["Tang","Shank","Finger brace","Pivot (tension) screw"],"a":3,"why":"The pivot screw joins the blades and sets their tension.","t":"Implements & Equipment"},{"q":"On standard clipper attachment guards, a higher guard number generally leaves the hair:","c":["Longer","Shorter","The same length","Thinner at the ends"],"a":0,"why":"Guard numbers increase with the length of hair left after cutting.","t":"Implements & Equipment"},{"q":"Which comb has fine, closely spaced, flexible teeth made for tapering and clipper-over-comb work?","c":["Rattail comb","Wide-tooth comb","Barber comb","Hair pick"],"a":2,"why":"The barber comb is designed to lift short hair evenly for clipper or shear-over-comb work.","t":"Implements & Equipment"},{"q":"What is the primary purpose of a lather machine in a barbershop?","c":["To warm and dispense lather for shaving","To sterilize razors between each client","To steam the face before a facial service","To mix and dispense permanent hair color"],"a":0,"why":"A lather machine heats and dispenses shaving lather; it must be cleaned regularly.","t":"Implements & Equipment"},{"q":"A facial steamer is mainly used to do which of the following?","c":["Sterilize razors and shaving tools","Dry out oily skin and blackheads","Soften the skin and beard hair","Permanently shrink the size of pores"],"a":2,"why":"Warm moist steam softens the skin and hair and prepares the skin for treatment or shaving.","t":"Implements & Equipment"},{"q":"Which tool is best for outlining necklines and detailing edges?","c":["Blending shears","Detail trimmer (outliner)","Wide-tooth comb","Texturizing razor"],"a":1,"why":"Trimmers have fine, close-cutting blades for outlining and edging.","t":"Implements & Equipment"},{"q":"Which shear edge is known for the sharpest, most precise slicing cut?","c":["Serrated edge","Notched edge","Blunt-ground edge","Convex edge"],"a":3,"why":"Convex-edge shears are honed to a razor-sharp curved edge for the smoothest slicing; serrated edges grip hair and notched blades are for thinning.","t":"Implements & Equipment"},{"q":"Before cleaning a corded clipper, the barber should do which of the following?","c":["Spray it while it is running","Keep it running to clear hair","Leave it on the charger","Turn it off and unplug it"],"a":3,"why":"Electrical tools are turned off and unplugged before cleaning to prevent shock.","t":"Implements & Equipment"},{"q":"Before the cut begins, what should the barber do first?","c":["Start with clippers at the nape of the neck","Discuss desired results and analyze hair and scalp","Apply styling product to the dry hair first","Choose a guard length without asking the client"],"a":1,"why":"A consultation clarifies what the client wants and what the hair and scalp can realistically do.","t":"Consultation"},{"q":"A client with a strong cowlick at the front hairline asks for a short fringe worn straight down. What is the best response?","c":["Cut it exactly as asked and say nothing","Refuse to perform any haircut service","Explain the cowlick and suggest an alternative","Cut the front much shorter to hide the cowlick"],"a":2,"why":"Good consultation sets realistic expectations and offers a style that works with the growth pattern.","t":"Consultation"},{"q":"A client who needs a chemical service has open sores and abrasions on his scalp. What should the barber do?","c":["Postpone the chemical service","Apply the product quickly, then rinse","Use a stronger neutralizer","Do a strand test only and proceed"],"a":0,"why":"Chemicals applied to broken or irritated skin can burn and cause infection, so the service is postponed.","t":"Chemical Safety"},{"q":"Which description best fits a fade haircut?","c":["The length stays the same all around the head","The hair gets gradually longer toward the nape","Hair blends gradually from very short to longer","Hair is cut into blunt layers throughout"],"a":2,"why":"A fade blends from very short (often skin level) to longer lengths with no visible line.","t":"Haircutting"},{"q":"In the clipper-over-comb technique, what is the role of the comb?","c":["To lift and support hair while clippers cut over it","To measure the overall shape and width of the head","To replace the clipper guard attachment on the blade","To smooth the hair after the cut is finished"],"a":0,"why":"The comb holds hair in position so the clipper trims whatever extends above the teeth.","t":"Haircutting"},{"q":"Shear-over-comb is most often used to do which of the following?","c":["Create long layers in the crown area","Notch the ends of very thick hair","Remove all of the weight from the top","Blend short areas at the nape and sides"],"a":3,"why":"Shear-over-comb creates close, soft tapers where hair is too short to hold between the fingers.","t":"Haircutting"},{"q":"In haircutting, the section that serves as the length reference for the rest of the cut is called the:","c":["Elevation","Guideline","Part line","Perimeter"],"a":1,"why":"A guideline (guide) shows the length to which following sections are cut.","t":"Haircutting"},{"q":"Hair is held out at 90 degrees from the head and cut to one consistent length. What is produced?","c":["A one-length form","Uniform layers","A heavy weight line at the nape","A solid form with no layers"],"a":1,"why":"Lifting hair to 90 degrees and cutting to the same length creates uniform layers.","t":"Haircutting"},{"q":"Cutting hair straight across with no elevation (0 degrees) builds up what?","c":["Uniform layers","Increased layers","Maximum movement","A solid form with weight"],"a":3,"why":"Zero elevation leaves the ends stacked at one length, forming a heavy, solid shape.","t":"Haircutting"},{"q":"Which technique removes bulk and adds movement by cutting small notches into the hair ends with shear tips?","c":["Point cutting","Club cutting","Freehand fading","Slide-over cutting"],"a":0,"why":"Point cutting is a texturizing technique that softens blunt ends.","t":"Haircutting"},{"q":"Thinning shears are primarily used to do which of the following?","c":["Cut a sharp, blunt perimeter line","Outline the neckline and sideburns","Remove bulk without greatly shortening length","Remove all of the texture from the top"],"a":2,"why":"Thinning shears have teeth that cut some hairs and pass others, reducing bulk while keeping length.","t":"Haircutting"},{"q":"When using a razor to cut hair, which condition is recommended?","c":["Damp hair with a guarded razor","Dry hair with an unguarded razor","Very coarse dry hair only","Hair coated with styling product"],"a":0,"why":"Damp hair allows the razor to glide without pulling, and a guard adds control.","t":"Haircutting"},{"q":"Which characteristic determines whether hair is described as fine, medium or coarse?","c":["Number of hairs per square inch","Length of the strand","Diameter of the strand","Amount of pigment"],"a":2,"why":"Texture refers to strand diameter, while density refers to the number of hairs.","t":"Haircutting"},{"q":"Hair with high porosity does which of the following?","c":["Resists absorbing moisture","Absorbs moisture easily","Cannot hold any artificial color","Has no cuticle layer"],"a":1,"why":"High porosity means the cuticle is raised or damaged, so the hair absorbs liquids readily.","t":"Hair Analysis"},{"q":"Which water temperature is appropriate when shampooing a client?","c":["Hot enough to open the hair cuticle","Cold to prevent any scalp irritation","Hot at first, then switched to cold","Comfortably warm, tested before use"],"a":3,"why":"Water should be comfortably warm and tested on the barber's wrist before it touches the client.","t":"Shampoo & Scalp Care"},{"q":"During a scalp massage, which part of the hand should be used?","c":["The knuckles with hard pressure","The fingernails for deeper stimulation","The heel of the hand only","The pads of the fingertips"],"a":3,"why":"Fingertip pads give firm, comfortable pressure without scratching or tugging the scalp.","t":"Shampoo & Scalp Care"},{"q":"Which ingredient group in shampoo lifts oil and dirt from the hair so they can be rinsed away?","c":["Humectants","Surfactants","Emollients","Astringents"],"a":1,"why":"Surfactants attract both water and oil, allowing grime to be washed off.","t":"Shampoo & Scalp Care"},{"q":"What is the main purpose of a rinse-off conditioner?","c":["Strip away all product buildup","Lift the natural pigment from hair","Smooth the cuticle and add manageability","Deposit a permanent color to the hair"],"a":2,"why":"Conditioners smooth the cuticle, reduce tangling and make the hair easier to manage.","t":"Shampoo & Scalp Care"},{"q":"The lightness or darkness of a hair color is called its:","c":["Level","Tone","Intensity","Primary"],"a":0,"why":"Level refers to depth, from very dark to very light; tone refers to warmth or coolness.","t":"Hair Color"},{"q":"What are the three primary colors used in color theory?","c":["Red, green, yellow","Orange, green, violet","Blue, red, yellow","Black, white, red"],"a":2,"why":"Blue, red and yellow cannot be mixed from other colors and make up all secondary colors.","t":"Hair Color"},{"q":"A client's lightened hair pulls yellow. Which tone neutralizes yellow?","c":["Violet","Orange","Red","Green-yellow"],"a":0,"why":"Violet sits opposite yellow on the color wheel, so it cancels it out.","t":"Hair Color"},{"q":"When should a predisposition (patch) test for aniline derivative tints be performed?","c":["Immediately before the color is applied","After the tint is mixed with developer","Only on new clients and never regulars","24 to 48 hours before the service"],"a":3,"why":"The test checks for allergic reaction and needs time to show results before the service.","t":"Hair Color"},{"q":"Which product provides the oxidizing agent in permanent hair color?","c":["Ammonia","Hydrogen peroxide developer","Neutralizing shampoo","Toner"],"a":1,"why":"Developer (hydrogen peroxide) supplies the oxygen that develops color and creates lift.","t":"Hair Color"},{"q":"Hair lightening works mainly by doing which of the following?","c":["Adding pigment to the hair cuticle layer","Oxidizing natural melanin in the cortex","Coating the strand with a light-colored tint","Removing the cuticle layer completely"],"a":1,"why":"Lightener oxidizes (breaks down) melanin in the cortex, which makes the hair lighter.","t":"Hair Color"},{"q":"What causes hair to turn gray?","c":["Excess oil on the scalp","Too much keratin in the cortex","Damage to the cuticle","Reduced melanin production"],"a":3,"why":"Melanocytes gradually make less pigment, so new hair grows in with little or no color.","t":"Hair Color"},{"q":"Permanent waving rearranges the hair by breaking and reforming which bonds?","c":["Disulfide bonds","Hydrogen bonds only","Salt bonds only","Peptide bonds only"],"a":0,"why":"Waving lotion breaks disulfide bonds in the cortex and the neutralizer re-forms them in the new shape.","t":"Chemical Texture"},{"q":"How does using smaller perm rods affect the result?","c":["Looser, larger curls","No change in curl size","Tighter curls","Straighter hair"],"a":2,"why":"Hair wrapped around a smaller rod sets into a smaller, tighter curl.","t":"Chemical Texture"},{"q":"What does the neutralizer do in a permanent wave?","c":["Re-forms disulfide bonds and sets the curl","Breaks disulfide bonds inside the cortex","Lightens the hair's natural pigment color","Raises the pH level of the scalp skin"],"a":0,"why":"Neutralizer (bonder) oxidizes the hair, rebuilding bonds so the curl pattern becomes permanent.","t":"Chemical Texture"},{"q":"Why is a protective base cream applied to the scalp and skin before a relaxer service?","c":["To speed up the processing time","To lighten the natural hair color","To protect the skin from irritation","To neutralize the relaxer on the hair"],"a":2,"why":"The base creates a barrier that helps protect the scalp, ears and hairline from the strong chemical.","t":"Chemical Texture"},{"q":"What is the purpose of a strand test before a relaxer service?","c":["To decide which guard to use afterward","To see how hair reacts and how long to process","To measure the client's overall hair density","To check the scalp for dandruff or flaking"],"a":1,"why":"A strand test shows how the hair responds and helps determine safe processing time.","t":"Chemical Texture"},{"q":"A client's hair is badly damaged and breaking from repeated bleaching, and he asks for a perm. What is the best action?","c":["Use the strongest solution available","Use the smallest rods to be safe","Perm and relax the hair together","Decline until the hair is healthier"],"a":3,"why":"Chemical services on severely damaged hair can cause breakage, so conditioning treatments come first.","t":"Chemical Texture"},{"q":"Which practice helps protect hair during blow-drying?","c":["Hold the dryer still at the roots","Use the highest heat on soaking wet hair","Rest the nozzle on the scalp","Keep the dryer moving at a safe distance"],"a":3,"why":"Moving the dryer and keeping distance prevents overheating the hair and scalp.","t":"Thermal Services"},{"q":"How can you safely check the temperature of a flat iron before using it on hair?","c":["Press it briefly on the client's hand","Clamp it on a clean tissue or white towel","Hold it close to the client's scalp","Wet the plates with water before use"],"a":1,"why":"If the tissue scorches, the iron is too hot; testing on a client risks burns.","t":"Thermal Services"},{"q":"Which hairpiece fiber is most likely to be damaged by high heat from styling tools?","c":["Human hair","Remy human hair","Standard synthetic fiber","Virgin human hair"],"a":2,"why":"Most synthetic fibers melt or distort under heat unless made to be heat-friendly.","t":"Hairpieces & Wigs"},{"q":"Which measurement is the basic starting point for sizing a client for a wig?","c":["Head circumference around the hairline","Distance between the eyebrows","Width of the shoulders","Height of the ear"],"a":0,"why":"Circumference around the head at the hairline is the basic size measurement for a wig.","t":"Hairpieces & Wigs"},{"q":"What should a barber wear while applying chemical products to a client?","c":["Thin cotton gloves","Bare hands for a better feel","Chemical-resistant protective gloves","A fresh smock and nothing else"],"a":2,"why":"Gloves protect the barber's skin from irritation and absorption of chemicals.","t":"Chemical Safety"},{"q":"What is the purpose of a neck strip or towel placed under the cape?","c":["Keep the cape from touching the client's skin","Remove the need to disinfect the cape","Hold the client's hair away from the neck","Reduce the amount of hair that falls"],"a":0,"why":"A barrier prevents direct cape-to-skin contact and helps limit spread of contaminants.","t":"Infection Control"},{"q":"Which face shape is considered ideal and suits most hairstyles?","c":["Round","Square","Diamond","Oval"],"a":3,"why":"The oval face is well proportioned, so most styles balance it.","t":"Hair Design"},{"q":"Which styling approach best suits a client with a round face?","c":["Add width at the sides of the head","Add height on top and keep the sides closer","Keep the hair flat and wide at the sides","Cut the hair into a rounded bowl shape"],"a":1,"why":"Height and slimmer sides create the illusion of a longer, narrower face.","t":"Hair Design"},{"q":"How can a barber make a long, narrow face appear shorter?","c":["Add height on top of the head","Add fullness at the sides, keep the top shorter","Cut the sides very short and tight","Style the hair straight up and back"],"a":1,"why":"Width at the sides and less height balance the length of a long face.","t":"Hair Design"},{"q":"What is the purpose of a hot towel applied to the face before a shave?","c":["Disinfect the skin of the face","Tighten the pores before shaving","Close the hair follicles on the face","Soften the beard and relax the skin"],"a":3,"why":"Warm moist heat softens the beard hair and prepares the skin for a smoother shave.","t":"Shaving"},{"q":"Shaving 'with the grain' means moving the razor in which direction?","c":["The direction the hair grows","Against the direction of hair growth","Side to side across the grain","Straight upward"],"a":0,"why":"Shaving with the grain is the first, safest pass and causes the least irritation.","t":"Shaving"},{"q":"Razor bumps (pseudofolliculitis barbae) occur when what happens?","c":["A fungus infects the hair follicle","A virus enters the broken skin","Cut hair curls back into the skin","Hair is left too long after a shave"],"a":2,"why":"Curly hair that re-enters the skin causes inflammation and bumps, especially after close shaving.","t":"Shaving"},{"q":"A client is nicked during a shave and bleeds. After putting on gloves, what should the barber do next?","c":["Stop the bleeding and clean the wound","Continue shaving elsewhere on the face","Wipe the blood with the used towel","Reuse the same blade after wiping"],"a":0,"why":"Standard precautions require stopping the bleeding and cleaning the wound before dealing with contaminated items.","t":"Bloodborne Pathogens & OSHA"},{"q":"After it touches blood, how must a used razor blade be handled?","c":["Wiped clean and reused on the next client","Soaked in water and reused later","Discarded in a sharps container","Thrown in the regular trash can"],"a":2,"why":"Contaminated blades are sharps and must go into a puncture-resistant, labeled container.","t":"Bloodborne Pathogens & OSHA"},{"q":"During a straight razor shave, what is the role of the barber's free hand?","c":["Holding the razor steady","Stretching the skin taut","Applying fresh lather","Holding the hot towel"],"a":1,"why":"Stretching the skin creates a smooth, firm surface and reduces nicks.","t":"Shaving"},{"q":"Before applying an after-shave or other skin product, what should the barber ask about?","c":["A recent haircut","A preferred barber","A favorite fragrance","Allergies or sensitivities"],"a":3,"why":"Asking about allergies helps prevent adverse reactions to ingredients.","t":"Shaving"},{"q":"Skin that looks shiny with enlarged pores and frequent blackheads is classified as:","c":["Dry","Normal","Mature","Oily"],"a":3,"why":"Overactive sebaceous glands create shine, large pores and comedones in oily skin.","t":"Skin Care & Facials"},{"q":"A light, gliding stroking movement used to begin and end a massage is called:","c":["Petrissage","Effleurage","Tapotement","Friction"],"a":1,"why":"Effleurage is the soothing stroking movement; petrissage is kneading.","t":"Skin Care & Facials"},{"q":"Tapotement is a massage movement that consists of which of the following?","c":["Slow gliding strokes","Deep kneading and rolling","Light tapping or percussion","Circular rubbing motions"],"a":2,"why":"Tapotement, or percussion, uses light tapping or striking movements.","t":"Skin Care & Facials"},{"q":"A client with sunburned, peeling skin asks for a facial. What should the barber do?","c":["Postpone the facial and recommend healing first","Use an exfoliating scrub to remove the peeling","Apply steam to soothe the burned skin quickly","Use firm massage to relieve the tightness"],"a":0,"why":"Burned or irritated skin should not be exfoliated, steamed or massaged; it needs time to heal.","t":"Skin Care & Facials"},{"q":"Before beginning a beard trim, what should the barber do?","c":["Cut the beard dry without using a cape","Lather the whole face of the client first","Evaluate growth patterns and face shape","Apply astringent to the beard area first"],"a":2,"why":"Understanding growth direction and face shape guides a balanced, flattering trim.","t":"Beard Trimming"},{"q":"A client's beard area shows pus-filled bumps and crusting. What should the barber do?","c":["Decline the service and refer the client to a doctor","Shave carefully over the lesions and bumps","Cover the area with a hot towel and proceed","Apply after-shave directly onto the bumps"],"a":0,"why":"These signs may indicate a contagious infection, so service is declined and a referral is made.","t":"Skin Disorders"},{"q":"How often should a blade in a shaving razor be replaced?","c":["After rinsing, on the next client","After wiping it with a towel","After disinfecting, for repeated clients","With a new blade for every client"],"a":3,"why":"Single-use blades prevent cross-contamination and are discarded in a sharps container.","t":"Shaving"},{"q":"What is beard oil mainly used for?","c":["Permanently dyeing gray facial hair","Moisturizing facial hair and the skin","Opening the follicles before a shave","Disinfecting the skin before service"],"a":1,"why":"Beard oil conditions the hair and softens skin, reducing dryness and itch.","t":"Beard Trimming"},{"q":"When purchasing a blowdryer, what are the important factors to consider?","c":["Aesthetics and price","Weight and balance","Brand name and color","Cord length and noise level"],"a":1,"why":"Weight and balance matter most because a barber holds the dryer for long periods, and a heavy or poorly balanced dryer causes hand and arm fatigue.","t":"Implements & Equipment"},{"q":"A(n) ______ is contact with nonintact (broken) skin, blood, body fluid, or other infectious materials as a result of the performance of a worker's duties.","c":["efficacy","standard precaution","PPE","exposure incident"],"a":3,"why":"An exposure incident is contact with broken skin, blood, body fluid, or other infectious materials during the performance of a worker's duties.","t":"Bloodborne Pathogens & OSHA"},{"q":"What happens when a mild perm solution is used on coarse hair?","c":["The hair softens.","The hair won't perm.","The hair lightens.","The hair straightens."],"a":1,"why":"Coarse hair is resistant, so a mild perm solution is not strong enough to change it and the hair won't perm.","t":"Chemical Texture"},{"q":"What is the primary active ingredient in all hydroxide relaxers?","c":["Ammonia","Thioglycolate","Hydroxide ions","Oxygen"],"a":2,"why":"Hydroxide relaxers work through hydroxide ions, which swell the hair and break its disulfide bonds.","t":"Chemical Texture"},{"q":"What are the four razor positions used in barbering?","c":["Freehand, backhand, reverse freehand, reverse backhand","Freehand, backhand, reverse backhand, sideways","Freehand, backward, reverse freehand, side-to-side","Backhand, reverse freehand, reverse backhand, sideways"],"a":0,"why":"The four razor positions are freehand, backhand, reverse freehand, and reverse backhand.","t":"Shaving"},{"q":"When cutting hair, what is the angle at which the fingers are held called?","c":["Elevation","Overdirection","Finger angle","Guideline"],"a":2,"why":"The angle at which the fingers are held while cutting is called the finger angle.","t":"Haircutting"},{"q":"Being well groomed advertises a professional's ______ their industry.","c":["abstinence from","obedience to","distrust in","commitment to"],"a":3,"why":"Being well groomed shows a professional's commitment to their industry and advertises it to clients.","t":"Professional Practice"},{"q":"______ is the identification of long-term and short-term goals.","c":["Visualizing","Building self-esteem","Goal setting","Mission statement writing"],"a":2,"why":"Goal setting is the identification of long-term and short-term goals.","t":"Professional Practice"},{"q":"What is the primary function of the circulatory system?","c":["Breaking down food into nutrients or waste","Controlling blood movement throughout the body","Eliminating waste from the body","Regulating body temperature"],"a":1,"why":"The circulatory system controls blood movement throughout the body, carrying oxygen and nutrients to the cells.","t":"Anatomy & Physiology"},{"q":"What is pediculosis capitis?","c":["A head lice infestation","A bacterial infection","A fungal infection","A form of dandruff"],"a":0,"why":"Pediculosis capitis is the medical name for a head lice infestation.","t":"Parasites & Fungi"},{"q":"What should you be aware of when cutting a blunt cut?","c":["The degree of elevation","The crown area and around the ears","The amount of overdirection","The cutting line"],"a":1,"why":"In a blunt cut, pay special attention to the crown area and around the ears, where hair length and weight can easily end up uneven.","t":"Haircutting"},{"q":"What type of comb is best for detangling large sections of hair?","c":["Cutting comb","Flat handle comb","Teasing comb","Wide-tooth comb"],"a":3,"why":"A wide-tooth comb detangles large sections of hair gently and with less breakage.","t":"Implements & Equipment"},{"q":"Which of the following makes up 50 to 70 percent of the body's weight and is necessary for virtually every function of the cells and body?","c":["Water","Mineral","Protein","Fat"],"a":0,"why":"Water makes up 50 to 70 percent of body weight and is needed for virtually every cell function.","t":"Anatomy & Physiology"},{"q":"What is the function of sensory nerves?","c":["To control digestion and metabolism","To regulate heartbeat and breathing","To carry messages from the sense organs to the brain and spinal cord","To carry impulses from the brain to the muscles or glands"],"a":2,"why":"Sensory nerves carry messages from the sense organs to the brain and spinal cord.","t":"Anatomy & Physiology"},{"q":"What does a fade refer to in haircutting?","c":["A type of haircolor technique","A haircut where only one side of the head is shaved","A tapered haircut with smooth transitions","A haircut where all hair is cut to the same length"],"a":2,"why":"A fade is a tapered haircut with smooth transitions from short to longer lengths.","t":"Haircutting"},{"q":"What are disease-causing microorganisms that are carried in the body by blood or body fluids, such as hepatitis and HIV, called?","c":["Mycobacteria","Systemic infections","Bloodborne pathogens","Bloodborne viruses"],"a":2,"why":"Disease-causing microorganisms carried in blood or body fluids, such as hepatitis and HIV, are bloodborne pathogens.","t":"Bloodborne Pathogens & OSHA"},{"q":"What is the function of the hair follicle?","c":["Lubricating the hair","Causing goosebumps","Anchoring the hair in the skin","Supplying nutrients to the hair"],"a":2,"why":"The hair follicle anchors the hair in the skin.","t":"Anatomy of Skin & Hair"},{"q":"What organization did the barber-surgeons form?","c":["Worshipful Company of Soldiers","Worshipful Company of Barbers","Worshipful Company of Blacksmiths","Worshipful Company of Surgeons"],"a":1,"why":"Barber-surgeons formed the Worshipful Company of Barbers.","t":"History & Licensing"},{"q":"What type of canities is a result of age?","c":["Ringed hair","Congenital canities","Acquired canities","Hirsuties"],"a":2,"why":"Acquired canities is graying that comes with age, while congenital canities is present at birth.","t":"Hair & Scalp Disorders"},{"q":"What is the purpose of neck strips in barbering?","c":["Providing a barrier","Keeping hair in place","Absorbing excess water","Protecting barber's hands"],"a":0,"why":"Neck strips act as a barrier between the client's skin and the cape.","t":"Shampoo & Scalp Care"},{"q":"What is the shear-over-comb technique useful for?","c":["Cutting hair from long to short lengths","Creating a blunt cut","Providing a close shave on the sides of the head","Cutting hair from short to long"],"a":3,"why":"Shear-over-comb is used to cut hair from short to long, as in a taper at the nape and sides.","t":"Haircutting"},{"q":"______ are the basic units of matter.","c":["Electrons","Neutrons","Protons","Atoms"],"a":3,"why":"Atoms are the basic units of matter.","t":"Chemistry & Electricity"},{"q":"Which comb is primarily used for sectioning the hair during haircutting services?","c":["Wide-tooth comb","Barber comb","Tail comb","Styling or cutting comb"],"a":2,"why":"A tail comb is used for parting and sectioning hair during haircutting services.","t":"Implements & Equipment"},{"q":"Which of the following is TRUE of nonpathogenic and pathogenic bacteria?","c":["Both pathogenic and nonpathogenic bacteria are harmful to humans.","Neither pathogenic nor nonpathogenic bacteria are harmful to humans.","Pathogenic bacteria are harmful to humans, whereas nonpathogenic bacteria are not.","Nonpathogenic bacteria are harmful to humans, whereas pathogenic bacteria are not."],"a":2,"why":"Pathogenic bacteria cause disease and are harmful to humans, while nonpathogenic bacteria are not.","t":"Bacteria & Viruses"},{"q":"How should the client's skin be kept during the shave?","c":["Cold","Dry","Moist","Wet"],"a":2,"why":"The client's skin should be kept moist during the shave so the razor glides and irritation is reduced.","t":"Shaving"},{"q":"What color range is generally better for blending and requires less maintenance for clients who are 80 to 100 percent gray?","c":["Blond","Brown","Black","Red"],"a":0,"why":"Blond tones blend gray more easily and need less maintenance than dark colors, which show regrowth quickly.","t":"Hair Color"},{"q":"What is the purpose of the second-time-over shave?","c":["To shave against the grain","To apply more shaving cream","To remove any remaining hair after the first shave","To prepare the face for finishing steps"],"a":2,"why":"The second-time-over shave removes any hair that remains after the first pass.","t":"Shaving"},{"q":"What is androgenic alopecia characterized by?","c":["Excessive hair growth","Hair curling","A shortened anagen phase","Change in the hair's color"],"a":2,"why":"Androgenic alopecia is characterized by a shortened anagen (growth) phase, so hairs grow thinner and shorter.","t":"Hair & Scalp Disorders"},{"q":"Which type of haircolor product can lighten and deposit color simultaneously?","c":["Permanent haircolor","Demipermanent haircolor","Semipermanent haircolor","Temporary haircolor"],"a":0,"why":"Permanent haircolor can lighten the natural pigment and deposit color in the same step.","t":"Hair Color"},{"q":"What is reflective listening?","c":["Pretending to listen to the client while actually beginning to concentrate on their service","Listening to the client and then repeating, in your own words, what you think the client is telling you","Having your assistants listen to the client and then asking them to tell you what the client said","Trying to remember what clients requested without actually having to ask them to repeat it"],"a":1,"why":"Reflective listening means listening, then repeating in your own words what you think the client is telling you.","t":"Professional Practice"},{"q":"What is the role of a toner in the haircoloring process?","c":["Further lightening the hair","Causing the hair to expand and swell","Increasing the hair's natural pigment","Removing harsh undertones after pre-lightening"],"a":3,"why":"A toner removes unwanted, harsh undertones after the hair has been pre-lightened.","t":"Hair Color"},{"q":"Why should ammonia never be mixed with bleach?","c":["It \"discolors\" more than lightens the hair.","It dries out skin excessively.","It creates a potentially deadly gas.","They become unpredictable in their use."],"a":2,"why":"Mixing ammonia with bleach creates a potentially deadly gas.","t":"Chemical Safety"},{"q":"What is the function of the hair cuticle?","c":["To provide elasticity","To protect the cortex","To add weight to the hair","To determine the hair's color"],"a":1,"why":"The cuticle is the outer layer of the hair and protects the cortex.","t":"Anatomy of Skin & Hair"},{"q":"Which of the following is TRUE of phenolic disinfectants?","c":["The safest way to dispose of them is down the drain.","They can be safely applied to the skin.","They are known carcinogens.","They have a low pH."],"a":2,"why":"Phenolic disinfectants are known carcinogens, so they must be used with care and never applied to the skin.","t":"Chemical Safety"},{"q":"What is the primary component of hair?","c":["Lipids","Keratin","Minerals","Water"],"a":1,"why":"Hair is made mainly of keratin, a fibrous protein.","t":"Anatomy of Skin & Hair"},{"q":"What is the primary determinant of skin color?","c":["The size of skin cells","The amount of sweat produced","The number of melanocytes","The amount of melanin produced"],"a":3,"why":"The amount of melanin produced is the primary determinant of skin color.","t":"Anatomy of Skin & Hair"},{"q":"Which of the following BEST defines transmission?","c":["The process by which the spread of infections is controlled or suppressed","The process by which pathogens move between individuals","The process by which individuals are cured of sickness","The process by which diseases become infectious"],"a":1,"why":"Transmission is the process by which pathogens move between individuals.","t":"Infection Control"},{"q":"What protein fiber gives the skin form and strength?","c":["Keratin","Elastin","Collagen","Fibrin"],"a":2,"why":"Collagen is the protein fiber that gives skin its form and strength.","t":"Professional Practice"},{"q":"What is the primary cause of dandruff?","c":["Stress","Pollution","A specific fungus","Seasonal changes"],"a":2,"why":"Dandruff is associated with a specific fungus (Malassezia) that feeds on scalp oils.","t":"Hair & Scalp Disorders"},{"q":"Most bacteria are ______.","c":["nonpathogenic","pathogenic","contagious","deadly"],"a":0,"why":"Most bacteria are nonpathogenic, meaning they do not cause disease.","t":"Bacteria & Viruses"},{"q":"Which layer of the skin is responsible for producing new skin cells?","c":["Stratum corneum","Papillary layer","Reticular layer","Stratum germinativum"],"a":3,"why":"New skin cells are produced in the stratum germinativum, the deepest layer of the epidermis.","t":"Anatomy of Skin & Hair"},{"q":"Which draping uses a plastic shampoo cape?","c":["Chemical service draping","Shave service draping","Shampoo draping","Cutting or styling draping"],"a":2,"why":"Shampoo draping uses a plastic shampoo cape to protect the client's clothing from water.","t":"Shampoo & Scalp Care"},{"q":"What is the principle that refers to creating equal or appropriate proportions?","c":["Rhythm","Balance","Proportion","Emphasis"],"a":1,"why":"Proportion is the principle that refers to creating equal or appropriate proportions.","t":"Hair Design"},{"q":"What is the function of nerves in the body?","c":["To store energy","To conduct information","To filter blood","To produce hormones"],"a":1,"why":"Nerves conduct information between the brain, spinal cord, and the rest of the body.","t":"Anatomy of Skin & Hair"},{"q":"What term refers to a hairstyle's mass or general outline?","c":["Form","Space","Texture","Line"],"a":0,"why":"Form is a hairstyle's mass or general outline.","t":"Hair Design"},{"q":"When designing sideburns, what should you consider?","c":["Making them as long as possible","Ensuring they are the same thickness all through","Keeping them even in length and thickness","Making them stand out"],"a":2,"why":"When designing sideburns, keep them even in length and thickness on both sides.","t":"Hair Design"},{"q":"Which of the following is TRUE of a disease that spreads from one person to another?","c":["It is deadly.","It is nonpathogenic.","It is communicable.","It is systemic."],"a":2,"why":"A disease that spreads from one person to another is communicable.","t":"Infection Control"},{"q":"What are the three main steps of a standard professional shave?","c":["Preparing the face, shaving the face, finishing the face","Preparing the face, shaving the face, cleaning the face","Analyzing the face, shaving the face, finishing the face","Preparing the face, cutting the hair, finishing the face"],"a":0,"why":"A standard shave has three steps: prepare the face, shave the face, and finish the face.","t":"Shaving"},{"q":"Which of the following conditions would prevent a hair service from being performed?","c":["Hair thinning","Gray hair","Abrasions on the scalp","Dry hair"],"a":2,"why":"Abrasions on the scalp are a contraindication, so the service should not be performed.","t":"Anatomy of Skin & Hair"},{"q":"If you are interested in working at an establishment with secure pay and benefits, and one that will allow you to transfer should you relocate to a different state, where should you focus your search?","c":["Independent chains","Large national chains","Independent shops","Booth rental establishments"],"a":1,"why":"Large national chains tend to offer secure pay and benefits and let employees transfer when they relocate.","t":"Professional Practice"},{"q":"What should you do if you are removing protective styles and performing a shampooing service?","c":["Cut off the protective styles before the shampoo service.","Remove the protective styles during the shampoo service.","Detangle the hair before the shampoo service.","Remove the protective styles after the shampoo service."],"a":2,"why":"Detangle the hair before shampooing when removing protective styles, so the shampoo does not cause matting and breakage.","t":"Shampoo & Scalp Care"},{"q":"What is the origin of the term \"barber\"?","c":["It's derived from the Greek word for hair.","It's from the Latin word for scissors.","It was coined in the twentieth century.","It's from the Latin word barba for beard."],"a":3,"why":"The word \"barber\" comes from the Latin word barba, meaning beard.","t":"History & Licensing"},{"q":"The pH scale is used to measure ______.","c":["acidity and alkalinity","overexposure and underexposure","levels of carbon dioxide","levels of oxygen"],"a":0,"why":"The pH scale measures acidity and alkalinity.","t":"Chemistry & Electricity"},{"q":"What should be done with used blades after a shaving session?","c":["Discard them in a sharps container.","Discard them in the regular trash.","Reuse them for the next client.","Wash and reuse them."],"a":0,"why":"Used blades go into a sharps container so no one is cut or exposed to blood.","t":"Implements & Equipment"},{"q":"What technique is commonly used for shaping curlier textured beards?","c":["Clipper-over-comb","Freehand clipper","Shear-over-comb","Razor-over-comb"],"a":1,"why":"A freehand clipper technique is commonly used to shape curlier-textured beards.","t":"Beard Trimming"},{"q":"What first step regulated the barbering profession in the late 1800s?","c":["Establishment of barber schools","Formation of barber groups","Passing of a barber-licensing law","Separation from medicine and religion"],"a":1,"why":"The formation of barber groups was the first step in regulating the barbering profession in the late 1800s.","t":"History & Licensing"},{"q":"Which of the following best describes the role of a cell's nucleus?","c":["To protect the cell's interior","To provide structure for cell parts","To combine simple molecules to form complex ones","To control the cell's growth and reproduction"],"a":3,"why":"The nucleus controls the cell's growth and reproduction.","t":"Anatomy & Physiology"},{"q":"What should you do if you have a conflict with a coworker on the job?","c":["You should be willing to resolve the conflict.","You should be willing to leave the conflict unresolved.","You should be willing to escalate the conflict if necessary.","You should be willing to discuss the conflict with others who are not involved."],"a":0,"why":"When there is a conflict at work, be willing to resolve it in a professional way.","t":"Professional Practice"},{"q":"Which technique is used in the curly method?","c":["Palm coiling","Raking","Finger coiling","Twisting"],"a":1,"why":"Raking is a technique used in the curly method.","t":"Hair Design"},{"q":"A condition that prohibits certain treatments is called a ______.","c":["cathode","catalyst","contraindication","conductor"],"a":2,"why":"A contraindication is a condition that prohibits certain treatments.","t":"Consultation"},{"q":"What part of the curl gives hair direction and mobility?","c":["Its base","The curl itself","Its stem","The circle"],"a":2,"why":"The stem of the curl gives hair its direction and mobility.","t":"Hair Design"},{"q":"What should be done after combing a subsection into position during the haircutting process?","c":["Cut the subsection immediately.","Comb the subsection again.","Transfer the comb to the other hand.","Leave the comb in the dominant hand."],"a":2,"why":"After combing a subsection into position, transfer the comb to the other hand so the shears can cut.","t":"Haircutting"},{"q":"Which of the following is an essential set of benchmarks that, once achieved, helps you to realize your mission and your vision?","c":["Goals","Statements","Objectives","Policies"],"a":0,"why":"Goals are the benchmarks that, once achieved, help you realize your mission and vision.","t":"Professional Practice"},{"q":"What is the proper way to hold the clipper determined by?","c":["The barber's personal preference","The clipper style","The section of the head being cut","The length of the hair"],"a":2,"why":"How you hold the clipper depends on the section of the head being cut.","t":"Implements & Equipment"},{"q":"Which of the following is a predisposition for acne?","c":["Diet","Heredity and hormones","Exercise","Climate"],"a":1,"why":"Heredity and hormones are predispositions for acne.","t":"Skin Disorders"},{"q":"What causes scabies?","c":["Bacteria","Fungus","Mites","Virus"],"a":2,"why":"Scabies is caused by a mite that burrows into the skin.","t":"Parasites & Fungi"},{"q":"What type of brush is recommended for straight-to-wavy hair during the shampoo and conditioning service?","c":["A wide-tooth comb","A cushion brush","A brush with natural bristles","A tangle teaser"],"a":2,"why":"A brush with natural bristles is recommended for straight-to-wavy hair during shampooing and conditioning.","t":"Shampoo & Scalp Care"},{"q":"What is the most significant extrinsic factor that impacts skin aging?","c":["Dry air","Poor nutrition","The sun's ultraviolet (UV) light","Lack of exercise"],"a":2,"why":"The sun's ultraviolet (UV) light is the most significant extrinsic factor in skin aging.","t":"Skin Disorders"},{"q":"Which appliance is used in barbershops to transmit vibrations to the client's skin and muscles?","c":["Electric massager","Rotary brush","Hot towel cabinet","Microdermabrasion machine"],"a":0,"why":"An electric massager transmits vibrations to the client's skin and muscles.","t":"Implements & Equipment"},{"q":"What is the study of bones called?","c":["Cardiology","Dermatology","Osteology","Neurology"],"a":2,"why":"Osteology is the study of bones.","t":"Anatomy & Physiology"},{"q":"How should a barber stand or sit when working with shears during a haircut?","c":["To the left of the cut area","On the client's side","Behind the client","In front of the cut area, hands positioned right"],"a":3,"why":"Stand or sit in front of the cut area with your hands positioned correctly for the shears.","t":"Haircutting"},{"q":"What is the primary basis for determining skin type?","c":["Client's age and lifestyle","Amount of oil produced and lipids between cells","Number of visible pores on the skin","Frequency of acne breakouts"],"a":1,"why":"Skin type is based mainly on how much oil is produced and the lipids between the cells.","t":"Skin Care & Facials"},{"q":"What is the first step toward achieving overall skin health?","c":["Getting a facial massage weekly","Visiting a dermatologist monthly","Starting a regular skin care regimen","Applying sunscreen when outdoors only"],"a":2,"why":"Starting a regular skin care regimen is the first step toward overall skin health.","t":"Skin Care & Facials"},{"q":"What percentage of your body weight is made up by muscles?","c":["40 to 50 percent","60 to 70 percent","10 to 20 percent","20 to 30 percent"],"a":0,"why":"Muscles make up about 40 to 50 percent of body weight.","t":"Anatomy & Physiology"},{"q":"What is the natural hair movement?","c":["An interest in using only organic hair products","A recent trend","A style using chemicals to alter hair texture","A style avoiding chemicals to maintain natural hair"],"a":3,"why":"The natural hair movement is a style that avoids chemicals to maintain natural hair.","t":"Hair Design"},{"q":"What is facial massage?","c":["A skin pore-cleansing method","An art of applying makeup","Manual or mechanical face and neck manipulation","A way to remove excess sebum"],"a":2,"why":"Facial massage is the manual or mechanical manipulation of the face and neck.","t":"Skin Care & Facials"},{"q":"What is the key difference between base relaxers and no-base relaxers?","c":["The pH level","The use of a protective base cream","The active ingredient","The need for product mixing before application"],"a":1,"why":"Base relaxers require a protective base cream before application, while no-base relaxers do not.","t":"Chemical Texture"},{"q":"What are the two techniques that are used to build a cushion or base in the hair?","c":["Backcombing and frontcombing","Teasing and rolling","Backcombing and backbrushing","Brushing and combing"],"a":2,"why":"Backcombing and backbrushing are the two techniques used to build a cushion or base in the hair.","t":"Hair Design"},{"q":"What is inflammation?","c":["A type of skin infection","A contagious disease","A biological defense mechanism","Specific to eczema"],"a":2,"why":"Inflammation is the body's biological defense mechanism against injury or irritation.","t":"Skin Disorders"},{"q":"Why must disposable gloves be worn during a relaxer service?","c":["To prevent skin damage","To enhance tool grip","To keep hands clean","To quicken the process"],"a":0,"why":"Disposable gloves protect the skin from damage by relaxer chemicals.","t":"Chemical Texture"},{"q":"Which type of thermal iron is manually wrapped around the hair?","c":["Marcel iron","Spring iron","Clamp-free iron","Flat iron"],"a":2,"why":"A clamp-free iron has no clamp, so the hair is wrapped around the barrel by hand.","t":"Thermal Services"},{"q":"What is the difference between dry scalp and dandruff?","c":["Dry scalp lacks moisture, while dandruff has excess.","Dry scalp has excess oil, while dandruff lacks moisture.","Dry scalp lacks moisture, while dandruff has excess oil.","Dry scalp and dandruff have the same causes."],"a":2,"why":"Dry scalp lacks moisture, while dandruff involves excess oil and flaking.","t":"Shampoo & Scalp Care"},{"q":"What is the cause of a verruca?","c":["Exposure to the sun","Changes in the skin due to aging","Repeated pressure or friction on the skin","A virus"],"a":3,"why":"A verruca (wart) is caused by a virus.","t":"Skin Disorders"},{"q":"Which component of hair structure is responsible for its strength and elasticity and contains the natural pigment melanin that determines hair color?","c":["Medulla","Cuticle","Cortex","The root"],"a":2,"why":"The cortex gives hair its strength and elasticity and contains melanin, which determines hair color.","t":"Hair Color"},{"q":"What is a benefit of root-turning the hair strands in hair systems?","c":["Minimizes tangling and matting","Increases resistance to damage","Eases blending of different hair types","Makes the hair easier to clean"],"a":0,"why":"Root-turning keeps the cuticle direction aligned, which minimizes tangling and matting.","t":"Hairpieces & Wigs"},{"q":"Which product is used to prepare the hair before every thermal-style service?","c":["Styling cream","Setting lotion","Heat protectants","Dry shampoo"],"a":2,"why":"Apply a heat protectant to the hair before every thermal-style service.","t":"Thermal Services"},{"q":"What is one tip for styling hair loss at the sides of the widow's peak?","c":["Cutting the hair shorter at the sides","Directing the hair toward hairless areas","Styling the hair away from the hairline","Using heavy shine products"],"a":1,"why":"Direct the hair toward the hairless areas to help cover thinning at the sides of the widow's peak.","t":"Hairpieces & Wigs"},{"q":"What does razor temper refer to?","c":["The ease of using the razor","The balance of the razor","The hardness of the razor","The angle of the razor blade"],"a":2,"why":"Razor temper refers to the hardness of the razor's steel.","t":"Implements & Equipment"},{"q":"What is the result if there is improper saturation of haircolor or lightener?","c":["The color becomes brighter","The hair becomes smoother","The application becomes uneven","The color lasts longer"],"a":2,"why":"Improper saturation causes uneven application of haircolor or lightener.","t":"Hair Color"},{"q":"How should the direction of massage movements be determined for clients with facial hair?","c":["Align with beard growth direction","Upward","Avoid performing a massage in the beard area","Direction doesn't matter"],"a":0,"why":"Direct the massage movements to follow the direction of beard growth.","t":"Skin Care & Facials"},{"q":"What is the technique called where a blowdryer is used to dry and style damp hair in one operation?","c":["Air-drying","Hood drying","Blowdry styling","Scrunch styling"],"a":2,"why":"Blowdry styling uses a blowdryer to dry and style damp hair in one operation.","t":"Thermal Services"},{"q":"What factors determine the lightening processing time?","c":["The client's age and the type of hair","The haircolor used and brand of the haircolor product","The hair's tone and curl pattern","The experience of the barber and barbershop rules"],"a":2,"why":"The hair's tone and curl pattern are factors that determine lightening processing time.","t":"Hair Color"},{"q":"Why are changeable-blade razors used in barbershops?","c":["They maintain infection control.","They are cheaper.","They provide a closer shave.","They are easier to find."],"a":0,"why":"Changeable-blade razors are used to maintain infection control, because a fresh blade is used for each client.","t":"Implements & Equipment"},{"q":"Why is it important for a barber to analyze the client's skin before beginning the shave?","c":["To choose the right shaving cream","To decide the price of the service","To choose the right razor blade","To ensure that the client does not have a skin infection or pustules"],"a":3,"why":"Analyze the skin first to make sure the client has no skin infection or pustules, which would be a contraindication for shaving.","t":"Shaving"},{"q":"What is a characteristic of permanent facial haircolor?","c":["It fades quickly.","It requires frequent touch-ups due to hair growth.","It softens the hair cuticle.","It defines edge-ups or accent lines."],"a":1,"why":"Permanent facial haircolor needs frequent touch-ups because the hair keeps growing.","t":"Beard Trimming"},{"q":"What is the function of end papers in a perm service?","c":["To dry the hair","To curl the hair","To apply perm solution","To control the hair's ends when winding"],"a":3,"why":"End papers control the hair ends when winding a perm rod.","t":"Chemical Texture"},{"q":"What does the longevity of a hair system depend on?","c":["Fit","Care","Price","Brand"],"a":1,"why":"The longevity of a hair system depends on how well it is cared for.","t":"Hairpieces & Wigs"},{"q":"What should be applied around the hairline, neck, and ears before a perm service?","c":["Water","Protective cream","Shampoo","Perm solution"],"a":1,"why":"Apply protective cream around the hairline, neck, and ears to keep perm solution off the skin.","t":"Chemical Texture"},{"q":"What is a key advantage of using human hair in hair systems?","c":["Cheaper than synthetic hair","Natural look and chemical process tolerance","Low maintenance for styling","Resistance to climate changes"],"a":1,"why":"Human hair gives a natural look and tolerates chemical processes such as coloring.","t":"Hairpieces & Wigs"},{"q":"What can contribute to the differences in texture and color between scalp hair and facial hair?","c":["Sunlight","Hair products","Genetics and the medulla","Weather conditions"],"a":2,"why":"Genetics and the medulla can contribute to differences in texture and color between scalp hair and facial hair.","t":"Beard Trimming"},{"q":"What is the role of the arrector pili muscles?","c":["To regulate sweat glands","To produce hormones","To filter blood","To cause \"goosebumps\""],"a":3,"why":"The arrector pili muscles contract and pull the hair upright, causing \"goosebumps.\"","t":"Anatomy of Skin & Hair"},{"q":"Why is it important never to stop learning about the beauty and wellness industry?","c":["Because you will always be required to attend classes.","Because formal schooling will always be a part of your career.","Because throughout your career there will be tests and quizzes.","Because the beauty and wellness industry never stops changing."],"a":3,"why":"The beauty and wellness industry never stops changing, so professionals keep learning for their whole careers.","t":"Professional Practice"},{"q":"Which of the following is a nonsurgical alternative for hair replacement?","c":["Using cover-up hair fibers","Applying scalp reduction methods","Conducting hair transplants","Performing flap surgery"],"a":0,"why":"Cover-up hair fibers are a nonsurgical option for hair replacement, unlike transplants, flap surgery, or scalp reduction.","t":"Hairpieces & Wigs"},{"q":"What indicated social status in ancient Greece?","c":["Long hair","Well-trimmed beards","Tattoos","The tonsure"],"a":1,"why":"In ancient Greece, well-trimmed beards were a sign of social status.","t":"History & Licensing"},{"q":"What should be avoided to prevent damage to hair systems?","c":["Using a wide-tooth comb","Wringing out cleaning fluids","Using manufacturer's care products","Taking precise measurements"],"a":1,"why":"Wringing out cleaning fluids can damage a hair system, so squeeze or blot it gently instead.","t":"Hairpieces & Wigs"},{"q":"On the job, punctuality is ______.","c":["an important part of personal hygiene","unimportant if all else is in line","a professional responsibility","at the discretion of the employee"],"a":2,"why":"Punctuality is a professional responsibility, because clients and coworkers depend on your time.","t":"Professional Practice"},{"q":"SDS are designed for ______.","c":["use in an emergency","use only by new employees","use only by managers","everyday use"],"a":0,"why":"Safety Data Sheets (SDS) give emergency information, such as first aid and spill response, for chemicals.","t":"Chemical Safety"},{"q":"What is the first step in creating a successful haircolor that delivers the client's desired result?","c":["Mixing colors randomly","Applying the color immediately","Haircolor formulation","Choosing the cheapest color"],"a":2,"why":"Haircolor formulation is the first step, because the formula determines the result the client wants.","t":"Hair Color"},{"q":"How many types of melanin does the body produce?","c":["Four","Three","Two","One"],"a":2,"why":"The body produces two types of melanin: eumelanin and pheomelanin.","t":"Anatomy of Skin & Hair"},{"q":"How should you prepare the client's facial hair for the shave?","c":["Apply cream but no towel.","Use cold towels and lather.","Use warm towels and lather.","Just wet the face with water."],"a":2,"why":"Warm towels and lather soften the hair and open the follicles, which prepares the beard for the shave.","t":"Shaving"},{"q":"What is the first step to a successful haircoloring service?","c":["Applying the haircolor","Measuring the haircolor and developer","Consultation and formulation","Mixing the haircolor and developer"],"a":2,"why":"Every successful haircoloring service starts with a consultation and formulation.","t":"Hair Color"},{"q":"What should be done with products that have touched infected eyes?","c":["Reused after a day","Washed with soap and water","Thrown away","Stored separately"],"a":2,"why":"Products that have touched infected eyes must be thrown away to prevent spreading infection.","t":"Skin Disorders"},{"q":"What is the function of melanocytes in the skin?","c":["To produce skin pigment called melanin","To form a barrier to protect underlying tissues","To produce new skin cells","To cause goosebumps"],"a":0,"why":"Melanocytes produce the skin pigment called melanin.","t":"Anatomy of Skin & Hair"},{"q":"Acid-alkali neutralization reactions occur when an acid is mixed with an alkali in equal proportions, balancing the total pH and forming water (H2O) and ______.","c":["a salt","nitrogen","carbon dioxide","a sulfur"],"a":0,"why":"When an acid and an alkali neutralize each other, they form water and a salt.","t":"Chemistry & Electricity"},{"q":"What type of pigmentation disorder is usually caused by cumulative sun exposure or aging?","c":["Nevus","Stain","Lentigines","Chloasma"],"a":3,"why":"Chloasma is a pigmentation disorder, with increased pigment in patches, linked to cumulative sun exposure or aging.","t":"Skin Disorders"},{"q":"What should you do if clients arrive late and you have the time to take the appointment without jeopardizing other appointments?","c":["Politely tell the clients you can no longer accept their business.","Ask the clients to reschedule anyhow.","Politely advise the clients of the late policy.","Provide the clients with services without mentioning their tardiness."],"a":2,"why":"If you have time to take the late client, politely advise them of the late policy and then provide the service.","t":"Professional Practice"},{"q":"What position should the top or front blade of the clipper be in relative to the back blade?","c":["Above the back blade","At least 1 inch below the back blade","Between 1/16 and 1/32 inches below the back blade","Flush with the back blade"],"a":2,"why":"The top blade sits between 1/16 and 1/32 inch below the back blade for a clean, safe cut.","t":"Haircutting"},{"q":"Because of ______, the human body is able to resist and destroy pathogens and respond to infection.","c":["tolerance","immunity","safety","toxicity"],"a":1,"why":"Immunity is the body's ability to resist and destroy pathogens and respond to infection.","t":"Infection Control"},{"q":"What does the level system in professional haircoloring measure?","c":["The level of hair damage","The intensity of the hair color","The lightness or darkness of hair color","The level of hair hydration"],"a":2,"why":"The level system measures how light or dark a hair color is.","t":"Hair Color"},{"q":"Which of the following is a razor safety tip?","c":["Always use a dull blade.","Cut dry hair with a razor.","Force the razor through the hair.","Always use a guard when working with a razor."],"a":3,"why":"Always use a guard when working with a razor.","t":"Haircutting"},{"q":"Which of the following is TRUE of sterilization?","c":["It is usually mandated in the beauty and wellness industry.","It is the first step in defense against the spread of disease.","It destroys all microbial life except for spores.","It destroys all microbial life, including spores."],"a":3,"why":"Sterilization destroys all microbial life, including spores.","t":"Infection Control"},{"q":"What is one of the risks associated with cutting past the second knuckle when cutting hair?","c":["Increased risk of skin cuts","Unevenness in the haircut","Dulling of the shears","Discomfort for the client"],"a":0,"why":"Cutting past the second knuckle makes it hard to control the shears, which raises the risk of skin cuts.","t":"Haircutting"},{"q":"Which of the following destroys all microbial life?","c":["Sterilization","Disinfection","Sanitization","Cleaning"],"a":0,"why":"Sterilization is the only level of decontamination that destroys all microbial life.","t":"Infection Control"},{"q":"When preparing your professional resume, avoid ______.","c":["making it longer than one page","including your name, address, and phone number","including your email address","listing your skills and accomplishments"],"a":0,"why":"A resume should not be longer than one page, so it stays focused and easy to read.","t":"Professional Practice"},{"q":"What type of draping is used for services such as haircoloring, permanent waves, or chemical hair relaxing?","c":["Wet draping","Shave service draping","Chemical service draping","Haircut draping"],"a":2,"why":"Chemical service draping is used for haircoloring, permanent waves, and relaxing, to protect the client from chemicals.","t":"Shampoo & Scalp Care"},{"q":"What is a solvent?","c":["A stable physical mixture of two or more substances","A substance that dissolves a solute and makes a solution","A substance dissolved into a solution","A liquid not capable of being mixed to form a stable solution"],"a":1,"why":"A solvent is the substance that dissolves a solute to make a solution.","t":"Chemistry & Electricity"},{"q":"What determines the shape of the hair strand?","c":["The amount of keratin in the hair","The shape of the hair follicle","The amount of melanin in the hair","The type of bond in the hair"],"a":1,"why":"The shape of the hair follicle determines the shape of the hair strand.","t":"Anatomy of Skin & Hair"},{"q":"What is a microorganism?","c":["Any infectious organism","Any living organism","Any plant-based organism","Any organism of microscopic size"],"a":3,"why":"A microorganism is any organism of microscopic size.","t":"Bacteria & Viruses"},{"q":"How should a barber perform a scalp massage?","c":["With mechanical movements","Without head contact","By manipulating the hair","By using deliberate motions"],"a":3,"why":"A scalp massage uses deliberate, controlled motions, not random or rough ones.","t":"Shampoo & Scalp Care"},{"q":"Which of the following is TRUE of pathogens?","c":["They all reside in the same places but infect humans in different ways.","They reside in different places, but all infect humans in exactly the same way.","They all reside in the same places and infect humans in exactly the same way.","They all reside in different places and affect humans in different ways."],"a":3,"why":"Pathogens live in different places and affect humans in different ways.","t":"Bacteria & Viruses"},{"q":"What is the primary benefit of a sulfate-free shampoo?","c":["It alters the shampoo's moisturizing content.","It adjusts the shampoo's pH level.","It is gentle on artificial haircolor.","It impacts the shampoo service's results."],"a":2,"why":"A sulfate-free shampoo is gentler on artificial haircolor, so color lasts longer.","t":"Shampoo & Scalp Care"},{"q":"What is the first phase of the hair growth cycle?","c":["Anagen phase","Catagen phase","Telogen phase","Melanogen phase"],"a":0,"why":"Anagen is the first phase of the hair growth cycle, when the hair actively grows.","t":"Anatomy of Skin & Hair"},{"q":"What technique involves coloring strands of hair darker than the natural color?","c":["Highlighting","Lowlighting","Foilayage","Pintura highlights"],"a":1,"why":"Lowlighting colors strands darker than the natural color.","t":"Hair Color"},{"q":"What are the two types of duct glands in the skin?","c":["Sweat glands and nervous glands","Sebaceous glands and sweat glands","Salivary glands and sebaceous glands","Sebaceous glands and nervous glands"],"a":1,"why":"The two types of duct glands in the skin are the sebaceous glands and the sweat glands.","t":"Anatomy of Skin & Hair"},{"q":"What is a crucial aspect of maintaining the hair system?","c":["Washing the system daily","Using the same hair products you were using on your own hair","Only making follow-up appointments when the hair system is damaged","Proper aftercare"],"a":3,"why":"Proper aftercare is a crucial part of maintaining a hair system.","t":"Hairpieces & Wigs"},{"q":"The presence of pus is a sign of ______.","c":["bacterial infection","inflammation","nonpathogenic organisms","contagious disease"],"a":0,"why":"Pus is a sign of bacterial infection.","t":"Bacteria & Viruses"},{"q":"How can resistant gray hair be treated to ensure complete coverage?","c":["By using a semipermanent haircolor","By pre-treating it","By using a lighter haircolor","By using a temporary haircolor"],"a":1,"why":"Pre-treating resistant gray hair opens the cuticle so the color can penetrate and give complete coverage.","t":"Hair Color"},{"q":"What are the two types of joints in the body?","c":["Flexible and immovable","Movable and flexible","Movable and immovable","Movable and semi-movable"],"a":2,"why":"The two types of joints are movable and immovable.","t":"Anatomy & Physiology"},{"q":"Which of the following is TRUE of the process of disinfection?","c":["It eliminates no microorganisms.","It eliminates a small number of microorganisms.","It eliminates most microorganisms.","It eliminates all microorganisms."],"a":2,"why":"Disinfection eliminates most microorganisms, but not all of them, and not bacterial spores.","t":"Infection Control"},{"q":"What is the cause of tinea?","c":["Bacteria","Mites","A fungal organism","Parasites"],"a":2,"why":"Tinea (ringworm) is caused by a fungal organism.","t":"Parasites & Fungi"},{"q":"OSHA defines PPE as ______.","c":["specialized clothing or equipment worn by an employee for protection against a hazard","guidelines that require the employee to assume that any human blood is potentially infectious","precautions that include proper hand washing and wearing of gloves around certain chemicals","items that should be cleaned and disinfected using any of the EPA-registered disinfectants"],"a":0,"why":"OSHA defines PPE as specialized clothing or equipment worn by an employee for protection against a hazard.","t":"Bloodborne Pathogens & OSHA"},{"q":"What is the primary function of the endocrine system?","c":["Making blood and oxygen available to body structures through respiration","Controlling hormone levels within the body","Protecting the body from disease","Eliminating waste from the body"],"a":1,"why":"The endocrine system controls hormone levels in the body.","t":"Anatomy & Physiology"},{"q":"Which of the following is an electrical safety device that is designed to prevent excessive current from passing through a circuit by blowing out or melting when a wire becomes too hot from overloading the circuit with too much current?","c":["A fuse","A circuit breaker","An ampere","A nonconductor"],"a":0,"why":"A fuse blows out or melts when too much current passes through the circuit, which prevents overheating.","t":"Chemistry & Electricity"},{"q":"Which hair disorder is characterized by the formation of nodular swellings along the hair shaft?","c":["Hypertrichosis","Trichoptilosis","Trichorrhexis nodosa","Canities"],"a":2,"why":"Trichorrhexis nodosa forms nodular swellings along the hair shaft.","t":"Hair & Scalp Disorders"},{"q":"What should be done with completed forms containing sensitive client information?","c":["Discard them after some time.","File them in a secure system.","Leave them on the consultation desk.","Share them for training purposes."],"a":1,"why":"Completed forms with sensitive client information should be filed in a secure system to protect privacy.","t":"Skin Care & Facials"},{"q":"What is the result of applying a thio relaxer over hair that has been treated with a hydroxide relaxer?","c":["Hair becomes straighter","Hair texture increases","Color of the hair changes","Hair loss occurs"],"a":3,"why":"Applying a thio relaxer over a hydroxide-relaxed head can cause severe damage and hair loss.","t":"Chemical Texture"},{"q":"What is the best way to record your tips and additional income?","c":["Enter them into a spreadsheet immediately after a client tips you.","Keep a daily log.","Keep a monthly log.","Guesstimate as best you can while you are preparing your annual taxes."],"a":1,"why":"Keeping a daily log of tips and extra income is the most accurate way to record it.","t":"Professional Practice"},{"q":"What do the colors of the barber pole represent?","c":["The French flag","Blood, bone, and hair","Fire, water, and air","Blood, veins, and bandages"],"a":3,"why":"The red, white, and blue of the barber pole represent blood, veins, and bandages.","t":"History & Licensing"},{"q":"What is a trigger point in massage therapy?","c":["A hypersensitive area within a muscle","Highest point of muscle tension","Muscle attachment point to bone","Midpoint between two muscles"],"a":0,"why":"A trigger point is a hypersensitive area within a muscle.","t":"Skin Care & Facials"},{"q":"What are the two common categories of chemical hair relaxers?","c":["Hydrochloric acid and ammonium chloride","Sodium hydroxide and potassium hydroxide","Hydroxide and ammonium thioglycolate (thio)","Hydrogen and disulfide bonds"],"a":2,"why":"The two common categories of chemical relaxers are hydroxide and ammonium thioglycolate (thio).","t":"Chemical Texture"},{"q":"How many types of tissues are there in the body?","c":["Two","Three","Four","Five"],"a":2,"why":"The body has four types of tissue: epithelial, connective, muscle, and nerve.","t":"Anatomy & Physiology"},{"q":"What should be done if a client calls to book an appointment with a particular barber on a particular day and time, but that barber is off that day?","c":["Politely apologize and tell the client you cannot accommodate them.","Call the barber and demand that they come in on their day off.","Suggest other times that the barber is available.","Refer the client to another business in the neighborhood."],"a":2,"why":"When the barber is off, suggest other times that the barber is available.","t":"Professional Practice"},{"q":"How should the razor be held for shaving?","c":["Thumb and two fingers on the shanks","Thumb at the bottom, fingers at the top","Thumb and fingers near the shank","Thumb and little finger on the tang"],"a":0,"why":"Hold the razor with the thumb and two fingers on the shanks for control.","t":"Implements & Equipment"},{"q":"After cutting and blending a full head bonded system, when can the client shampoo?","c":["Immediately","After a week","After 2 weeks","After 24 to 48 hours"],"a":3,"why":"Wait 24 to 48 hours before the client shampoos a newly bonded full head system.","t":"Hairpieces & Wigs"},{"q":"What factor determines the razor positions and strokes used during a shave?","c":["The direction of hair growth","The client's beard length","The client's skin type","The type of razor used"],"a":0,"why":"The direction of hair growth determines the razor positions and strokes used in a shave.","t":"Shaving"},{"q":"What is the definition of a \"position\" in barbering?","c":["The angle at which the razor cuts the hair","The movement of the razor","The type of razor used in barbering","The way the razor is held in the barber's hand"],"a":3,"why":"A \"position\" is the way the razor is held in the barber's hand.","t":"Shaving"},{"q":"What does the nervous system consist of?","c":["Brain, spinal cord, and nerves","Brain, liver, and kidneys","Spinal cord, lungs, and tarsals","Brain, heart, and nerves"],"a":0,"why":"The nervous system consists of the brain, spinal cord, and nerves.","t":"Anatomy & Physiology"},{"q":"How is acne graded?","c":["On a scale of 1 to 4","On a scale of 1 to 5","On a scale of 1 to 10","On a scale of 1 to 3"],"a":0,"why":"Acne is graded on a scale of 1 to 4.","t":"Skin Disorders"},{"q":"Which organ is responsible for keeping the blood moving within the circulatory system?","c":["Heart","Liver","Kidneys","Lungs"],"a":0,"why":"The heart keeps the blood moving within the circulatory system.","t":"Anatomy & Physiology"},{"q":"Which product adds a shiny or matte finish to the hair?","c":["Foam","Pomade","Serum","Volumizer"],"a":1,"why":"Pomade adds a shiny or matte finish to the hair.","t":"Hair Design"},{"q":"What should be provided between the client's head and the headrest?","c":["An additional cape","A clean cloth or paper","A warm, damp towel","Nothing"],"a":1,"why":"Place a clean cloth or paper between the client's head and the headrest for sanitation.","t":"Shaving"},{"q":"What does the \"E\" in the ABCDE of melanoma detection stand for?","c":["Edges","Elevation","Evolution","Exposure"],"a":2,"why":"In the ABCDE of melanoma detection, E stands for Evolution, meaning a spot that changes over time.","t":"Skin Disorders"},{"q":"What should a barber do if perm solution drips into a client's eye?","c":["Wipe it away with a tissue.","Apply an eye patch.","Apply a soothing eye cream.","Thoroughly flush the eye with cool water."],"a":3,"why":"If perm solution drips into a client's eye, flush the eye thoroughly with cool water right away.","t":"Chemical Texture"},{"q":"What is the process of texturizing in hairstyling?","c":["Removing excess hair bulk without shortening","Producing a long-layered look","Giving the appearance of highlights","Providing a close shave"],"a":0,"why":"Texturizing removes excess hair bulk without shortening the hair.","t":"Haircutting"},{"q":"What is the role of the dermal papilla in hair growth?","c":["Lubricates the hair and skin","Anchors the hair in the skin","Supplies nutrients to the hair","Causes the hair to stand up"],"a":2,"why":"The dermal papilla supplies nutrients to the hair.","t":"Anatomy of Skin & Hair"},{"q":"What does a graduated haircut result in?","c":["A single hanging level","Movement and volume","More volume to hairstyles","A visual buildup of weight"],"a":3,"why":"A graduated haircut results in a visual buildup of weight.","t":"Haircutting"},{"q":"What does the cortex of the hair provide?","c":["Shine","Protection","Strength","Medulla"],"a":2,"why":"The cortex provides strength to the hair.","t":"Anatomy of Skin & Hair"},{"q":"What are the three tests that should be conducted before beginning any perm service?","c":["Preliminary curl test, patch test, and strength test","Porosity test, elasticity test, and color test","Patch test, metallic salts test, and preliminary curl test","Metallic salts test, patch test, and drying test"],"a":2,"why":"Before any perm service, do a patch test, a metallic salts test, and a preliminary curl test.","t":"Chemical Texture"},{"q":"What is an autoimmune disorder that leads to hair loss in round or irregularly shaped patches?","c":["Alopecia areata","Hair shedding","Postpartum alopecia","Androgenic alopecia"],"a":0,"why":"Alopecia areata is an autoimmune disorder that causes hair loss in round or irregularly shaped patches.","t":"Hair & Scalp Disorders"},{"q":"Why is it essential to clean and disinfect pressing combs?","c":["To make them look shiny","To make them last longer","To make them easier to handle","To maintain efficiency and remove buildup"],"a":3,"why":"Pressing combs are cleaned and disinfected to maintain efficiency and remove buildup.","t":"Hair Design"},{"q":"Which of the following is a parasitic infection?","c":["Tinea","Dandruff","Scabies","Furuncles"],"a":2,"why":"Scabies is a parasitic infection caused by mites.","t":"Parasites & Fungi"},{"q":"What does \"palming the shears\" refer to?","c":["Holding shears with the palm","Using thumb and index finger only","Holding shears and comb simultaneously","Using nondominant hand to hold shears"],"a":2,"why":"\"Palming the shears\" means holding the shears and comb at the same time.","t":"Haircutting"},{"q":"What is the term for a very tight curl in hair terminology?","c":["Spiral","Coil","Loop","Zigzag"],"a":1,"why":"A very tight curl is called a coil.","t":"Thermal Services"},{"q":"What should you use to clean the barrel or plates of thermal irons?","c":["Soap and water","An abrasive substance","A damp cloth with water or rubbing alcohol","A dry cloth only"],"a":2,"why":"Clean the barrel or plates of thermal irons with a damp cloth and water or rubbing alcohol.","t":"Thermal Services"},{"q":"Which element in hair design can be fast or slow?","c":["Harmony","Proportion","Balance","Rhythm"],"a":3,"why":"Rhythm in hair design can be fast or slow.","t":"Hair Design"},{"q":"How long does it typically take for hair to fully loc?","c":["1 to 2 months","6 months to 1 year","2 to 3 weeks","3 to 4 years"],"a":1,"why":"Hair typically takes 6 months to 1 year to fully loc.","t":"Hair Design"},{"q":"Which of the following is a bacterial infection of the scalp?","c":["Tinea","Carbuncles","Scabies","Head lice"],"a":1,"why":"Carbuncles are a bacterial infection of the scalp.","t":"Hair & Scalp Disorders"},{"q":"How should the hair be lathered for shaving?","c":["In random directions","No specific direction","With the grain","Against the grain"],"a":3,"why":"Lather against the grain to lift the hairs so the razor can cut them cleanly.","t":"Shaving"},{"q":"What do reference points on the head mark?","c":["Changes in head's surface","Hair length","Hair texture","Hair type"],"a":0,"why":"Reference points mark the changes in the head's surface.","t":"Hair Design"},{"q":"What are two of the key factors a barber should consider when creating a facial design plan for a client?","c":["Bone structure and hair texture","The client's age and lifestyle habits","The client's facial features and clothing style","The client's current hairstyle and hair color"],"a":0,"why":"Bone structure and hair texture are two of the key factors in a facial design plan.","t":"Shaving"},{"q":"What should every barbershop service include?","c":["A client billing process","A detailed haircutting process","A client consultation","An extensive marketing plan"],"a":2,"why":"Every barbershop service should include a client consultation.","t":"Shampoo & Scalp Care"},{"q":"What is the proper angle to achieve a cutting stroke?","c":["45 degrees","90 degrees","60 degrees","30 degrees"],"a":3,"why":"A cutting stroke is achieved at a 30 degree angle.","t":"Shaving"},{"q":"Which finger should be placed in the finger grip of the still blade when holding haircutting shears?","c":["Ring finger","Thumb","Index finger","Middle finger"],"a":0,"why":"The ring finger goes in the finger grip of the still blade when holding haircutting shears.","t":"Implements & Equipment"},{"q":"What tool is typically used for beard trimming and design?","c":["A curling iron for stylizing","A hair straightener for creating smooth lines","A hairdryer for setting the style","Clippers"],"a":3,"why":"Clippers are the tool typically used for beard trimming and design.","t":"Implements & Equipment"},{"q":"What is one purpose of a deep-conditioning treatment?","c":["To help haircolor penetrate the cuticle layer","To straighten curly hair","To penetrate the cuticle with moisturizers","To increase the hair's pH level"],"a":2,"why":"A deep-conditioning treatment penetrates the cuticle with moisturizers.","t":"Shampoo & Scalp Care"},{"q":"What does microcurrent therapy do to aging skin?","c":["Peels off the top layer","Emits heat to stimulate collagen","Tones and lifts the skin","Rehydrates dry skin"],"a":2,"why":"Microcurrent therapy tones and lifts aging skin.","t":"Skin Care & Facials"},{"q":"What type of clamp or clip is used to secure heavy or thick sections of hair?","c":["Single-prong clip","Duckbill clip","Double-prong clip","Croc clamp"],"a":3,"why":"A croc clamp secures heavy or thick sections of hair.","t":"Hair Design"},{"q":"What mechanical exfoliation technique involves a hand-held device to loosen dead skin cells?","c":["Microneedling","Microdermabrasion","LED therapy","Enzyme peel"],"a":1,"why":"Microdermabrasion uses a hand-held device to loosen dead skin cells.","t":"Skin Care & Facials"},{"q":"What determines the chemical strength needed for the hair relaxer service?","c":["Client's current hairstyle","If the client has treated their hair with henna","Client's hair texture","Length of the client's hair"],"a":2,"why":"The client's hair texture determines the chemical strength needed for a relaxer service.","t":"Chemical Texture"},{"q":"If you perform one complete turn with your curling tool, what shape of curl will be created?","c":["C-shaped curl","Wave","Complete curl","Spiral curl"],"a":0,"why":"One complete turn of the curling tool creates a C-shaped curl.","t":"Hair Design"},{"q":"What should be done to a razor after use to maintain its quality?","c":["Placed in a humid environment","Stored without cleaning","Cleaned and stropped after use","Dropped to test its durability"],"a":2,"why":"Clean and strop the razor after use to maintain its quality.","t":"Implements & Equipment"},{"q":"What type of base is usually recommended at the side front hairline for a smooth, upswept effect when doing pin curls?","c":["Rectangular base","Arc-shaped base","Square-shaped base","Triangular-shaped base"],"a":0,"why":"A rectangular base gives a smooth, upswept effect at the side front hairline for pin curls.","t":"Hair Design"},{"q":"What is the purpose of dividing hair into panels before starting a perm wrap?","c":["To create an even curl formation","To predetermine the size of the perm rod","To minimize the risk of hair breakage during perm wrapping","To systematically organize the hair for perm wrapping"],"a":3,"why":"Dividing the hair into panels systematically organizes it for perm wrapping.","t":"Chemical Texture"},{"q":"Which of the following best describes the clipper-over-comb technique?","c":["It is used for creating long haircuts only.","It is used only on wet hair.","It allows close cutting to the scalp.","It requires the comb to be constantly moving."],"a":2,"why":"Clipper-over-comb allows close cutting to the scalp.","t":"Haircutting"},{"q":"Why should barbers understand different skin types?","c":["To suggest suitable home skin care routines","To sell more skin care products","To know which clients to turn away","To recommend the same skin care treatment to all clients"],"a":0,"why":"Understanding skin types lets barbers suggest suitable home skin care routines.","t":"Skin Care & Facials"},{"q":"What tool is commonly used for a temporary hair straightening process?","c":["Pressing comb","Blowdryer","Curling iron","Hair scissors"],"a":0,"why":"A pressing comb is commonly used for temporary hair straightening.","t":"Thermal Services"},{"q":"Which agent is used to achieve oxidation in the haircolor formula?","c":["Melanin","Ethanolamine","Hydrogen peroxide","Ammonia"],"a":2,"why":"Hydrogen peroxide is the agent used to achieve oxidation in the haircolor formula.","t":"Hair Color"},{"q":"What should never be used for coloring mustaches?","c":["Pomades","Beard filler pencils","Aniline-derivative tints","Semipermanent haircolor"],"a":2,"why":"Aniline-derivative tints should never be used to color mustaches.","t":"Shaving"},{"q":"What are the two basic lines used in haircutting?","c":["Curved and asymmetrical","Straight and asymmetrical","Straight and curved","Up-down and left-right"],"a":2,"why":"The two basic lines in haircutting are straight and curved.","t":"Haircutting"}],"cosmetologist":[{"q":"Which level of decontamination destroys all microbial life, including bacterial spores?","c":["Sterilization","Sanitation","Disinfection","Antisepsis"],"a":0,"why":"Sterilization is the only level that kills all microorganisms and spores. Sanitation and disinfection do not reach that level.","t":"Infection Control"},{"q":"Which product should be used to disinfect non-porous salon tools such as metal shears?","c":["Antibacterial hand soap","Witch hazel astringent","EPA-registered disinfectant","Scented room deodorizer"],"a":2,"why":"Non-porous implements are disinfected with an EPA-registered disinfectant used according to its label directions.","t":"Infection Control"},{"q":"A used emery board cannot be disinfected because it is porous. What should happen to it?","c":["It is wiped with alcohol","It is discarded after use on one client","It is stored in a UV cabinet","It is rinsed and air dried"],"a":1,"why":"Porous single-use items cannot be properly disinfected, so they are thrown away after one client.","t":"Infection Control"},{"q":"A disinfectant label lists a contact time. What does that term mean?","c":["How long the mixed solution stays potent","How long to rinse tools after soaking","The shelf life of the unopened product","How long a surface must stay wet with it"],"a":3,"why":"Contact time is the period a surface must remain visibly wet with the disinfectant for it to be effective.","t":"Infection Control"},{"q":"Which of the following is a bloodborne pathogen that can be spread by a contaminated razor?","c":["Tinea capitis","Pediculus capitis","Staphylococcus aureus","Hepatitis B virus"],"a":3,"why":"Hepatitis B virus is a bloodborne pathogen. Tinea capitis is a fungus and Pediculus capitis is a louse.","t":"Bloodborne Pathogens & SDS"},{"q":"A razor lightly nicks a client and the skin bleeds. Which response is correct?","c":["Wipe it with a towel and continue","Stop, clean the area and cover it with a bandage","Spray it with disinfectant and continue","Ask the client to hold pressure and continue"],"a":1,"why":"Stop the service, wear gloves, clean the injury and cover it, then properly discard or disinfect contaminated items.","t":"Bloodborne Pathogens & SDS"},{"q":"What information is found on a Safety Data Sheet (SDS)?","c":["Retail price and sales terms","A client's allergy history","Chemical hazards, safe handling and first aid","Employee training schedules"],"a":2,"why":"An SDS gives hazard, safe handling, storage and first-aid information for a chemical product.","t":"Bloodborne Pathogens & SDS"},{"q":"Which bacteria are round and grow in grape-like clusters, often causing boils and abscesses?","c":["Staphylococci","Streptococci","Diplococci","Spirilla"],"a":0,"why":"Staphylococci form grape-like clusters and are associated with boils and abscesses. Streptococci form chains.","t":"Microbiology"},{"q":"Which statement about viruses is true?","c":["They need a living host cell to reproduce","They are treated with antibiotics","They reproduce by binary fission","They are larger than most bacteria"],"a":0,"why":"Viruses are not cells and can only reproduce inside a living host. Antibiotics do not work against them.","t":"Microbiology"},{"q":"Ringworm (tinea) is caused by which type of microorganism?","c":["Virus","Bacterium","Fungus","Parasitic mite"],"a":2,"why":"Tinea infections are caused by fungi that live on keratin-rich tissue such as skin, hair and nails.","t":"Microbiology"},{"q":"Which layer of the hair shaft contains melanin and provides most of the hair's strength and elasticity?","c":["Cuticle","Cortex","Medulla","Hair bulb"],"a":1,"why":"The cortex is the middle layer. It holds the pigment and gives the hair its strength and elasticity.","t":"Trichology"},{"q":"Which phase of the hair growth cycle is the active growth phase?","c":["Telogen","Catagen","Exogen","Anagen"],"a":3,"why":"Anagen is the growth phase. Catagen is a short transition and telogen is a resting phase.","t":"Trichology"},{"q":"Which structure at the base of the follicle holds the blood and nerve supply that nourishes the growing hair?","c":["Arrector pili","Sebaceous gland","Sudoriferous gland","Dermal papilla"],"a":3,"why":"The dermal papilla fits into the hair bulb and supplies the nutrients needed for hair growth.","t":"Anatomy & Physiology"},{"q":"In which epidermal layer are new skin cells continually formed through cell division?","c":["Stratum corneum","Stratum germinativum","Stratum lucidum","Stratum granulosum"],"a":1,"why":"The stratum germinativum is the deepest epidermal layer, where mitosis produces new cells.","t":"Anatomy & Physiology"},{"q":"Which muscle of the scalp raises the eyebrows and draws the scalp forward?","c":["Occipitalis","Corrugator","Frontalis","Orbicularis oculi"],"a":2,"why":"The frontalis is the front portion of the epicranius. It raises the eyebrows and pulls the scalp forward.","t":"Anatomy & Physiology"},{"q":"Which cranial nerve is the chief sensory nerve of the face?","c":["Trigeminal (fifth)","Facial (seventh)","Accessory (eleventh)","Hypoglossal (twelfth)"],"a":0,"why":"The trigeminal nerve carries most facial sensation. The facial nerve is the chief motor nerve of the face.","t":"Anatomy & Physiology"},{"q":"On the pH scale, a change of one whole number represents how much change in acidity or alkalinity?","c":["Tenfold","Twofold","Fivefold","Hundredfold"],"a":0,"why":"The pH scale is logarithmic, so each whole number is a tenfold change in acidity or alkalinity.","t":"Chemistry & pH"},{"q":"Which pH range is closest to that of healthy skin and hair?","c":["7.0 to 8.0","8.5 to 9.5","4.5 to 5.5","1.0 to 3.0"],"a":2,"why":"Healthy skin and hair are slightly acidic, with a pH of about 4.5 to 5.5.","t":"Chemistry & pH"},{"q":"Which term describes a mixture of two immiscible substances, such as oil and water, joined with an emulsifier?","c":["Solution","Emulsion","Suspension","Compound"],"a":1,"why":"An emulsion combines two normally unmixable substances using an emulsifier. Creams and lotions are common examples.","t":"Chemistry & pH"},{"q":"Which device changes alternating current (AC) into direct current (DC)?","c":["Converter","Fuse","Circuit breaker","Rectifier"],"a":3,"why":"A rectifier converts AC to DC. A converter does the opposite and changes DC to AC.","t":"Electricity"},{"q":"What is the main purpose of a circuit breaker or fuse?","c":["Raise the voltage of a circuit","Convert AC to DC power","Store extra electricity for later","Stop current flow if a circuit overloads"],"a":3,"why":"These safety devices interrupt the flow of electricity when a circuit is overloaded, preventing overheating and fire.","t":"Electricity"},{"q":"Which unit measures the strength (rate of flow) of an electric current?","c":["Volt","Ampere","Ohm","Watt"],"a":1,"why":"The ampere measures current strength. A volt measures pressure, an ohm measures resistance and a watt measures power use.","t":"Electricity"},{"q":"Which ingredient is commonly added to skin and hair products as a humectant to attract water?","c":["Mineral oil","Isopropyl alcohol","Glycerin","Talc"],"a":2,"why":"Glycerin is a humectant. It draws moisture from the air and deeper skin layers to the surface.","t":"Product Ingredients"},{"q":"The 'head' of a surfactant molecule is hydrophilic. What does that mean?","c":["It is attracted to water","It is attracted to oil","It repels water","It dissolves in oil only"],"a":0,"why":"Hydrophilic means water-loving. The opposite, lipophilic, end of the molecule attaches to oil and dirt.","t":"Product Ingredients"},{"q":"How should a used razor blade be disposed of?","c":["In a puncture-resistant sharps container","In the regular trash can","Wrapped in a paper towel","In the sanitary hamper"],"a":0,"why":"Used blades are sharps. They go into a puncture-resistant, labeled container to protect people from injury and bloodborne exposure.","t":"Safety"},{"q":"What is the most effective way to prevent the spread of infection in a salon?","c":["Wearing a smock all day","Using hand lotion between clients","Washing hands with soap and water","Spraying fragrance in the room"],"a":2,"why":"Proper hand washing with liquid soap and running water is the single most effective infection-control measure.","t":"Infection Control"},{"q":"A disease that spreads from one person to another by direct or indirect contact is described as:","c":["Chronic","Contagious","Congenital","Seasonal"],"a":1,"why":"A contagious (communicable) disease is one that can be transmitted from person to person.","t":"Infection Control"},{"q":"Why should aerosol hairspray be stored away from heat?","c":["The fragrance will weaken","The nozzle will clog with rust","The product will separate into layers","The can can burst and the contents ignite"],"a":3,"why":"Aerosols are pressurized and many are flammable, so heat can cause a container to burst or ignite.","t":"Safety"},{"q":"An infection confined to one area of the body, such as a pimple or boil, is called:","c":["Systemic","Epidemic","Congenital","Local"],"a":3,"why":"A local infection stays in one body area. A systemic infection spreads through the bloodstream to the whole body.","t":"Microbiology"},{"q":"What is MRSA?","c":["A fungal infection of the scalp","A staph infection resistant to many antibiotics","A viral infection of the nail bed","A parasitic infestation of the hair"],"a":1,"why":"MRSA is methicillin-resistant Staphylococcus aureus, a bacterial infection that resists many common antibiotics.","t":"Microbiology"},{"q":"Which term describes cell reproduction by division into two identical cells?","c":["Metabolism","Catabolism","Mitosis","Anabolism"],"a":2,"why":"Mitosis is the process by which a cell divides into two identical daughter cells.","t":"Anatomy & Physiology"},{"q":"Hair is composed primarily of which protein?","c":["Keratin","Collagen","Elastin","Albumin"],"a":0,"why":"Hair, skin and nails are made largely of keratin, a tough fibrous protein.","t":"Trichology"},{"q":"A hair's ability to absorb moisture, determined by the condition of the cuticle, is called:","c":["Porosity","Density","Texture","Elasticity"],"a":0,"why":"Porosity describes how readily hair absorbs liquids and is affected by how open or damaged the cuticle is.","t":"Trichology"},{"q":"Which hair bonds are temporarily broken by water and heat and re-form as the hair dries in a new shape?","c":["Disulfide bonds","Peptide bonds","Hydrogen bonds","Lanthionine bonds"],"a":2,"why":"Hydrogen bonds are physical bonds broken by water or heat and re-formed as hair cools or dries, which is how wet sets and thermal styling work.","t":"Trichology"},{"q":"About how many hairs does a person normally shed each day?","c":["Fewer than 10","50 to 100","Around 250","More than 500"],"a":1,"why":"Losing roughly 50 to 100 hairs daily is a normal part of the growth cycle.","t":"Trichology"},{"q":"What is the best way to confirm you and a client agree on a desired haircolor or style?","c":["Choose the look that best suits your skills","Go by the client's current hair length","Start the service and adjust as you go","Review reference photos and restate the look"],"a":3,"why":"Reviewing photos and restating the look in your own words confirms shared expectations before the service begins.","t":"Consultation"},{"q":"A new client says she used box dye at home a month ago and now wants highlights. What is the best next step?","c":["Skip the strand test to save time","Apply lightener at full strength","Use a higher developer volume","Do a strand test and adjust your plan"],"a":3,"why":"Previous artificial color affects lift and results. A strand test shows how the hair will react before the full service.","t":"Consultation"},{"q":"Which type of shampoo is best for removing heavy product buildup and mineral deposits?","c":["Conditioning","Clarifying","Volumizing","Detangling"],"a":1,"why":"Clarifying shampoos contain stronger cleansing agents that remove buildup, minerals and residue.","t":"Shampoo & Scalp Care"},{"q":"Which massage movement uses light, gliding strokes and is used to begin and end a scalp massage?","c":["Tapotement","Petrissage","Effleurage","Vibration"],"a":2,"why":"Effleurage is a light, smooth, gliding movement that relaxes the client and is used to start and finish.","t":"Shampoo & Scalp Care"},{"q":"When hair is held straight out at 90 degrees from the head and cut, the result is:","c":["Uniform layers","A one-length blunt line","A stacked graduated line","Longer hair at the nape"],"a":0,"why":"Cutting at 90-degree elevation removes weight and creates uniform layers. Zero elevation produces a one-length form.","t":"Haircutting"},{"q":"Which haircut form is cut with no elevation (zero degrees), creating weight along the perimeter?","c":["Solid (one-length) form","Graduated form","Layered form","Increase-layered form"],"a":0,"why":"The solid form is cut at zero degrees. Hair falls to one length and weight builds up at the bottom edge.","t":"Haircutting"},{"q":"For best control and comfort, razor cutting is performed on hair that is:","c":["Completely dry and unwashed","Coated with styling wax","Damp and well detangled","Chemically relaxed"],"a":2,"why":"A razor glides best on damp, detangled hair. Dry or tangled hair is pulled and can cause discomfort.","t":"Haircutting"},{"q":"Before using a thermal iron on a client, how can you check that the temperature is safe?","c":["Touch it to your own wrist","Clamp it on a clean tissue or paper","Test on the client's nape hair","Wait until the indicator light turns red"],"a":1,"why":"Testing on clean tissue or paper shows whether the iron is too hot. If the paper scorches, let it cool first.","t":"Thermal Styling"},{"q":"A client with fine, damaged hair wants a flat-iron style. Which approach is best?","c":["Use the highest setting for speed","Press the same section repeatedly","Skip heat protectant on fragile ends","Use a lower temperature and heat protectant"],"a":3,"why":"Fine or damaged hair needs less heat. A lower setting and a protectant reduce the risk of further damage.","t":"Thermal Styling"},{"q":"In a pin curl, which part is the foundation area anchored to the scalp?","c":["Circle","Stem","Peak","Base"],"a":3,"why":"The base is the stationary foundation of a pin curl. The stem and circle extend from it.","t":"Wet Styling"},{"q":"Repeated tension from tight braids at the hairline can lead to which condition?","c":["Alopecia areata","Traction alopecia","Telogen effluvium","Trichorrhexis nodosa"],"a":1,"why":"Traction alopecia is hair loss caused by constant pulling on the follicles, such as from tight braids.","t":"Braiding & Updos"},{"q":"What is the main purpose of backcombing (teasing) hair before creating an updo?","c":["Remove tangles","Smooth the cuticle","Build volume and support","Increase hair elasticity"],"a":2,"why":"Backcombing builds a cushion of volume and grip that supports the shape of an updo.","t":"Braiding & Updos"},{"q":"In the hair color level system, which level represents black?","c":["Level 1","Level 3","Level 5","Level 10"],"a":0,"why":"Level 1 is the darkest level (black). The numbers increase toward the lightest blondes.","t":"Hair Color"},{"q":"As dark natural hair is lightened, which warm tones are exposed first?","c":["Red and orange","Yellow and pale yellow","Blue and violet","Gold and green"],"a":0,"why":"Dark hair contains red and orange underlying pigment that appears first. Yellow shows later at lighter levels.","t":"Hair Color"},{"q":"Which color on the color wheel neutralizes unwanted orange tones?","c":["Violet","Green","Blue","Yellow"],"a":2,"why":"Blue is opposite orange on the color wheel, so it neutralizes orange tones.","t":"Hair Color"},{"q":"What is the purpose of a predisposition (patch) test before using an aniline derivative tint?","c":["Determine the desired level of lift","Check for allergic sensitivity to the product","Measure the hair's porosity","Predict how long the color will last"],"a":1,"why":"The patch test checks whether the client is allergic to the tint so a reaction is avoided.","t":"Hair Color"},{"q":"A 20-volume developer is typically chosen when the goal is to lift hair by up to about:","c":["Six levels","Four levels","No levels","Two levels"],"a":3,"why":"Twenty-volume developer is the standard choice for up to about two levels of lift with permanent color.","t":"Hair Color"},{"q":"Which type of color deposits pigment without lift and is formulated to be used without a developer?","c":["Permanent color","Powder lightener","High-lift tint","Semi-permanent color"],"a":3,"why":"Semi-permanent color only deposits color on and in the outer hair and does not lift natural pigment.","t":"Hair Color"},{"q":"When lightening virgin hair, why is lightener applied to the area near the scalp last?","c":["That area is more porous","Scalp heat speeds up processing","That area has less melanin","It prevents lightener odor"],"a":1,"why":"Body heat from the scalp makes lightener process faster there, so it is applied last to avoid uneven results.","t":"Hair Lightening"},{"q":"A color retouch service applies color to which area?","c":["The entire hair length","Only the ends","Only the new growth","Only the midstrand"],"a":2,"why":"A retouch covers only the new growth at the scalp to avoid overlapping previously colored hair.","t":"Hair Color"},{"q":"Gray hair appears gray or white because it lacks:","c":["Melanin","Keratin","Sebum","Moisture"],"a":0,"why":"Gray hair has lost its melanin pigment. The cortex is no longer producing pigment.","t":"Hair Color"},{"q":"What does the neutralizer do in a permanent wave?","c":["Rebuilds the disulfide bonds in the new shape","Breaks the disulfide bonds","Raises the cuticle for processing","Removes hydrogen from the hair"],"a":0,"why":"Neutralizer oxidizes the hair, reforming the disulfide bonds in their new curled position.","t":"Perms & Relaxers"},{"q":"The main active ingredient in alkaline (cold) permanent waving solution is:","c":["Sodium hydroxide","Hydrogen peroxide","Ammonium thioglycolate","Calcium hydroxide"],"a":2,"why":"Ammonium thioglycolate is the reducing agent that breaks disulfide bonds in alkaline permanent waves.","t":"Perms & Relaxers"},{"q":"Before applying a hydroxide relaxer, what should be applied to the scalp and hairline for protection?","c":["Clarifying shampoo","Protective base cream","Neutralizing shampoo","Heated oil"],"a":1,"why":"A protective base cream shields the scalp and skin from the caustic relaxer.","t":"Perms & Relaxers"},{"q":"After rinsing a hydroxide relaxer, which step restores the hair to its normal pH and stops the relaxing action?","c":["Clarifying shampoo","Protein filler","Cool water rinse alone","Neutralizing (acid-balanced) shampoo"],"a":3,"why":"A neutralizing shampoo lowers the hair's pH back toward normal and stops the chemical action.","t":"Perms & Relaxers"},{"q":"Which extension method sews wefts of hair onto a track of braided natural hair?","c":["Fusion bonding","Tape-in application","Clip-in application","Track and sew weave"],"a":3,"why":"In a track-and-sew weave, the natural hair is braided into a track and the wefts are sewn on.","t":"Wigs & Extensions"},{"q":"Which wig type has individual hairs knotted by hand onto a fine mesh foundation?","c":["Capless wig","Hand-tied wig","Wefted wig","Clip-in topper"],"a":1,"why":"Hand-tied wigs have hairs knotted one by one so they look like they grow from the scalp.","t":"Wigs & Extensions"},{"q":"Why should you avoid using a curling iron on a standard synthetic wig?","c":["It makes the cap shrink","It permanently removes the color","The heat can melt the fibers","It makes the fibers tangle"],"a":2,"why":"Standard synthetic fibers are plastic-based and can melt or distort under heat, unlike heat-friendly fibers.","t":"Wigs & Extensions"},{"q":"Which term refers to dandruff?","c":["Pityriasis","Alopecia","Canities","Hypertrichosis"],"a":0,"why":"Pityriasis is the medical term for dandruff, which shows as scalp flaking.","t":"Scalp & Hair Disorders"},{"q":"While shampooing, you notice small white nits glued to the hair shafts close to the scalp. What should you do?","c":["Stop the service and recommend a physician","Finish and disinfect the comb afterward","Apply lightener to kill the nits","Cut the hair short and continue"],"a":0,"why":"Nits indicate head lice, which are contagious. Stop the service, avoid spread and refer the client for treatment.","t":"Scalp & Hair Disorders"},{"q":"Which condition is a contagious fungal infection of the scalp that may cause scaly patches and broken hairs?","c":["Pityriasis steatoides","Alopecia areata","Tinea capitis","Trichorrhexis nodosa"],"a":2,"why":"Tinea capitis is scalp ringworm, a contagious fungal infection. Affected clients should be referred to a physician.","t":"Scalp & Hair Disorders"},{"q":"Which condition causes sudden loss of hair in round or oval patches?","c":["Androgenic alopecia","Alopecia areata","Hypertrichosis","Canities"],"a":1,"why":"Alopecia areata is an autoimmune condition that causes sudden, patchy hair loss.","t":"Scalp & Hair Disorders"},{"q":"Trichoptilosis is the technical term for:","c":["Knotted hair","Beaded hair","Prematurely gray hair","Split ends"],"a":3,"why":"Trichoptilosis is the splitting of the hair end. Knotted hair is trichorrhexis nodosa.","t":"Scalp & Hair Disorders"},{"q":"Which factor most influences whether hair grows straight, wavy or curly?","c":["Sebum production","Hair color","Scalp pH","Shape of the follicle"],"a":3,"why":"Straight hair grows from round follicles, while flatter or curved follicles produce wavy and curly hair.","t":"Trichology"},{"q":"Which term describes the number of individual hairs per square inch on the scalp?","c":["Texture","Density","Elasticity","Porosity"],"a":1,"why":"Density is the number of hairs per square inch. Texture is the thickness of each strand.","t":"Consultation"},{"q":"Which comb is best for detangling wet, curly hair?","c":["Fine-tooth comb","Rattail comb","Wide-tooth comb","Teasing comb"],"a":2,"why":"A wide-tooth comb detangles with less stress and breakage than a fine-tooth comb, especially on wet curly hair.","t":"Shampoo & Scalp Care"},{"q":"Which technique uses the tips of the shears cut into the ends to soften a blunt line?","c":["Point cutting","Clipper-over-comb","Blunt cutting","Fade tapering"],"a":0,"why":"Point cutting snips into the ends to remove bulk and create a softer, textured edge.","t":"Haircutting"},{"q":"Which scalp treatment is most appropriate for a dry, flaking scalp that feels tight?","c":["A moisturizing scalp treatment","A clarifying shampoo daily","An alcohol-based astringent","A degreasing scalp scrub"],"a":0,"why":"A dry scalp lacks oil and moisture, so a moisturizing treatment is appropriate. Drying products would worsen it.","t":"Shampoo & Scalp Care"},{"q":"A client has natural level 5 hair and wants level 7 with permanent color. How many levels of lift are needed?","c":["Four levels","Three levels","Two levels","One level"],"a":2,"why":"The difference between level 5 and level 7 is two levels of lift.","t":"Hair Color"},{"q":"What is the purpose of applying a toner after lightening?","c":["Lift the hair two more levels","Neutralize or adjust unwanted undertones","Strengthen the hair's disulfide bonds","Remove residue from metallic salts"],"a":1,"why":"A toner deposits pigment to neutralize or refine the leftover warm undertones after lightening.","t":"Hair Lightening"},{"q":"What may happen if lightener is applied to hair that has been treated with a metallic dye?","c":["It lifts evenly with no change","The color becomes more vibrant","The dye washes out harmlessly","Hair may discolor, heat up or break"],"a":3,"why":"Metallic salts react with lightener and can cause discoloration, heat, odor and breakage. A strand test helps detect this.","t":"Hair Lightening"},{"q":"Why do cationic (positively charged) conditioning agents cling to damaged hair?","c":["Damaged hair is positively charged","Damaged hair is electrically neutral","Water repels cationic agents","Damaged hair has a negative charge"],"a":3,"why":"Damaged hair carries a negative charge, so positively charged conditioning agents are attracted to it.","t":"Product Ingredients"},{"q":"Which blow-dryer attachment concentrates airflow to smooth the cuticle for a sleek finish?","c":["Diffuser","Concentrator nozzle","Pick","Vent brush"],"a":1,"why":"A concentrator focuses airflow in a narrow stream, helping smooth the cuticle and create a sleek finish.","t":"Thermal Styling"},{"q":"A client has fresh cuts and abrasions on the scalp before a chemical service. What should you do?","c":["Apply base cream and proceed","Use a lower volume developer","Postpone the chemical service","Rinse with cold water and proceed"],"a":2,"why":"Chemicals can irritate broken skin and be absorbed, so the chemical service should be postponed until it heals.","t":"Safety"},{"q":"A wet strand stretches easily and does not return to its original length. This hair is most likely:","c":["Weak or damaged","Healthy and elastic","High in density","Coarse and resistant"],"a":0,"why":"Healthy hair stretches and springs back. Hair that stays stretched has poor elasticity and is weak or damaged.","t":"Consultation"},{"q":"Which skin type typically shows enlarged pores, a shiny surface and a tendency toward blackheads?","c":["Oily","Dry","Normal","Sensitive"],"a":0,"why":"Oily skin has overactive sebaceous glands, which cause shine, large pores and comedones.","t":"Skin Types"},{"q":"An open comedone, with a dark surface caused by oxidation, is commonly called a:","c":["Whitehead","Papule","Blackhead","Pustule"],"a":2,"why":"An open comedone is a blackhead. The dark color comes from oxidation of the sebum plug.","t":"Facial Treatments"},{"q":"What is the main purpose of exfoliation during a facial?","c":["Add oil to the skin","Remove dead surface cells","Close the pores permanently","Increase sebum production"],"a":1,"why":"Exfoliation removes dead cells from the stratum corneum, revealing smoother skin and helping products absorb.","t":"Facial Treatments"},{"q":"What does a sun protection factor (SPF) rating mainly measure?","c":["Protection from UVA only","Protection from infrared heat","Protection from visible light","Protection from UVB sunburn rays"],"a":3,"why":"SPF indicates how well a product protects against UVB rays, the main cause of sunburn.","t":"Skin Types"},{"q":"Which client should NOT receive waxing?","c":["A client with oily skin","A client who wears contact lenses","A client with normal skin","A client taking oral isotretinoin"],"a":3,"why":"Isotretinoin makes skin thin and fragile, so waxing can tear or lift it. It is a contraindication.","t":"Hair Removal"},{"q":"When using soft wax with muslin strips, how should the wax be applied and removed?","c":["Against growth, then pulled with growth","With growth, then pulled against growth","With growth, then pulled straight up","Against growth, then pulled upward"],"a":1,"why":"Soft wax is spread in the direction of growth and the strip is pulled back against growth, close to the skin.","t":"Hair Removal"},{"q":"Which concealer color is used to counteract redness?","c":["Yellow","Lavender","Green","Orange"],"a":2,"why":"Green is opposite red on the color wheel, so a green corrector neutralizes redness.","t":"Makeup"},{"q":"How should cream product be removed from a jar to avoid cross-contamination?","c":["With a clean disposable spatula","With a clean fingertip","With the brush used on the last client","With an applicator wiped on a tissue"],"a":0,"why":"A clean disposable spatula prevents bacteria from the artist's hands or tools from entering the container.","t":"Makeup"},{"q":"Which skin layer contains blood vessels, nerves, sweat glands and hair follicles?","c":["Dermis","Epidermis","Stratum corneum","Stratum lucidum"],"a":0,"why":"The dermis is the living layer beneath the epidermis. It houses vessels, nerves, glands and follicles.","t":"Skin Anatomy"},{"q":"A client has chronic redness, flushing and small bumps across the cheeks and nose. Which condition does this resemble?","c":["Milia","Vitiligo","Rosacea","Impetigo"],"a":2,"why":"These are classic signs of rosacea. Do not diagnose; suggest the client see a physician.","t":"Skin Disorders"},{"q":"In which part of the nail are new nail cells produced?","c":["Free edge","Matrix","Eponychium","Hyponychium"],"a":1,"why":"The matrix is where nail cells are formed. Damage to it can affect nail growth.","t":"Nail Structure"},{"q":"Which term describes the living skin at the base of the nail that overlaps the nail plate?","c":["Hyponychium","Lunula","Nail bed","Eponychium"],"a":3,"why":"The eponychium is the living skin at the base of the nail plate. The cuticle is the dead tissue on the plate.","t":"Nail Structure"},{"q":"A client's nail is thickened, discolored and crumbling, with debris beneath it. What is the best action?","c":["File it thinner and apply polish","Soak it and proceed as normal","Cover it with an acrylic overlay","Decline service and refer to a physician"],"a":3,"why":"These signs suggest a possible fungal infection. Do not service the nail; refer the client to a physician.","t":"Nail Disorders"},{"q":"How should natural nails be filed to reduce splitting?","c":["Using a back-and-forth sawing motion","From the sides toward the center","From the center toward the sides","In a circular motion at the tip"],"a":1,"why":"Filing in one direction from the sides toward the center reduces stress on the nail plate and splitting.","t":"Manicure & Pedicure"},{"q":"Between pedicure clients, a pedicure spa basin must be:","c":["Rinsed with water","Wiped with a dry towel","Cleaned and disinfected","Drained and left open"],"a":2,"why":"Footbaths must be cleaned and then disinfected with an EPA-registered disinfectant between clients.","t":"Nail Sanitation"},{"q":"Acrylic enhancements are formed when liquid monomer is mixed with:","c":["Polymer powder","Cyanoacrylate glue","Nail primer","Acetone"],"a":0,"why":"Acrylic nails form when liquid monomer and polymer powder combine and harden through polymerization.","t":"Nail Enhancements"},{"q":"Soak-off gel polish hardens when it is exposed to:","c":["UV or LED light","Open air only","Warm water","Nail primer"],"a":0,"why":"Gel polish cures only when exposed to a UV or LED lamp that triggers polymerization.","t":"Nail Enhancements"},{"q":"Redness, itching and swelling around the nails, with no pus or pain, appear after enhancement application. This suggests:","c":["Pterygium","Onychomycosis","Allergic contact dermatitis","Onycholysis"],"a":2,"why":"Redness, itching and swelling after exposure to enhancement products (monomer, primer, gel) suggest allergic contact dermatitis. Paronychia is a painful bacterial infection, often with pus, and onychomycosis is a fungal nail infection.","t":"Nail Disorders"},{"q":"Which term describes white spots or lines in the nail plate, often caused by minor injury?","c":["Onychauxis","Leukonychia","Melanonychia","Koilonychia"],"a":1,"why":"Leukonychia is white spots or lines in the nail, often caused by minor trauma to the matrix.","t":"Nail Disorders"},{"q":"Which product is most effective at dissolving acrylic nail enhancements?","c":["Non-acetone polish remover","Isopropyl alcohol","Nail primer","Acetone"],"a":3,"why":"Acetone breaks down acrylic and is used to soak off enhancements. Non-acetone remover is not strong enough.","t":"Nail Enhancements"}],"nailt":[{"q":"Which level of infection control destroys all microbial life, including bacterial spores?","c":["Sanitation","Sterilization","Disinfection","Antisepsis"],"a":1,"why":"Sterilization eliminates every form of microbial life, including spores. Salons typically use disinfection, which is a lower level of control.","t":"Infection Control & Safety"},{"q":"A metal nipper used on a client with intact skin must be processed before the next client. Which is correct?","c":["Wipe it with a dry paper towel, then store it in a drawer","Rinse it under running water, then let it air dry fully","Soak it in plain warm water for several minutes first","Wash it, then immerse it in EPA-registered disinfectant"],"a":3,"why":"Nonporous implements must be cleaned first, then fully immersed in an EPA-registered disinfectant for the full contact time on the label.","t":"Infection Control & Safety"},{"q":"A wooden-core emery board has been used on one client. What should you do with it?","c":["Discard it or give it to that client","Soak it in disinfectant overnight","Spray it with disinfectant and reuse it","Wipe it with alcohol and store it in a drawer"],"a":0,"why":"Porous items such as emery boards and buffers cannot be properly disinfected, so they are discarded or given to the client after one use.","t":"Infection Control & Safety"},{"q":"What does the contact time on a disinfectant label tell you?","c":["How long the mixed solution stays fresh","How long cleaned items can be stored afterward","How long the surface must stay wet with the solution","How long to rinse items after removing them"],"a":2,"why":"Contact time is the period an item must remain wet with the disinfectant to be effective against the organisms listed on the label.","t":"Infection Control & Safety"},{"q":"In the United States, which agency registers the disinfectants used on salon implements and surfaces?","c":["OSHA","FDA","EPA","CDC"],"a":2,"why":"The Environmental Protection Agency (EPA) registers disinfectants. OSHA enforces workplace safety rules such as SDS availability.","t":"Infection Control & Safety"},{"q":"Which document lists a product's hazards, safe handling, storage and first-aid measures?","c":["Safety data sheet (SDS)","Client consultation card","State board inspection report","Manufacturer's marketing brochure"],"a":0,"why":"The SDS, supplied by the manufacturer, explains hazards, handling, storage, disposal and first aid for a product. Salons must keep them available.","t":"Infection Control & Safety"},{"q":"Which of the following is a bloodborne pathogen?","c":["Tinea unguium","Pediculosis capitis","Pseudomonas aeruginosa","Hepatitis B virus"],"a":3,"why":"Hepatitis B virus, hepatitis C virus and HIV are spread through blood. The other choices are fungal, parasitic or bacterial conditions not spread this way.","t":"Infection Control & Safety"},{"q":"You accidentally nick a client with a nipper and the cut bleeds. What is the first thing you should do?","c":["Hand the client a tissue and continue the service","Put on gloves, stop the bleeding and clean the area","Rinse the nipper and finish the service","Apply polish over the cut to seal it"],"a":1,"why":"Protect yourself with gloves, stop the bleeding, then clean the injury and apply antiseptic. Any implement that contacted blood must be handled as contaminated.","t":"Infection Control & Safety"},{"q":"Which item belongs in a puncture-resistant sharps container?","c":["A used disposable razor blade","A used orangewood stick","A used cotton pad","A used metal cuticle pusher"],"a":0,"why":"Disposable blades are sharps and must go into a puncture-resistant container so no one is cut during disposal.","t":"Infection Control & Safety"},{"q":"Which practice best reduces your exposure to product vapors and dust during enhancement services?","c":["Leaving product containers open for faster work","Opening a window only after the service has ended","Capturing dust at the source and keeping containers closed","Spraying air freshener between each client's service"],"a":2,"why":"Capturing dust and vapors at the source and keeping containers capped limit inhalation exposure. Air fresheners only mask odors.","t":"Infection Control & Safety"},{"q":"A fungal infection that leaves the nail thick, discolored and crumbly is called:","c":["Onychia","Onychomycosis","Onychauxis","Onycholysis"],"a":1,"why":"Onychomycosis is a fungal infection of the nail plate. Because it is contagious, services on affected nails should be refused.","t":"Infection Control & Safety"},{"q":"Which bacterial form is spiral-shaped?","c":["Cocci","Bacilli","Staphylococci","Spirilla"],"a":3,"why":"Spirilla are spiral-shaped. Cocci are round and bacilli are rod-shaped.","t":"Infection Control & Safety"},{"q":"How often should disinfectant solution in a container be changed?","c":["Once a week regardless of how much it is used","Only when the container is completely empty","Once a month on a fixed calendar date","Per the label and whenever it looks cloudy or dirty"],"a":3,"why":"Follow the manufacturer's directions for mixing and replacement, and change the solution any time it becomes cloudy or visibly contaminated.","t":"Infection Control & Safety"},{"q":"Which action most effectively reduces the spread of pathogens between clients?","c":["Wearing the same gloves for every client","Washing hands with liquid soap and warm water","Wiping hands on a dry towel","Applying hand lotion before each client"],"a":1,"why":"Handwashing with liquid soap, warm water and friction before each client is the single most effective way to reduce the spread of pathogens.","t":"Infection Control & Safety"},{"q":"A green discoloration trapped between an enhancement and the natural nail is most often caused by:","c":["A reaction to the polish pigment used","Overexposure to the UV curing lamp","A vitamin deficiency in the client","A bacterial infection such as Pseudomonas"],"a":3,"why":"Green discoloration under a lifted enhancement is usually bacterial (Pseudomonas aeruginosa), not mold. The product should be removed and the client referred if it persists.","t":"Infection Control & Safety"},{"q":"The nail matrix is the part of the nail unit that:","c":["Produces the cells that become the nail plate","Attaches the plate to the tissue beneath it","Seals the area under the free edge","Forms the fold of skin around the nail sides"],"a":0,"why":"The matrix contains the living cells that divide, harden and form the nail plate. Damage to it can cause permanent nail deformities.","t":"Anatomy & Physiology"},{"q":"The tissue directly beneath the nail plate that supports it is the:","c":["Matrix","Nail bed","Eponychium","Hyponychium"],"a":1,"why":"The nail bed lies under the plate, supplies it with nutrients through blood vessels, and guides the plate as it grows forward.","t":"Anatomy & Physiology"},{"q":"The slightly thickened skin under the free edge that forms a protective seal is the:","c":["Hyponychium","Eponychium","Lunula","Nail wall"],"a":0,"why":"The hyponychium is the living skin beneath the free edge. It forms a barrier against bacteria entering the nail bed.","t":"Anatomy & Physiology"},{"q":"What is the term for the dead, colorless tissue that clings to the nail plate from the eponychium?","c":["Hyponychium","Perionychium","Pterygium","Cuticle"],"a":3,"why":"The cuticle is dead tissue stuck to the plate. The eponychium is the living skin at the base of the nail from which it extends.","t":"Anatomy & Physiology"},{"q":"The whitish half-moon at the base of the nail plate is called the:","c":["Matrix","Mantle","Lunula","Free edge"],"a":2,"why":"The lunula is the visible part of the matrix. It looks whitish because of how light reflects off the newly forming, not yet fully hardened cells.","t":"Anatomy & Physiology"},{"q":"The nail plate is made mostly of which protein?","c":["Collagen","Elastin","Keratin","Melanin"],"a":2,"why":"Nails, like hair and the outer skin layer, are composed mainly of keratin, a tough fibrous protein.","t":"Anatomy & Physiology"},{"q":"The bones that make up the fingers and toes are the:","c":["Carpals","Metacarpals","Tarsals","Phalanges"],"a":3,"why":"Phalanges are the finger and toe bones. Carpals form the wrist, metacarpals the palm, and tarsals the ankle region.","t":"Anatomy & Physiology"},{"q":"How many carpal bones make up the wrist?","c":["Eight","Five","Seven","Fourteen"],"a":0,"why":"The wrist contains eight carpal bones. Five metacarpals form the palm and fourteen phalanges form the fingers.","t":"Anatomy & Physiology"},{"q":"Muscles that spread the fingers or toes apart are called:","c":["Flexors","Abductors","Extensors","Adductors"],"a":1,"why":"Abductors draw a digit away from the midline of the hand or foot. Adductors pull them together.","t":"Anatomy & Physiology"},{"q":"Nerves that carry sensations such as touch and pain from the body to the brain are called:","c":["Motor nerves","Autonomic nerves","Efferent nerves","Sensory nerves"],"a":3,"why":"Sensory (afferent) nerves send information to the brain. Motor (efferent) nerves carry commands from the brain to muscles.","t":"Anatomy & Physiology"},{"q":"What is the outermost layer of the skin called?","c":["Epidermis","Dermis","Subcutis","Papillary layer"],"a":0,"why":"The epidermis is the thin outer protective layer of the skin. The dermis lies beneath it.","t":"Anatomy & Physiology"},{"q":"Which skin layer contains blood vessels, sweat glands, oil glands and nerve endings?","c":["Epidermis","Dermis","Stratum corneum","Stratum lucidum"],"a":1,"why":"The dermis is the deeper, living layer that houses vessels, glands, hair follicles and nerve endings.","t":"Anatomy & Physiology"},{"q":"Glands that produce sebum, the skin's natural oil, are called:","c":["Sudoriferous glands","Endocrine glands","Sebaceous glands","Lymph glands"],"a":2,"why":"Sebaceous (oil) glands secrete sebum that lubricates the skin. Sudoriferous glands produce sweat.","t":"Anatomy & Physiology"},{"q":"Why can the nail plate be trimmed without causing pain or bleeding?","c":["It has no nerves or blood supply of its own","It is made of oil-based cells that feel nothing","It is covered by a thick layer of natural sebum","It contains only moisture and almost no protein"],"a":0,"why":"The visible plate is dead keratin without nerves or blood vessels. Pain and bleeding come only from living tissue such as the nail bed.","t":"Anatomy & Physiology"},{"q":"Muscles that bend the wrist, fingers and toes are called:","c":["Extensors","Flexors","Pronators","Supinators"],"a":1,"why":"Flexors decrease the angle of a joint by bending it. Extensors straighten it.","t":"Anatomy & Physiology"},{"q":"A pH of 7 on the pH scale is considered:","c":["Acidic","Alkaline","Neutral","Caustic"],"a":2,"why":"Pure water has a pH of 7. Values below 7 are acidic and values above 7 are alkaline.","t":"Chemistry"},{"q":"On the pH scale, a change of one whole number represents:","c":["A twofold change","A fivefold change","A change of one percent","A tenfold change"],"a":3,"why":"The pH scale is logarithmic, so each whole number is a tenfold change in acidity or alkalinity.","t":"Chemistry"},{"q":"What is the chemical process called in which small molecules link to form long chains in an acrylic system?","c":["Oxidation","Evaporation","Polymerization","Saponification"],"a":2,"why":"Polymerization joins monomers into long polymer chains, which hardens the enhancement product.","t":"Chemistry"},{"q":"The small molecules in acrylic liquid that link together to form chains are called:","c":["Polymers","Monomers","Oligomers","Initiators"],"a":1,"why":"Monomers are single units. Linking many of them creates a polymer.","t":"Chemistry"},{"q":"Why is MMA (methyl methacrylate) monomer considered unsafe for nail enhancements?","c":["It bonds so strongly it can damage the nail and cause allergy","It never hardens enough to hold a shape on the nail","It cures only when exposed to ultraviolet lamp light","It is mostly water so it cannot bond to the nail"],"a":0,"why":"MMA creates an extremely hard product that adheres so strongly that removal can damage the nail plate. It can also cause allergic reactions.","t":"Chemistry"},{"q":"Which monomer is the standard used in professional acrylic liquids?","c":["Methyl methacrylate","Cyanoacrylate","Isopropyl alcohol","Ethyl methacrylate"],"a":3,"why":"Ethyl methacrylate (EMA) is the monomer used in professional acrylic liquid, and it is easier to remove than MMA.","t":"Chemistry"},{"q":"Which ingredient is the main component of nail adhesive (nail glue)?","c":["Methacrylic acid","Toluene","Ethyl acetate","Cyanoacrylate"],"a":3,"why":"Nail adhesive is made of cyanoacrylate, which bonds quickly when it contacts moisture on the nail surface.","t":"Chemistry"},{"q":"What causes UV or LED gel to harden?","c":["Evaporation of solvents into the air","Contact with oxygen on the nail surface","Photoinitiators reacting to the lamp's light","Mixing with a polymer powder and liquid"],"a":2,"why":"Light-cured gels contain photoinitiators that start polymerization when exposed to the proper wavelength of light.","t":"Chemistry"},{"q":"Which statement about methacrylic-acid primer is correct?","c":["It is harmless and needs no safety precautions","It is corrosive and can burn skin, so use sparingly","It dissolves artificial nails on contact","It is a neutralizer applied after buffing"],"a":1,"why":"Acid-based primer is corrosive and can burn skin and eyes. Apply a tiny amount only to the natural nail plate and avoid skin contact.","t":"Chemistry"},{"q":"A nail dehydrator is used mainly to:","c":["Remove surface oil and moisture from the plate","Soften and dissolve the cuticle tissue fully","Add shine to the finished enhancement surface","Speed up the curing of gel under the lamp"],"a":0,"why":"Dehydrators remove oils and moisture that would otherwise interfere with the adhesion of enhancement products.","t":"Chemistry"},{"q":"What is the main purpose of a client consultation card?","c":["To replace the need for disinfecting tools","To record health and service history for safe service","To confirm payment and tip amounts after service","To list the salon's price menu for the client"],"a":1,"why":"The consultation card records relevant health information, allergies and service history so the technician can deliver safe, appropriate services.","t":"Pre-Service Procedures"},{"q":"A client arrives with an open, weeping sore on a finger. What is the best course of action?","c":["Cover it with polish and continue as planned","Bandage it and complete the service as booked","Politely decline service and suggest a physician","Apply antiseptic and perform the service anyway"],"a":2,"why":"Open or infected skin is a contraindication. Decline service on that area and recommend a physician rather than risk spreading infection.","t":"Pre-Service Procedures"},{"q":"Which setup step is correct before each client arrives?","c":["Reuse the previous client's towel if it looks dry","Lay out unwashed tools you might need later","Skip hand washing until the service has begun","Disinfect the table and set out clean towels and tools"],"a":3,"why":"Each client needs a disinfected work surface, fresh linens and disinfected implements, with your hands washed before the service starts.","t":"Pre-Service Procedures"},{"q":"A client with diabetes books a pedicure. Which approach is the most appropriate?","c":["Avoid cuts and abrasions and skip aggressive callus work","Use a sharp blade to remove all calluses completely","Use very hot water to boost circulation in the feet","Trim the cuticle very closely to prevent infection"],"a":0,"why":"Diabetic clients may have reduced sensation and slow healing, so even small cuts can become serious. Use gentle techniques and avoid anything that could break the skin.","t":"Pre-Service Procedures"},{"q":"Which health-screening question is most relevant before an enhancement service?","c":["Do you have allergies to nail products or latex?","How long have you lived in your current city?","What kind of work do your relatives usually do?","Which salon did you visit before coming here?"],"a":0,"why":"Screening for allergies and sensitivities helps prevent reactions to monomers, adhesives, latex gloves and other materials.","t":"Pre-Service Procedures"},{"q":"Which file grit is the coarsest?","c":["240 grit","180 grit","150 grit","100 grit"],"a":3,"why":"Lower grit numbers mean coarser abrasives. A 100-grit file is rougher than 150, 180 or 240.","t":"Tools, Implements & Materials"},{"q":"A fine-grit abrasive such as 240 grit or higher is best used to:","c":["Remove bulk from thick acrylic quickly","Shorten the natural nail free edge fast","Refine the surface and remove file scratches","Strip off gel polish in a single pass"],"a":2,"why":"Fine abrasives smooth and polish the surface and remove scratches left by coarser files. Coarse files are for bulk reduction.","t":"Tools, Implements & Materials"},{"q":"To reduce splitting when filing natural nails, you should:","c":["Use a sawing motion back and forth quickly","File from the sides toward the center","Choose the coarsest file available to you","File downward underneath the free edge"],"a":1,"why":"Filing from the sides toward the center in one direction helps prevent splitting and layer separation at the free edge.","t":"Tools, Implements & Materials"},{"q":"A cuticle nipper is designed to:","c":["Push back the eponychium","Trim loose, dead tissue and hangnails","Cut away living tissue around the nail","Shorten the free edge of the nail"],"a":1,"why":"Nippers are used only to trim loose dead cuticle tissue and hangnails. Cutting living skin risks injury and infection.","t":"Tools, Implements & Materials"},{"q":"Which implement is used to gently loosen and push back softened cuticle?","c":["Nail clipper","Callus rasp","Wire brush","Cuticle pusher"],"a":3,"why":"A cuticle pusher, metal or wood, is used after softening to push back the cuticle from the plate.","t":"Tools, Implements & Materials"},{"q":"To prevent heat buildup and discomfort when using an e-file, you should:","c":["Hold the bit in one spot for control","Use heavy pressure at maximum speed","Keep the bit moving with light pressure","Use a worn bit to avoid cutting too fast"],"a":2,"why":"Keeping the bit moving with light pressure avoids heat buildup and thinning of the nail plate. A dull bit increases friction and heat.","t":"Tools, Implements & Materials"},{"q":"A nail form is used to:","c":["Support the product while an extension is sculpted","Replace the need for any nail preparation","Dissolve product from the surface of the nail","Hold polish in place while it fully dries"],"a":0,"why":"A sculpting form is placed under the free edge to support product while the extension is built, then removed.","t":"Tools, Implements & Materials"},{"q":"On a nail tip, the well is the area that:","c":["Forms the free-edge extension","Shows the smile line","Is adhered to the natural nail plate","Is cut away before application"],"a":2,"why":"The well is the contoured area at the top of the tip that overlaps and is adhered to the natural nail.","t":"Tools, Implements & Materials"},{"q":"Which hair is considered the highest quality for acrylic brushes?","c":["Kolinsky sable","Nylon","Horsehair","Boar bristle"],"a":0,"why":"Kolinsky sable holds liquid well and has good spring, which is why it is the traditional choice for quality acrylic brushes.","t":"Tools, Implements & Materials"},{"q":"Why are lint-free wipes preferred over cotton balls when cleansing the nail before an enhancement?","c":["They are more absorbent than cotton for polish","They leave no fibers to get trapped in the product","They contain a built-in disinfectant solution","They can be reused on the next client safely"],"a":1,"why":"Cotton can shed fibers that get trapped under the product and contribute to lifting and an uneven surface.","t":"Tools, Implements & Materials"},{"q":"A hand nail brush is used mainly to:","c":["Apply cuticle softener to the cuticle area","Blend acrylic beads into the nail surface","Dilute nail products before applying them","Remove debris from under the free edge and plate"],"a":3,"why":"A nail brush cleans dirt and debris from the nails and under the free edge. It must be disinfected or discarded between clients.","t":"Tools, Implements & Materials"},{"q":"Gel products must be cured in a lamp that:","c":["Matches the wavelength the gel was made for","Is the least expensive one available","Gives off the brightest visible white light","Provides heat so the gel solvents evaporate"],"a":0,"why":"Gel photoinitiators respond to specific wavelengths, so the lamp must be compatible with the product for a full cure.","t":"Tools, Implements & Materials"},{"q":"Which implement is appropriate for gently reducing calluses through friction?","c":["Cuticle nipper with a sharp jaw edge","Orangewood stick pushed under the callus","Abrasive foot file or foot paddle","Tweezers used to pull the dead skin"],"a":2,"why":"A foot file or paddle removes dead skin gradually through abrasion and does not cut skin. It must be discarded or disinfected as appropriate.","t":"Tools, Implements & Materials"},{"q":"In a basic manicure, which step comes first after your hands and the client's are washed?","c":["Apply base coat","Massage the hands","Push back the cuticles","Remove existing polish"],"a":3,"why":"Old polish is removed first so the nails can be shaped and cleaned. Base coat and massage come later.","t":"Manicure & Pedicure Services"},{"q":"The squoval nail shape is a combination of which two shapes?","c":["Round and pointed","Square and oval","Square and pointed","Oval and pointed"],"a":1,"why":"Squoval has a square free edge with softly rounded corners, which is strong and resistant to snagging.","t":"Manicure & Pedicure Services"},{"q":"What is the best way to mix nail polish without introducing bubbles?","c":["Shake the bottle vigorously","Stir it with an orangewood stick","Hold the bottle under hot water","Roll the bottle between your palms"],"a":3,"why":"Rolling gently mixes pigment without trapping air. Shaking creates bubbles that appear in the finished polish.","t":"Manicure & Pedicure Services"},{"q":"What is the correct order of a polish application?","c":["Color coat, base coat, top coat","Base coat, color coats, top coat","Top coat, color coat, base coat","Base coat, top coat, color coat"],"a":1,"why":"Base coat protects the nail and aids adhesion, thin color coats follow, and top coat seals and adds shine.","t":"Manicure & Pedicure Services"},{"q":"Applying polish in thick coats most often results in:","c":["Slow drying, bubbling or smudging","Faster drying and longer wear","Better adhesion to the nail","A stronger nail plate"],"a":0,"why":"Thick coats trap solvent, so they dry slowly and are prone to bubbles, smudges and dents. Thin coats dry more evenly.","t":"Manicure & Pedicure Services"},{"q":"Which massage movement is a kneading motion that lifts and squeezes the tissue?","c":["Effleurage","Friction","Petrissage","Tapotement"],"a":2,"why":"Petrissage is a kneading movement. Effleurage is light stroking, friction is circular pressure and tapotement is tapping.","t":"Manicure & Pedicure Services"},{"q":"Which massage movement uses light tapping or slapping?","c":["Effleurage","Tapotement","Petrissage","Vibration"],"a":1,"why":"Tapotement, or percussion, consists of short tapping or slapping movements. It is used sparingly in nail services.","t":"Manicure & Pedicure Services"},{"q":"Calluses most commonly develop because of:","c":["Repeated pressure or friction on the skin","A fungal infection of the foot","A bacterial infection under the nail","Excessive moisture in the shoe"],"a":0,"why":"A callus is a thickened area of skin that forms as protection against repeated pressure or friction.","t":"Manicure & Pedicure Services"},{"q":"Which description fits a corn?","c":["A viral growth found on the sole of the foot","A fluid-filled blister caused by friction","A thickened area of skin with a central core","A flat, dark discoloration under the skin"],"a":2,"why":"A corn is a small, concentrated area of thickened skin with a hard core. It is often painful and a client with one may need a podiatrist.","t":"Manicure & Pedicure Services"},{"q":"After each pedicure client, the foot spa basin should be:","c":["Rinsed with water and refilled right away","Wiped with a dry towel and left empty","Drained and left to air dry until needed","Drained, cleaned, then disinfected per label"],"a":3,"why":"Basins must be cleaned and disinfected between clients following the label's contact time to prevent cross-contamination.","t":"Manicure & Pedicure Services"},{"q":"Which condition should you refuse to service because it is contagious?","c":["Vertical nail ridges","White spots on the plate","Tinea pedis (athlete's foot)","Eggshell nails"],"a":2,"why":"Tinea pedis is a contagious fungal infection. Ridges, white spots and eggshell nails are not contagious and can generally be serviced with care.","t":"Manicure & Pedicure Services"},{"q":"Which statement describes onycholysis?","c":["The habit of biting the nails","A thickening of the nail plate","The growth of a nail into the skin","Separation of the plate from the nail bed"],"a":3,"why":"Onycholysis is the lifting of the plate from the bed, often due to injury, infection or reactions. The area should not be covered with product.","t":"Manicure & Pedicure Services"},{"q":"Habitual nail biting is known as:","c":["Onychorrhexis","Onychophagy","Onychatrophia","Onychocryptosis"],"a":1,"why":"Onychophagy is nail biting. Onychorrhexis is split nails, onychatrophia is wasting, and onychocryptosis is ingrown nails.","t":"Manicure & Pedicure Services"},{"q":"Beau's lines, which appear as horizontal depressions across the nail, are caused by:","c":["A temporary stop in matrix growth from illness or injury","Applying polish in too many thick coats over time","Using a coarse file along the edge of the nail","A bacterial infection of the tissue in the nail bed"],"a":0,"why":"Beau's lines form when growth at the matrix is disrupted by illness, injury or major stress. They grow out with the nail.","t":"Manicure & Pedicure Services"},{"q":"How should toenails be trimmed in a pedicure?","c":["Curved deeply down the sides of the toe","Cut short and shaped into a point","Rounded off to match the shape of the toe","Straight across with softened corners"],"a":3,"why":"Cutting straight across helps prevent ingrown toenails. Deep curves at the sides can cause the nail to grow into the skin.","t":"Manicure & Pedicure Services"},{"q":"Why should clients avoid shaving their legs just before a pedicure?","c":["Tiny nicks can let bacteria enter the skin","It dries out the nail plate right away","It prevents polish from adhering to the nail","It makes soaking the feet impossible to do"],"a":0,"why":"Shaving can cause microscopic cuts that create an entry point for bacteria in the foot bath or from tools.","t":"Manicure & Pedicure Services"},{"q":"What is the correct water temperature for a foot soak?","c":["Very hot to soften calluses faster","Ice cold to reduce the bacteria present","Comfortably warm and checked with client","Hot enough to turn the skin quite red"],"a":2,"why":"Water should be comfortably warm. Extremely hot water can burn skin, especially if the client has reduced sensation.","t":"Manicure & Pedicure Services"},{"q":"A paraffin wax treatment should NOT be given to a client who has:","c":["Dry, flaky skin","Cuts or sores on the hands","Brittle nails","Mild stiffness in the fingers"],"a":1,"why":"Paraffin must not be used over cuts, sores or infection, since heat and the wax can worsen the condition and spread pathogens.","t":"Manicure & Pedicure Services"},{"q":"Which bead consistency is ideal for most acrylic application?","c":["Medium, a smooth rounded bead that holds its shape","Very wet, with liquid running off the brush","Dry and crumbly with powder visible","Stiff and cracked on the surface"],"a":0,"why":"A medium bead has the right monomer-to-polymer balance so the product is workable, holds its shape and cures properly.","t":"Nail Enhancements"},{"q":"An acrylic bead that is too wet is most likely to cause:","c":["A brittle, crumbly finish on the surface","Flooding at the cuticle and increased lifting","Faster setting time than normal product","A milky white surface that is hard to file"],"a":1,"why":"Too much liquid makes the bead runny, causing flooding at the cuticle and sidewalls, a weaker product and lifting.","t":"Nail Enhancements"},{"q":"The stress area of a nail enhancement is located:","c":["At the cuticle edge of the plate only","At the sidewall of the nail only","Directly under the free edge itself","Where the plate meets the free edge"],"a":3,"why":"The stress area is where the plate and free edge meet. It takes the most pressure, so the product needs adequate thickness there.","t":"Nail Enhancements"},{"q":"The highest point of the arch of an enhancement, which adds strength, is called the:","c":["Cuticle line","Smile line","Apex","Sidewall"],"a":2,"why":"The apex is the highest point of the arch, positioned over the stress area for strength and balance.","t":"Nail Enhancements"},{"q":"The most common cause of enhancement lifting is:","c":["Excessive buffing of the enhancement surface","Using a fine-grit file on the surface","Poor prep leaving oil or moisture on the plate","Applying product in thin, even layers"],"a":2,"why":"Oils, moisture and debris prevent proper adhesion, so thorough prep is the best prevention for lifting.","t":"Nail Enhancements"},{"q":"What is the main purpose of a fill (rebalance)?","c":["To remove the entire enhancement from the nail","To fill regrowth space and restore the apex","To change the color of the whole nail","To shorten the length of the natural nail"],"a":1,"why":"A fill fills in regrowth space between the cuticle and the existing product and rebalances the arch.","t":"Nail Enhancements"},{"q":"In a dip powder system, the powder adheres to the nail because of:","c":["Heat given off by a curing lamp","Mixing with a bead of monomer liquid","Static electricity between the grains","A layer of resin or adhesive on the nail"],"a":3,"why":"Resin or base adhesive is applied to the nail, and the powder bonds to it. An activator then hardens the layer.","t":"Nail Enhancements"},{"q":"To prevent cross-contamination with dip powder, the technician should:","c":["Pour or brush powder over each finger, not into the jar","Dip each client's fingers into the same jar","Disinfect the shared powder with alcohol","Use the same open jar all day without covering it"],"a":0,"why":"Dipping fingers into a shared jar spreads pathogens, so powder is poured or brushed onto the nail over a catch tray.","t":"Nail Enhancements"},{"q":"Which technique is correct when applying a nail tip to avoid air bubbles?","c":["Slide it on flat and release immediately","Apply the glue to the free edge only","Press only at the center of the tip","Slide on at 45 degrees, press and hold briefly"],"a":3,"why":"Applying at an angle and pressing and holding lets adhesive spread evenly and prevents trapped air.","t":"Nail Enhancements"},{"q":"What is the purpose of blending the tip well area into the natural nail?","c":["To thin the natural nail plate","To make the tip cure faster","To create a smooth, seamless transition","To remove the free edge"],"a":2,"why":"Blending removes the visible line where the tip meets the nail so overlay product lies smooth.","t":"Nail Enhancements"},{"q":"A properly placed sculpting form should:","c":["Fit snugly under the free edge with no side gaps","Sit loosely below the nail to allow flexibility","Cover the sidewalls and the cuticle area fully","Tilt upward and away from the natural finger"],"a":0,"why":"A snug form with no gaps at the sides keeps product from leaking out and supports the extension. It fits under the free edge and is angled slightly downward, not tilted up and away from the finger.","t":"Nail Enhancements"},{"q":"Which statement best describes a nail overlay?","c":["A liquid applied beneath the nail plate","A coating over the nail or tip to add strength","A removable press-on that needs no prep","A chemical used to dissolve enhancements"],"a":1,"why":"An overlay covers the natural nail or tip with acrylic, gel or wrap material to add strength and protection.","t":"Nail Enhancements"},{"q":"What is the correct removal method for soak-off gel?","c":["Pry it off gently with a metal pusher","File the top layer, then wrap in acetone until soft","Peel it off after a long warm water soak","Soak the hand in isopropyl alcohol solution"],"a":1,"why":"Breaking the seal with a file lets acetone penetrate. After softening, the product is gently removed without prying.","t":"Nail Enhancements"},{"q":"Which type of gel is not removed by soaking in acetone?","c":["Soak-off gel polish","UV gel polish","Hard gel","Soak-off color gel"],"a":2,"why":"Hard gels are formulated to be durable and must be filed off. Soft or soak-off gels dissolve in acetone.","t":"Nail Enhancements"},{"q":"The sticky film left on the surface of a cured gel is called the:","c":["Inhibition layer","Oxidation layer","Primer film","Cure bloom"],"a":0,"why":"The inhibition layer forms where oxygen interferes with curing. It is removed with a gel cleanser or alcohol wipe.","t":"Nail Enhancements"},{"q":"A client feels heat while a gel is curing. What should you do?","c":["Tell the client to stay still until it passes","Add another thick layer of gel to insulate","Extend the curing time to finish faster","Have the client pull out briefly, then use thinner layers"],"a":3,"why":"Heat spikes occur when thick layers cure quickly. Briefly removing the hand and applying thinner layers prevents discomfort.","t":"Nail Enhancements"},{"q":"Allergic contact dermatitis from enhancement products is most often caused by:","c":["Repeated skin contact with uncured product","Wearing gloves while working","Using a fine-grit file","Cleaning the nails with a lint-free wipe"],"a":0,"why":"Repeated contact between uncured product and skin can sensitize the immune system. Keep product off the skin.","t":"Nail Enhancements"},{"q":"Over-filing the natural nail during prep can lead to:","c":["Stronger and thicker nails","Faster product curing","Improved adhesion for months","Thin, weak, sensitive nails"],"a":3,"why":"Removing too much of the plate leaves it thin and prone to damage, which compromises both comfort and strength.","t":"Nail Enhancements"},{"q":"To prevent lifting and skin reactions, product should be applied:","c":["Directly onto the cuticle and skin folds","Close to the cuticle but not touching skin","A wide margin away from the whole cuticle","Over the sidewalls and the skin folds"],"a":1,"why":"Leaving a tiny margin keeps product off the skin, which prevents lifting and sensitization.","t":"Nail Enhancements"},{"q":"Which material is commonly used in nail wraps to strengthen the natural nail or tip?","c":["Gauze pad cut into small pieces","Plastic film cut to match the nail","Silk, linen or fiberglass fabric","Latex strips cut to fit the nail"],"a":2,"why":"Silk, linen and fiberglass fabrics are used with resin or adhesive to reinforce the nail.","t":"Nail Enhancements"},{"q":"Which aftercare tip best helps extend the life of enhancements?","c":["Use the nails as tools to open items","Soak hands in hot water daily","Use cuticle oil daily and wear gloves for chores","Pick at lifted edges to reduce snagging"],"a":2,"why":"Hydrating cuticle oil and protective gloves guard enhancements against water, chemicals and trauma.","t":"Post-Service"},{"q":"Why is it good practice to rebook the client before they leave?","c":["It avoids the need for a consultation","It shortens the length of future services","It removes the need for any home care","It keeps the client on a regular schedule"],"a":3,"why":"Scheduling the next visit supports timely fills and maintenance and builds client loyalty.","t":"Post-Service"},{"q":"A client complains about a service. What is the best first response?","c":["Listen without interrupting and acknowledge the concern","Explain firmly why the client is mistaken","Offer a refund before hearing what happened","Ask the client to return on another day"],"a":0,"why":"Listening and acknowledging the concern calms the situation, then you can offer a fair solution.","t":"Post-Service"},{"q":"After the client leaves, how should used towels and linens be handled?","c":["Shake them out and fold them for next client","Hang them over a chair so they can dry","Place them in a closed container for laundering","Store them in a drawer until needed again"],"a":2,"why":"Soiled linens go into a closed or covered container, then are laundered, to prevent spread of contamination.","t":"Post-Service"}],"estht":[{"q":"Which level of decontamination destroys ALL microbial life, including bacterial spores?","c":["Sanitation","Sterilization","Disinfection","Antisepsis"],"a":1,"why":"Sterilization, such as autoclaving, is the highest level and eliminates all microbes including spores. Disinfection kills most pathogens on nonporous surfaces but not reliably spores.","t":"Infection Control"},{"q":"Which item is porous and cannot be properly disinfected, so it must be discarded after one client?","c":["A metal comedone extractor","A cosmetic sponge wedge","Stainless steel tweezers","A glass mixing bowl"],"a":1,"why":"Porous items such as sponges and paper-based files absorb fluids and cannot be disinfected. Nonporous metal and glass can be cleaned and disinfected.","t":"Infection Control"},{"q":"What must be done to a nonporous implement BEFORE it is placed in disinfectant?","c":["Let it air-dry in sunlight","Rinse it with cold water only","Wrap it in a clean towel","Clean it with soap and water"],"a":3,"why":"Cleaning removes debris and oils that would otherwise shield microbes from the disinfectant. Disinfection works only on a clean surface.","t":"Infection Control"},{"q":"How long must a disinfectant stay in contact with an implement or surface to be effective?","c":["Until the surface is completely dry","Until the surface looks visibly clean","A fixed 30 seconds for any product","The contact time stated on the product label"],"a":3,"why":"Each EPA-registered disinfectant has a label-specified contact time that must be followed exactly for it to kill the listed organisms.","t":"Infection Control"},{"q":"Which federal agency registers disinfectants sold for use in salons and spas?","c":["The CDC","OSHA","The FDA","The EPA"],"a":3,"why":"The Environmental Protection Agency registers disinfectants and approves their label claims. OSHA regulates workplace safety, and the FDA regulates cosmetics.","t":"Infection Control"},{"q":"What is the single most effective way for an esthetician to prevent the spread of infection between clients?","c":["Applying hand lotion between clients","Wearing the same gloves for several clients","Spraying the room with air freshener","Washing hands with liquid soap and warm water"],"a":3,"why":"Thorough hand washing before and after each client removes pathogens and is the most important infection-control habit.","t":"Infection Control"},{"q":"After a facial, where should used towels and linens be placed?","c":["In a closed, covered container away from clean linens","Shaken out and refolded for the next client","On the counter beside the clean towels","Draped over the chair to air-dry"],"a":0,"why":"Soiled linens go into a covered hamper to prevent cross-contamination with clean supplies.","t":"Infection Control"},{"q":"A client has pustules with honey-colored crusts on the chin that appear contagious. What should the esthetician do?","c":["Apply a clay mask over the area only","Extract the pustules and continue the facial","Cover the area with concealer and proceed","Decline the service and refer the client to a physician"],"a":3,"why":"Visible signs of a contagious infection are a contraindication. Estheticians do not diagnose or treat infections and must refer the client to a physician.","t":"Infection Control"},{"q":"Which bloodborne disease can be prevented with a vaccine?","c":["Herpes simplex","Hepatitis C","HIV","Hepatitis B"],"a":3,"why":"A vaccine is available for the hepatitis B virus (HBV). There is no vaccine for HIV or hepatitis C.","t":"Bloodborne Pathogens"},{"q":"Where should used razor blades and other sharp disposable items be discarded?","c":["A puncture-resistant, labeled sharps container","A lined bathroom wastebasket","A paper bag placed in regular trash","A covered laundry hamper"],"a":0,"why":"Sharps must go into a rigid, puncture-resistant container labeled for sharps to protect staff from accidental cuts and exposure.","t":"Bloodborne Pathogens"},{"q":"What information does a Safety Data Sheet (SDS) provide about a chemical product?","c":["Hazards, safe handling, and first-aid measures","The retail price and profit margin","Client consent and release language","The product's marketing claims"],"a":0,"why":"An SDS lists chemical hazards, handling and storage guidance, and emergency first-aid information.","t":"OSHA & SDS"},{"q":"Under OSHA's Hazard Communication standard, where must SDS documents for workplace chemicals be kept?","c":["Readily accessible to all employees","Locked in the owner's private office","Discarded after the first reading","Mailed to the state board each year"],"a":0,"why":"Employees must be able to obtain SDS information for the chemicals they use without delay, so the sheets must be accessible during work hours.","t":"OSHA & SDS"},{"q":"Which statement best describes most bacteria?","c":["They are parasites that live only in hair follicles","They are pathogenic and always cause disease","They are nonpathogenic and harmless or even beneficial","They are viruses that need a host to multiply"],"a":2,"why":"The majority of bacteria are nonpathogenic. Only a minority are pathogenic, meaning disease-producing.","t":"Microbiology"},{"q":"Staphylococci, which grow in grape-like clusters, are most associated with which problem?","c":["Cold sores around the lips","Syphilis and Lyme disease","Pus-forming infections such as boils","Ringworm of the skin"],"a":2,"why":"Staphylococci are pus-forming cocci that cause boils and abscesses. Staph strains such as MRSA are a serious concern in service settings.","t":"Microbiology"},{"q":"Some bacteria form a protective spore. When does this typically happen?","c":["When conditions are unfavorable for growth","When the bacteria are actively dividing","When the bacteria are feeding on sebum","When the temperature is ideal"],"a":0,"why":"Spore-forming bacteria become inactive and coated when food, moisture, or temperature is unfavorable, then revive when conditions improve.","t":"Microbiology"},{"q":"Which statement correctly distinguishes viruses from bacteria?","c":["Viruses are easily killed by antibiotics","Viruses cannot reproduce without a living host cell","Viruses reproduce by binary fission","Viruses are larger than most bacteria"],"a":1,"why":"Viruses are much smaller than bacteria and must invade a host cell to replicate. Antibiotics do not work on them.","t":"Microbiology"},{"q":"Scabies is a contagious condition caused by which type of organism?","c":["A fungus that grows on the skin","A mite that burrows into the skin","A bacterium that forms in clusters","A virus that infects follicles"],"a":1,"why":"Scabies is caused by the itch mite, a parasite that burrows under the skin and causes intense itching.","t":"Microbiology"},{"q":"Which epidermal layer is the outermost and consists of flat, dead, keratinized cells?","c":["Stratum germinativum","Stratum corneum","Stratum granulosum","Stratum spinosum"],"a":1,"why":"The stratum corneum, or horny layer, is the outermost protective layer that continually sheds.","t":"Skin Histology"},{"q":"New epidermal cells are produced by mitosis primarily in which layer?","c":["Reticular layer of the dermis","Stratum lucidum","Stratum corneum","Stratum germinativum (basal layer)"],"a":3,"why":"The deepest epidermal layer, the stratum germinativum, contains the basal cells that divide to replace cells lost from the surface.","t":"Skin Histology"},{"q":"Which cells in the dermis produce collagen and elastin?","c":["Merkel cells","Melanocytes","Langerhans cells","Fibroblasts"],"a":3,"why":"Fibroblasts manufacture the collagen and elastin fibers that give skin strength and elasticity.","t":"Skin Histology"},{"q":"Which structure produces sebum, the oily substance that lubricates the skin and hair?","c":["Eccrine glands","Sebaceous glands","Apocrine glands","Arrector pili"],"a":1,"why":"Sebaceous (oil) glands are attached to hair follicles and secrete sebum. Sudoriferous glands produce sweat.","t":"Skin Histology"},{"q":"What is the main role of the subcutaneous layer beneath the dermis?","c":["Fat storage that insulates and cushions the body","Producing melanin for pigmentation","Forming the barrier of dead keratinized cells","Sensing light touch at the surface"],"a":0,"why":"The subcutaneous tissue is made largely of fat cells that insulate, cushion, and store energy.","t":"Skin Histology"},{"q":"Which muscle raises the eyebrows and wrinkles the forehead horizontally?","c":["Procerus","Corrugator","Frontalis","Orbicularis oculi"],"a":2,"why":"The frontalis portion of the epicranius raises the brows and creates horizontal forehead lines. The corrugator pulls the brows together.","t":"Muscles"},{"q":"Which muscle encircles the mouth and is used to pucker and compress the lips?","c":["Buccinator","Orbicularis oris","Mentalis","Risorius"],"a":1,"why":"Orbicularis oris is the circular muscle of the mouth. The buccinator compresses the cheeks.","t":"Muscles"},{"q":"Which muscle is a primary muscle of chewing (mastication) that closes the jaw?","c":["Masseter","Risorius","Mentalis","Procerus"],"a":0,"why":"The masseter, along with the temporalis, closes the jaw for chewing.","t":"Muscles"},{"q":"Which cranial nerve is the chief sensory nerve of the face?","c":["Facial (seventh)","Trigeminal (fifth)","Accessory (eleventh)","Vagus (tenth)"],"a":1,"why":"The trigeminal nerve carries sensation from the face. The facial nerve is the chief motor nerve controlling expressions.","t":"Nerves & Circulation"},{"q":"Which pair of arteries supplies blood to the head, face, and neck?","c":["Common carotid arteries","Jugular veins","Pulmonary arteries","Brachial arteries"],"a":0,"why":"The common carotid arteries branch to supply the head, face, and neck. The jugular veins return blood from the head to the heart.","t":"Nerves & Circulation"},{"q":"What is the main function of lymph vessels and lymph nodes?","c":["Pump oxygenated blood to the face","Filter waste and help defend against infection","Secrete hormones that control metabolism","Produce sebum for the skin surface"],"a":1,"why":"The lymphatic system drains fluid, filters waste and microbes, and supports immunity, which is the reason lymphatic drainage massage is used.","t":"Nerves & Circulation"},{"q":"Which is the only movable bone of the skull?","c":["Mandible","Maxilla","Zygomatic","Temporal"],"a":0,"why":"The mandible, or lower jawbone, is the only movable skull bone.","t":"Bones"},{"q":"Which bone forms the prominence of the cheek?","c":["Occipital","Nasal","Maxilla","Zygomatic"],"a":3,"why":"The zygomatic (malar) bone forms the cheekbone. The maxilla forms the upper jaw.","t":"Bones"},{"q":"A flat, discolored spot on the skin such as a freckle is classified as a:","c":["Vesicle","Papule","Macule","Nodule"],"a":2,"why":"A macule is a flat, nonpalpable change in skin color. A papule is a small raised bump.","t":"Skin Lesions"},{"q":"A raised, inflamed lesion with a white or yellow pus-filled top is called a:","c":["Vesicle","Papule","Pustule","Wheal"],"a":2,"why":"Pustules contain pus. Papules lack visible pus, and vesicles are filled with clear fluid.","t":"Skin Lesions"},{"q":"Which term describes an abnormal crack in the skin that extends into the dermis, such as chapped lips?","c":["Excoriation","Fissure","Crust","Macule"],"a":1,"why":"A fissure is a crack or split in the skin. An excoriation is an abrasion caused by scratching or scraping.","t":"Skin Lesions"},{"q":"Chronic redness with flushing, visible capillaries, and papules on the cheeks and nose suggests:","c":["Milia","Psoriasis","Rosacea","Vitiligo"],"a":2,"why":"Rosacea is a chronic vascular and inflammatory disorder of the central face, often aggravated by heat, alcohol, and sun.","t":"Skin Disorders"},{"q":"Milia are best described as:","c":["Patches of fungal infection on the scalp","Infected oil glands filled with pus and redness","Contagious viral growths on the hands and feet","Tiny white keratin-filled cysts without an opening"],"a":3,"why":"Milia are tiny, pearl-like cysts of trapped keratin and sebum with no follicular opening and are common around the eyes.","t":"Skin Disorders"},{"q":"Red, thickened patches covered with silvery-white scales on elbows and knees are typical of:","c":["Milia","Impetigo","Tinea corporis","Psoriasis"],"a":3,"why":"Psoriasis is a chronic condition with rapid cell turnover that forms scaly plaques. It is not contagious.","t":"Skin Disorders"},{"q":"Which skin cancer is the most common and often appears as a pearly, waxy bump?","c":["Squamous cell carcinoma","Malignant melanoma","Basal cell carcinoma","Actinic keratosis"],"a":2,"why":"Basal cell carcinoma is the most common skin cancer. Melanoma is the most dangerous, and actinic keratosis is precancerous.","t":"Skin Disorders"},{"q":"Common warts (verrucae) are contagious growths caused by which agent?","c":["Blocked sebaceous glands","Staphylococcus bacteria","A dermatophyte fungus","Human papillomavirus"],"a":3,"why":"Warts are caused by the human papillomavirus (HPV) and can spread by contact.","t":"Skin Disorders"},{"q":"Vitiligo is characterized by:","c":["Scaly red plaques on the scalp","Brown patches triggered by hormones","Milky-white patches from loss of melanocytes","Small tan spots from sun exposure"],"a":2,"why":"Vitiligo is an acquired hypopigmentation caused by the loss of melanocytes. The affected areas need sun protection.","t":"Pigmentation Disorders"},{"q":"Dark marks that remain on the skin after a pimple has healed are called:","c":["Leukoderma (loss of pigment)","Post-inflammatory hyperpigmentation","Albinism (congenital pigment loss)","Melasma (hormonal patches)"],"a":1,"why":"Inflammation can stimulate melanocytes to overproduce melanin, leaving dark marks. Daily sunscreen prevents them from darkening.","t":"Pigmentation Disorders"},{"q":"A Fitzpatrick Type I client typically:","c":["Always burns and never tans","Tans easily and rarely burns","Burns minimally and tans well","Has deeply pigmented skin that never burns"],"a":0,"why":"Type I has very fair skin that burns easily and does not tan. Type VI never burns.","t":"Skin Types & Fitzpatrick"},{"q":"What does the Fitzpatrick scale classify?","c":["The hydration level of the epidermis","The activity level of the oil glands","The degree of wrinkling","The skin's response to ultraviolet exposure"],"a":3,"why":"The Fitzpatrick scale groups skin into six types based on how it burns or tans after sun exposure, which guides treatment safety.","t":"Skin Types & Fitzpatrick"},{"q":"A client's skin feels tight with fine surface lines but produces a normal amount of oil. This skin is best described as:","c":["Dry","Dehydrated","Oily","Sensitive"],"a":1,"why":"Dehydrated skin lacks water and can occur in any skin type. Dry skin lacks oil (sebum).","t":"Skin Types & Fitzpatrick"},{"q":"What is the approximate pH of healthy skin's surface?","c":["8.5 to 9.5","7.0 to 7.5","4.5 to 5.5","1.0 to 2.0"],"a":2,"why":"The skin's acid mantle is slightly acidic, around pH 4.5 to 5.5, which helps protect against microbes.","t":"Chemistry & pH"},{"q":"How does a product with a pH of 4 compare to a product with a pH of 6?","c":["It is twice as acidic","It is 100 times more acidic","It is 10 times more acidic","It has the same acidity"],"a":1,"why":"The pH scale is logarithmic, so each whole number is a tenfold change. Two units equals 10 x 10, or 100 times.","t":"Chemistry & pH"},{"q":"Hyaluronic acid and glycerin are examples of which type of ingredient?","c":["Humectants","Occlusives","Surfactants","Preservatives"],"a":0,"why":"Humectants attract and hold water in the skin. Occlusives, such as petrolatum, form a barrier that slows water loss.","t":"Cosmetic Ingredients"},{"q":"Zinc oxide and titanium dioxide in sunscreen are classified as:","c":["Preservatives that prevent spoilage","Chemical filters that absorb UV","Physical filters that reflect and scatter UV","Emulsifiers that blend oil and water"],"a":2,"why":"Mineral sunscreens sit on the skin surface and reflect or scatter UV. Chemical filters absorb UV and convert it to heat.","t":"Cosmetic Ingredients"},{"q":"Which alpha hydroxy acid has the smallest molecule and penetrates skin most readily?","c":["Glycolic acid","Lactic acid","Salicylic acid","Citric acid"],"a":0,"why":"Glycolic acid, derived from sugar cane, is the smallest AHA and penetrates readily. Salicylic acid is a BHA, not an AHA.","t":"Cosmetic Ingredients"},{"q":"Which type of current does a galvanic machine use?","c":["Tesla high-frequency current","Alternating current (AC)","Direct current (DC)","Interrupted faradic current"],"a":2,"why":"Galvanic current is a constant, direct current with a positive and negative pole used for desincrustation and iontophoresis.","t":"Electricity & Machines"},{"q":"In desincrustation, which pole and solution are used to soften and emulsify sebum?","c":["Positive pole with an acidic solution","Positive pole with an alkaline solution","Negative pole with an acidic solution","Negative pole with an alkaline solution"],"a":3,"why":"The negative pole repels the alkaline solution into the follicle, saponifying sebum and softening comedones.","t":"Electricity & Machines"},{"q":"Which client should NOT receive electrical facial treatments such as high frequency?","c":["A client with mild dehydration","A client with a heart pacemaker","A client with oily skin and open pores","A client who wears contact lenses"],"a":1,"why":"Pacemakers, metal implants, pregnancy, and epilepsy are common contraindications to electrical current.","t":"Electricity & Machines"},{"q":"Which LED light color is most commonly used to target acne-causing bacteria?","c":["Infrared","Red","Blue","Green"],"a":2,"why":"Blue light has an antibacterial effect on acne bacteria. Red light is more associated with collagen stimulation and repair.","t":"Electricity & Machines"},{"q":"Microcurrent is a low-level current used primarily to:","c":["Sterilize implements between clients","Permanently destroy hair follicles","Stimulate facial muscles and improve skin tone","Deliver intense heat to the dermis"],"a":2,"why":"Microcurrent mimics the body's natural electrical impulses to tone muscles, and it is used in lifting-type facials.","t":"Electricity & Machines"},{"q":"Which vitamin is required for collagen formation and acts as an antioxidant in skin?","c":["Vitamin C","Vitamin K","Vitamin D","Vitamin B12"],"a":0,"why":"Vitamin C supports collagen synthesis and neutralizes free radicals. Vitamin K helps blood clotting.","t":"Nutrition & Aging"},{"q":"What is the leading external cause of premature skin aging?","c":["Washing with warm water","Drinking too little coffee","Sleeping on one side","Chronic ultraviolet exposure"],"a":3,"why":"Photoaging from cumulative UV exposure breaks down collagen and elastin and causes wrinkles and pigmentation.","t":"Nutrition & Aging"},{"q":"Which medication most strongly contraindicates waxing, peels, and microdermabrasion?","c":["A daily multivitamin","Isotretinoin (Accutane)","An antacid","Acetaminophen"],"a":1,"why":"Isotretinoin makes skin very thin and fragile, so exfoliating and waxing services can cause tearing and scarring.","t":"Consultation & Contraindications"},{"q":"What is the main purpose of a client intake form?","c":["Diagnose existing skin diseases and conditions","Collect health history and skin concerns to plan safe care","Promote retail products to every client","Replace the need for a skin analysis"],"a":1,"why":"The intake form helps identify contraindications and allergies and supports an appropriate treatment plan.","t":"Consultation & Contraindications"},{"q":"Why is a magnifying lamp used during skin analysis?","c":["To disinfect the surface of the face fully","To warm the skin before cleansing begins","To examine the cleansed skin in detail","To increase product absorption deeply"],"a":2,"why":"A magnifying lamp enlarges the skin so the esthetician can assess texture, pores, and lesions. The client's eyes are protected during use.","t":"Consultation & Contraindications"},{"q":"A client mentions a mole that has recently changed in size and color. What is the best response?","c":["Extract the mole during the facial","Treat the mole with a chemical peel","Recommend that the client see a dermatologist","Cover it with makeup and continue"],"a":2,"why":"Changes in a mole can signal skin cancer. Estheticians cannot diagnose, so they refer the client to a medical professional.","t":"Consultation & Contraindications"},{"q":"Which finding is a contraindication to a standard facial?","c":["Fine lines","Mild dryness","A few open comedones","Active sunburn"],"a":3,"why":"Sunburned skin is already inflamed and compromised, so exfoliation, massage, and steam could cause pain and further damage.","t":"Consultation & Contraindications"},{"q":"A client reports a latex allergy. Which glove choice is appropriate?","c":["Powdered latex gloves","Non-latex gloves such as nitrile","Double latex gloves","No gloves at all"],"a":1,"why":"Latex-allergic clients can react to latex contact, so nitrile or vinyl gloves should be used.","t":"Consultation & Contraindications"},{"q":"What is the purpose of applying toner after cleansing or mask removal?","c":["Deeply exfoliate the stratum corneum","Seal the skin with an occlusive barrier","Remove residue and help restore the skin's pH","Provide permanent pore reduction"],"a":2,"why":"Toners remove traces of cleanser or mask, refresh the skin, and prepare it for moisturizer.","t":"Facial Procedures"},{"q":"Which cleanser is generally best suited for oily, acne-prone skin?","c":["A heavy mineral-oil cold cream","A gel or foaming cleanser","A rich lanolin cream cleanser","A thick balm with shea butter"],"a":1,"why":"Gel and foaming cleansers remove excess oil without leaving a heavy residue.","t":"Facial Procedures"},{"q":"Why is steam often applied before extractions?","c":["To permanently shrink the pores","To soften sebum and hydrate the skin","To sterilize the follicles","To firm the facial muscles"],"a":1,"why":"Warm, moist steam softens the contents of follicles so they come out more easily and gently.","t":"Facial Procedures"},{"q":"When removing makeup at the start of a facial, which area is generally cleansed first?","c":["The forehead","The lips","The neck","The eyes"],"a":3,"why":"Eye makeup is removed first with a gentle eye makeup remover so it is not smeared across the face during cleansing.","t":"Facial Procedures"},{"q":"A client's skin turns bright red and feels burning during steam. What should the esthetician do?","c":["Stop the steam and apply a cool, soothing compress","Increase the steam time to calm the redness","Apply a stimulating scrub","Place a warm towel over the face"],"a":0,"why":"Redness with burning shows irritation, so the steam is stopped and the skin is soothed with cool compresses.","t":"Facial Procedures"},{"q":"Which massage movement consists of light, gliding strokes and is used to begin and end a sequence?","c":["Friction","Petrissage","Tapotement","Effleurage"],"a":3,"why":"Effleurage is a light, continuous stroking movement that relaxes and spreads product.","t":"Massage"},{"q":"Which description fits petrissage?","c":["Light gliding strokes","Kneading, lifting, and squeezing the tissue","Rapid tapping or slapping","Light vibration with the fingertips"],"a":1,"why":"Petrissage is a kneading movement that stimulates circulation and muscle tissue.","t":"Massage"},{"q":"Which massage movement is performed with a tapping action and is the most stimulating?","c":["Tapotement","Effleurage","Petrissage","Friction"],"a":0,"why":"Tapotement, or percussion, uses quick tapping movements and is very stimulating. It is applied lightly on the face.","t":"Massage"},{"q":"Which client should obtain physician clearance before receiving a facial massage?","c":["A client with uncontrolled high blood pressure","A client with oily skin and large pores","A client with balanced, normal skin","A client who regularly wears eyeglasses"],"a":0,"why":"Massage increases circulation, which can be risky for clients with cardiovascular conditions, so medical clearance is advised.","t":"Massage"},{"q":"Which mask is best suited to oily skin?","c":["A heated paraffin mask","A rich occlusive oil mask","A thick emollient butter mask","A clay-based mask that absorbs excess oil"],"a":3,"why":"Clay masks such as kaolin absorb sebum and help clear congestion.","t":"Masks"},{"q":"Which mask is made from seaweed, sets into a rubbery film, and is peeled off?","c":["Enzyme mask","Clay mask","Cream mask","Alginate mask"],"a":3,"why":"Alginate masks are derived from seaweed and are mixed with water to form a gel-like sheet that is peeled away.","t":"Masks"},{"q":"Which mask is typically best for dry, mature skin?","c":["An alcohol-based astringent mask","A kaolin clay mask","A sulfur-based drying mask","A hydrating cream mask with emollients"],"a":3,"why":"Cream masks with emollients and humectants add comfort and moisture, whereas clay and alcohol masks are drying.","t":"Masks"},{"q":"Which of the following is a form of chemical exfoliation?","c":["Microdermabrasion","A granular scrub","A rotating brush machine","An enzyme peel containing papain"],"a":3,"why":"Chemical exfoliants use acids or enzymes to dissolve dead cells. Scrubs, brushes, and microdermabrasion are mechanical.","t":"Exfoliation"},{"q":"How does microdermabrasion exfoliate the skin?","c":["It dissolves the dermis with strong acid solutions","It abrades dead surface cells using crystals or a diamond tip","It deposits pigment into the upper dermis layer","It heats the deep dermis with focused laser light"],"a":1,"why":"Microdermabrasion is a mechanical method that removes dead surface cells and stimulates renewal.","t":"Exfoliation"},{"q":"Why is salicylic acid (BHA) well suited to oily, acne-prone skin?","c":["It is oil-soluble and can penetrate sebum-filled follicles","It is water-soluble and stays on the surface","It is a physical abrasive","It is derived from milk"],"a":0,"why":"Salicylic acid dissolves in oil, so it can travel into pores and exfoliate inside the follicle.","t":"Exfoliation"},{"q":"Which aftercare advice is most important after a chemical peel?","c":["Book a tanning session to even out the tone","Use a granular scrub daily for the next week","Avoid sun and wear a broad-spectrum sunscreen daily","Apply fragranced oils to the treated area"],"a":2,"why":"Peeled skin is more sensitive to UV and prone to hyperpigmentation, so strict sun protection is essential.","t":"Exfoliation"},{"q":"Why is a client using topical retinoids at higher risk of irritation from a chemical peel?","c":["Retinoids thicken the stratum corneum permanently","Retinoids neutralize acids","Retinoids numb the skin","Retinoids speed cell turnover and thin the surface layer"],"a":3,"why":"Retinoids already exfoliate and sensitize the skin, so adding a peel can cause over-exfoliation, burning, and peeling.","t":"Exfoliation"},{"q":"Superficial peels performed by an esthetician are intended to affect which part of the skin?","c":["The reticular dermis","The hypodermis","The epidermis","The muscle fascia"],"a":2,"why":"Esthetic peels are superficial and work on the epidermis. Deeper peels are medical procedures.","t":"Exfoliation"},{"q":"Which lesion is generally appropriate for esthetic extraction?","c":["A hard nodule","A deep cyst","An open comedone (blackhead)","An inflamed deep papule"],"a":2,"why":"Surface comedones that have been softened can be extracted. Deep, inflamed, or cystic lesions should be referred to a physician.","t":"Extractions"},{"q":"Which practice is correct when performing manual extractions?","c":["Reuse the same cotton swab for every lesion","Use bare fingers with long nails for control","Squeeze firmly until blood appears at the site","Wear gloves and wrap fingertips in damp cotton"],"a":3,"why":"Gloves and cotton protect both parties from contact with fluids, and gentle pressure avoids trauma and scarring.","t":"Extractions"},{"q":"When using soft wax with a muslin or paper strip, how should the wax be applied and removed?","c":["Applied against growth, removed with growth","Applied with hair growth, removed against growth","Applied in a circular pattern, removed straight up","Applied thickly, left to harden for an hour"],"a":1,"why":"Applying wax in the direction of growth and pulling against it removes hair from the follicle efficiently.","t":"Hair Removal"},{"q":"Where should the esthetician first test the temperature of heated wax?","c":["On the inside of the esthetician's wrist","On the client's face","On the outer rim of the wax pot","On a paper strip"],"a":0,"why":"The thin skin of the inner wrist is a quick, reliable check of heat before wax touches the client; a small test patch is then applied to the client's skin. Judging by the pot rim or a strip is unreliable.","t":"Hair Removal"},{"q":"Which practice during waxing is unsafe and unsanitary?","c":["Using a new spatula for each application","Wearing gloves for the service","Re-dipping a used spatula into the wax pot","Holding the skin taut"],"a":2,"why":"Double-dipping contaminates the wax and can spread infection to later clients.","t":"Hair Removal"},{"q":"Which client should NOT be waxed in the area of concern?","c":["A client with normal skin and thick hair","A client with dark, coarse hair","A client with sunburned skin in the area","A client who shaved a week ago"],"a":2,"why":"Waxing on sunburned or irritated skin can lift the skin and cause severe damage.","t":"Hair Removal"},{"q":"Sugaring paste is typically made from which ingredients?","c":["Sugar, lemon juice, and water","Paraffin and resin","Beeswax and honey","Thioglycolate and lime"],"a":0,"why":"Sugar paste is a natural mixture of sugar, lemon juice, and water that is water-soluble and easy to clean.","t":"Hair Removal"},{"q":"Which method uses a fine probe to treat each follicle individually and is considered permanent?","c":["Electrolysis","Waxing","Depilatory cream","Threading"],"a":0,"why":"Electrolysis destroys the hair papilla one follicle at a time. Waxing, threading, and depilatories are temporary.","t":"Hair Removal"},{"q":"Which hair growth phase is the active growth stage?","c":["Catagen","Anagen","Telogen","Resting phase"],"a":1,"why":"In anagen the hair is actively growing and attached to the papilla. Catagen is transitional and telogen is resting.","t":"Hair Removal"},{"q":"Which color of corrector or concealer helps neutralize redness?","c":["Yellow","Lavender","Green","Orange"],"a":2,"why":"Green sits opposite red on the color wheel, so it cancels redness when used under foundation.","t":"Makeup & Color Theory"},{"q":"Which pair of colors are complementary?","c":["Blue and orange","Blue and green","Red and orange","Yellow and orange"],"a":0,"why":"Complementary colors sit directly opposite each other on the color wheel. Blue and orange are opposites.","t":"Makeup & Color Theory"},{"q":"How does a lighter shade of foundation or highlighter affect a facial feature?","c":["It makes the area look smaller","It makes the area appear to recede","It makes the area look larger and more prominent","It has no visible effect"],"a":2,"why":"Light colors reflect light and bring features forward, while darker shades recede.","t":"Makeup & Color Theory"},{"q":"Foundation shade is best matched by testing it on the:","c":["Back of the hand","Jawline","Inner wrist","Forehead"],"a":1,"why":"Testing along the jawline lets the esthetician blend the face into the neck and judge the match in natural light.","t":"Makeup & Color Theory"},{"q":"How should cosmetics be removed from a container for use on a client?","c":["With a clean disposable applicator or spatula","With a finger","With the brush used on the last client","With an applicator rinsed in water"],"a":0,"why":"Using a clean tool each time prevents contamination of the container and cross-contamination between clients.","t":"Makeup & Color Theory"},{"q":"The ideal eyebrow typically begins in line with the:","c":["Center of the pupil","Outer corner of the eye","Inner corner of the eye","Outer edge of the lip"],"a":2,"why":"A vertical line from the side of the nostril through the inner corner of the eye marks the proper start of the brow.","t":"Lash & Brow Services"},{"q":"Why is a patch test recommended before tinting lashes or brows?","c":["To check for an allergic reaction to the tint","To preview the exact final color shade","To disinfect the skin before tinting begins","To measure the client's hair growth rate"],"a":0,"why":"Tints can cause allergic reactions, so a patch test is performed in advance to identify sensitivity.","t":"Lash & Brow Services"},{"q":"Which condition is a contraindication to eyelash extensions?","c":["Active eye infection, such as pink eye","Naturally long, thick natural lashes","Dark brown or black natural lashes","Dry skin around the eye area"],"a":0,"why":"Eye infections can be worsened by adhesives and spread to other clients, so the service must be postponed.","t":"Lash & Brow Services"},{"q":"Which type of sunlight radiation penetrates deepest into the dermis and is the main contributor to photoaging?","c":["Gamma radiation","UVB","UVC","UVA"],"a":3,"why":"UVA has a longer wavelength and reaches the dermis, damaging collagen. UVB mainly causes sunburn.","t":"Sun Protection & Aftercare"},{"q":"What does the label term 'broad-spectrum' mean on a sunscreen?","c":["It is waterproof for any activity","It protects only against UVB rays","It protects against both UVA and UVB rays","It has an SPF of 100 or higher"],"a":2,"why":"Broad-spectrum sunscreens are formulated to protect against both UVA and UVB radiation.","t":"Sun Protection & Aftercare"},{"q":"Which action is outside an esthetician's scope of practice?","c":["Diagnosing disease or prescribing drugs","Performing a deep-cleansing facial","Recommending home care products","Applying makeup for a special event"],"a":0,"why":"Estheticians cleanse and beautify the skin but may not diagnose, treat disease, or prescribe medication.","t":"Professional Ethics"},{"q":"How should the information on a client's intake form be handled?","c":["Shared with coworkers for casual conversation","Kept private and shared only with client consent","Posted in the reception area for staff","Used for marketing without asking the client"],"a":1,"why":"Client records are private, and confidentiality builds trust and protects the esthetician professionally.","t":"Professional Ethics"}],"massage":[{"q":"Which muscle is the main prime mover of shoulder abduction after the first 15 degrees of movement?","c":["Pectoralis major","Middle deltoid","Latissimus dorsi","Teres major"],"a":1,"why":"The deltoid, particularly its middle fibers, is the prime mover of shoulder abduction once the supraspinatus has initiated the first 15 degrees.","t":"Anatomy & Physiology"},{"q":"Which structure separates the thoracic cavity from the abdominopelvic cavity?","c":["Mediastinum","Pleura","Peritoneum","Diaphragm"],"a":3,"why":"The dome-shaped diaphragm forms the boundary between the thoracic and abdominopelvic cavities.","t":"Anatomy & Physiology"},{"q":"Which pancreatic hormone raises blood glucose by prompting the liver to release stored glucose?","c":["Glucagon","Insulin","Calcitonin","Oxytocin"],"a":0,"why":"Glucagon, secreted by the alpha cells of the pancreatic islets, raises blood glucose; insulin lowers it.","t":"Anatomy & Physiology"},{"q":"Which layer of the skin is avascular and composed of stratified squamous epithelium?","c":["Dermis","Hypodermis","Epidermis","Subcutaneous layer"],"a":2,"why":"The epidermis has no blood vessels and receives nutrients by diffusion from the dermis below.","t":"Anatomy & Physiology"},{"q":"The vagus nerve is which cranial nerve?","c":["CN VII","CN IX","CN X","CN XII"],"a":2,"why":"The vagus nerve is cranial nerve X and supplies parasympathetic fibers to the heart, lungs and digestive organs.","t":"Anatomy & Physiology"},{"q":"Which muscle group has its main proximal attachment on the ischial tuberosity and crosses both the hip and the knee?","c":["Hamstrings","Quadriceps femoris","Adductor group","Gluteal group"],"a":0,"why":"Semitendinosus, semimembranosus and the long head of biceps femoris arise from the ischial tuberosity and cross both the hip and knee. The short head of biceps femoris arises from the linea aspera and crosses only the knee, so the group is defined by its main proximal attachment.","t":"Anatomy & Physiology"},{"q":"What is the primary function of the lymphatic system?","c":["Producing red blood cells","Regulating blood glucose levels","Transporting oxygen to tissues","Returning interstitial fluid to the circulation"],"a":3,"why":"The lymphatic system collects excess interstitial fluid as lymph and returns it to the blood, while also supporting immunity.","t":"Anatomy & Physiology"},{"q":"Blood leaving the right ventricle of the heart enters which vessel?","c":["Aorta","Pulmonary trunk","Pulmonary vein","Superior vena cava"],"a":1,"why":"The right ventricle pumps deoxygenated blood into the pulmonary trunk, which carries it to the lungs.","t":"Anatomy & Physiology"},{"q":"Which muscle is the primary muscle of quiet inspiration?","c":["Diaphragm","Internal intercostals","Transversus abdominis","Pectoralis minor"],"a":0,"why":"The diaphragm contracts and flattens to enlarge the thoracic cavity and is the main muscle of quiet breathing.","t":"Anatomy & Physiology"},{"q":"Which connective tissue sheath surrounds an individual muscle fiber?","c":["Epimysium","Perimysium","Endomysium","Periosteum"],"a":2,"why":"The endomysium surrounds each fiber, the perimysium surrounds fascicles, and the epimysium surrounds the whole muscle.","t":"Anatomy & Physiology"},{"q":"The hip joint is classified as which type of synovial joint?","c":["Hinge","Ball-and-socket","Pivot","Saddle"],"a":1,"why":"The head of the femur fits into the acetabulum, forming a ball-and-socket joint that allows movement in three planes.","t":"Anatomy & Physiology"},{"q":"Which movement occurs in the sagittal plane?","c":["Abduction of the hip","Rotation of the trunk","Adduction of the shoulder","Flexion of the elbow"],"a":3,"why":"Flexion and extension occur in the sagittal plane; abduction and adduction occur in the frontal plane, and rotation in the transverse plane.","t":"Kinesiology"},{"q":"What type of contraction occurs when a muscle lengthens while producing force, such as lowering a heavy weight slowly?","c":["Isometric","Concentric","Isokinetic","Eccentric"],"a":3,"why":"In an eccentric contraction the muscle develops tension while it lengthens, controlling the motion against gravity or load.","t":"Kinesiology"},{"q":"When the biceps brachii contracts to flex the elbow, the triceps brachii acts as the:","c":["Synergist","Antagonist","Fixator","Prime mover"],"a":1,"why":"The antagonist opposes the action of the agonist (prime mover); the triceps extends the elbow.","t":"Kinesiology"},{"q":"Which plane divides the body into anterior and posterior portions?","c":["Sagittal plane","Transverse plane","Frontal plane","Oblique plane"],"a":2,"why":"The frontal (coronal) plane divides the body front from back; abduction and adduction occur in this plane.","t":"Kinesiology"},{"q":"Which instrument is used to measure joint range of motion in degrees?","c":["Goniometer","Plumb line","Stethoscope","Pulse oximeter"],"a":0,"why":"A goniometer has two arms and a protractor-style scale that measure the angle of joint movement.","t":"Kinesiology"},{"q":"Which muscle is a primary plantar flexor of the ankle and also crosses the knee joint?","c":["Soleus","Gastrocnemius","Tibialis anterior","Fibularis tertius"],"a":1,"why":"The gastrocnemius crosses both the knee and ankle; the soleus crosses only the ankle.","t":"Kinesiology"},{"q":"Which forearm movement rotates the radius so that the palm faces anteriorly (or upward when the elbow is flexed)?","c":["Supination","Pronation","Opposition","Eversion"],"a":0,"why":"Supination rotates the radius back alongside the ulna so the palm faces forward (anatomical position) or up; pronation turns it posteriorly or down.","t":"Kinesiology"},{"q":"Which of the following muscles is part of the rotator cuff group?","c":["Teres major","Deltoid","Rhomboid minor","Infraspinatus"],"a":3,"why":"The rotator cuff consists of the supraspinatus, infraspinatus, teres minor and subscapularis (SITS).","t":"Kinesiology"},{"q":"Which muscle group is the primary mover for knee extension?","c":["Hamstrings","Sartorius","Quadriceps femoris","Gracilis"],"a":2,"why":"The four quadriceps muscles join in the patellar tendon and extend the knee.","t":"Kinesiology"},{"q":"By convention, the insertion of a muscle is the attachment located on the:","c":["Bone closest to the trunk","More stationary bone","More movable bone","Muscle belly itself"],"a":2,"why":"The origin is the attachment on the more stationary bone and the insertion is on the bone that moves when the muscle contracts.","t":"Kinesiology"},{"q":"Which ankle movement turns the sole of the foot outward (laterally)?","c":["Inversion","Plantar flexion","Dorsiflexion","Eversion"],"a":3,"why":"Eversion turns the sole outward; inversion turns it inward toward the midline.","t":"Kinesiology"},{"q":"Which of the following is a systemic contraindication to a full-body massage?","c":["Fever with an active infection","Mild muscle tension","Well-controlled hypertension","An old healed scar"],"a":0,"why":"A fever indicates the body is fighting infection; massage could spread infection and stress the system, so it is postponed.","t":"Pathology & Contraindications"},{"q":"A client has a swollen, warm, painful calf on one leg only. What is the most appropriate action?","c":["Perform deep stripping to reduce swelling","Do not massage the leg and refer the client to a physician promptly","Apply a hot pack, then massage","Perform vigorous percussion over the calf"],"a":1,"why":"These signs may indicate deep vein thrombosis; massage could dislodge a clot, so the client needs urgent medical evaluation.","t":"Pathology & Contraindications"},{"q":"Which is an example of a local contraindication?","c":["Open wound or acute inflammation at the site","General fatigue","A stable healed fracture","Mild stress"],"a":0,"why":"Local contraindications mean avoiding only the affected area while massage can often be done elsewhere on the body.","t":"Pathology & Contraindications"},{"q":"Which statement describes a common caution for clients with diabetes?","c":["Deep friction on the legs is preferred","Reduced sensation may mask discomfort from pressure","Massage always raises insulin needs","Oil must never be used"],"a":1,"why":"Neuropathy can reduce sensation, especially in the feet, so the client may not feel when pressure is too deep and tissue can be damaged.","t":"Pathology & Contraindications"},{"q":"Which position is generally recommended for a client in late pregnancy?","c":["Supine and flat","Prone and flat","Standing only","Side-lying with bolsters"],"a":3,"why":"Side-lying with support is comfortable and avoids pressure on the vena cava that can occur when lying flat on the back.","t":"Pathology & Contraindications"},{"q":"Edema is best described as:","c":["Inflammation of a joint","Narrowing of the airways","Abnormal accumulation of fluid in tissues","Tearing of a ligament"],"a":2,"why":"Edema is excess fluid in interstitial spaces, causing swelling; its cause must be known before massage is applied.","t":"Pathology & Contraindications"},{"q":"Clients taking anticoagulant medication such as warfarin require reduced pressure because of increased risk of:","c":["Dehydration","Hypoglycemia","Muscle spasm","Bruising and bleeding"],"a":3,"why":"Anticoagulants slow clotting, so deep pressure can easily cause bruising or bleeding under the skin.","t":"Pathology & Contraindications"},{"q":"Which skin condition is a contagious fungal infection that contraindicates massage over the area?","c":["Psoriasis","Eczema","Tinea corporis","Vitiligo"],"a":2,"why":"Tinea corporis (ringworm) is a fungal infection that can spread to the therapist and other clients.","t":"Pathology & Contraindications"},{"q":"Which approach is appropriate for a client who has cancer?","c":["Deep pressure over the tumor site","Adapt pressure and obtain input from the client's healthcare provider","Apply hot packs directly on the tumor","Use no adaptations at all"],"a":1,"why":"Massage for clients with cancer should be adapted and coordinated with the oncology care team, since treatments and disease affect tolerance.","t":"Pathology & Contraindications"},{"q":"A strain is an injury to a:","c":["Muscle or tendon","Ligament","Cartilage disc","Bone"],"a":0,"why":"A strain involves a muscle or its tendon, while a sprain involves a ligament.","t":"Pathology & Contraindications"},{"q":"Inflammation of the thick connective tissue band on the sole of the foot is called:","c":["Shin splints","Plantar fasciitis","Morton neuroma","Bunion"],"a":1,"why":"Plantar fasciitis is inflammation or irritation of the plantar fascia, typically causing heel pain.","t":"Pathology & Contraindications"},{"q":"Compression of which nerve at the wrist causes carpal tunnel syndrome?","c":["Ulnar nerve","Radial nerve","Median nerve","Musculocutaneous nerve"],"a":2,"why":"The median nerve passes through the carpal tunnel; compression causes numbness and tingling in the thumb, index and middle fingers.","t":"Pathology & Contraindications"},{"q":"Which modification is appropriate for a client with osteoporosis?","c":["Lighter pressure and gentle joint work","Vigorous percussion over the ribs","Deep spinal compression","Forceful joint mobilization"],"a":0,"why":"Bones are fragile in osteoporosis, so heavy pressure and forceful joint movements risk fracture.","t":"Pathology & Contraindications"},{"q":"A client points out a mole that has recently changed in shape and color. What is the best response?","c":["Massage over it with plenty of oil","Apply deep friction to the spot","Reassure the client it is probably harmless","Recommend the client see a physician"],"a":3,"why":"Changes in a mole can be a warning sign of skin cancer; the therapist should not diagnose but should recommend medical evaluation.","t":"Pathology & Contraindications"},{"q":"Effleurage is a gliding stroke that is most associated with:","c":["Breaking up adhesions","Percussive stimulation","Enhancing venous and lymphatic flow","Cross-fiber friction"],"a":2,"why":"Effleurage applied toward the heart assists venous and lymphatic return and helps spread lubricant and warm tissue.","t":"Benefits & Effects"},{"q":"Petrissage primarily works by:","c":["Tapping to excite nerve endings","Lifting and squeezing tissue to increase local circulation","Gliding lightly to calm the skin","Holding static compression on a point"],"a":1,"why":"Petrissage is a kneading stroke that lifts, rolls and squeezes muscle tissue, promoting circulation and mobility.","t":"Benefits & Effects"},{"q":"Tapotement is generally used to:","c":["Calm the nervous system","Stretch fascia","Reduce edema","Stimulate muscles and nerves"],"a":3,"why":"Rhythmic percussive strokes are stimulating and are often used in sports or pre-event massage.","t":"Benefits & Effects"},{"q":"Slow, rhythmic massage tends to promote activity in which division of the autonomic nervous system?","c":["Parasympathetic","Sympathetic","Somatic","Voluntary"],"a":0,"why":"Parasympathetic activation produces the relaxation response, with slower heart rate and relaxed muscles.","t":"Benefits & Effects"},{"q":"What is the immediate physiological effect of applying ice to an acutely injured area?","c":["Vasoconstriction","Vasodilation","Increased swelling","Muscle lengthening"],"a":0,"why":"Cold causes vasoconstriction, which helps limit swelling and bleeding and numbs pain.","t":"Benefits & Effects"},{"q":"Deep transverse friction is mainly used to:","c":["Warm the skin surface","Increase lymph flow","Sedate the nervous system","Help mobilize adhesions and scar tissue"],"a":3,"why":"Friction applied across the tissue fibers helps break down adhesions and improve mobility of scarred tissue.","t":"Benefits & Effects"},{"q":"Lymphatic drainage strokes are generally directed:","c":["Away from the nearest lymph nodes","Against the direction of venous flow","Toward the regional lymph nodes","Only toward the feet"],"a":2,"why":"Lymph is moved toward regional lymph nodes, where it is filtered before being returned to the bloodstream.","t":"Benefits & Effects"},{"q":"Which is a generally accepted effect of massage on the circulatory system?","c":["Permanently lowered heart rate","Temporary increase in local blood flow","Reduced red blood cell count","Hardening of the arteries"],"a":1,"why":"Massage causes local vasodilation and hyperemia, increasing blood flow to treated tissues.","t":"Benefits & Effects"},{"q":"Which receptor detects increased tension in a tendon and can trigger a protective muscle relaxation reflex?","c":["Muscle spindle","Meissner corpuscle","Pacinian corpuscle","Golgi tendon organ"],"a":3,"why":"Golgi tendon organs sense tension and inhibit the contracting muscle when tension is excessive.","t":"Benefits & Effects"},{"q":"Which receptor detects rapid stretch of a muscle and triggers the stretch reflex?","c":["Muscle spindle","Golgi tendon organ","Ruffini ending","Free nerve ending"],"a":0,"why":"Muscle spindles sense changes in muscle length and cause a reflex contraction to resist rapid stretch.","t":"Benefits & Effects"},{"q":"In post-isometric relaxation, an isometric contraction is followed by:","c":["Increased muscle tone","Temporary relaxation that allows a greater stretch","Muscle spasm","Numbness"],"a":1,"why":"After a brief isometric contraction, the muscle is temporarily more relaxed, allowing it to be stretched farther.","t":"Benefits & Effects"},{"q":"Which of the following is a mechanical effect of massage?","c":["Release of endorphins","Reduced anxiety","Passive stretching of soft tissue","Stimulation of the relaxation response"],"a":2,"why":"Mechanical effects come directly from physical pressure and movement; endorphin release, relaxation and reduced anxiety are physiological or psychological effects.","t":"Benefits & Effects"},{"q":"Which stroke direction best assists venous return in the extremities?","c":["Proximal to distal","Distal to proximal, toward the heart","Side to side across the limb","Away from the heart"],"a":1,"why":"Veins carry blood toward the heart, so moving distal to proximal helps assist flow.","t":"Benefits & Effects"},{"q":"How does the gate control theory explain pain relief from massage?","c":["Blood flow to nerves is blocked","Nociceptors are destroyed by pressure","Inflammation increases in the tissue","Touch input can compete with and inhibit pain signals in the spinal cord"],"a":3,"why":"Stimulating large touch fibers can close the spinal 'gate' and reduce transmission of pain signals to the brain.","t":"Benefits & Effects"},{"q":"A client says, 'My neck hurts at a 6 out of 10.' In a SOAP note, this belongs in which section?","c":["Plan","Objective","Subjective","Assessment"],"a":2,"why":"The Subjective section records what the client reports, including symptoms, pain levels and history.","t":"Assessment & Treatment Planning"},{"q":"Which entry belongs in the Objective section of a SOAP note?","c":["Therapist observed rounded shoulders and restricted neck rotation","Client says headaches occur daily","Plan to see client weekly","Stress appears to be the main cause"],"a":0,"why":"Objective data are measurable or observable findings by the therapist, such as posture, ROM and palpation.","t":"Assessment & Treatment Planning"},{"q":"Which entry belongs in the Plan section of a SOAP note?","c":["Recommend weekly sessions for four weeks plus stretching homework","Client rates pain 4/10","Observed elevated left shoulder","Palpated taut band in upper trapezius"],"a":0,"why":"The Plan outlines future treatment, frequency, client self-care and any referrals.","t":"Assessment & Treatment Planning"},{"q":"In a lateral postural assessment, the plumb line should pass through the earlobe, shoulder, hip and just anterior to which landmark?","c":["Calcaneus","Metatarsal heads","Lateral malleolus","Medial malleolus"],"a":2,"why":"Ideal alignment in a lateral view places the plumb line through the ear, acromion, greater trochanter, slightly anterior to the knee and just anterior to the lateral malleolus.","t":"Assessment & Treatment Planning"},{"q":"An exaggerated posterior curvature of the thoracic spine is called:","c":["Lordosis","Scoliosis","Flat back","Kyphosis"],"a":3,"why":"Kyphosis is an excessive thoracic curve, often seen as a hunched upper back.","t":"Assessment & Treatment Planning"},{"q":"An exaggerated anterior curvature of the lumbar spine is called:","c":["Kyphosis","Lordosis","Scoliosis","Torticollis"],"a":1,"why":"Lordosis is an increased lumbar curve, commonly accompanied by an anterior pelvic tilt.","t":"Assessment & Treatment Planning"},{"q":"During palpation, a muscle that feels abnormally tight and firm is described as:","c":["Atrophic","Hypotonic","Hypertonic","Flaccid"],"a":2,"why":"Hypertonicity means increased muscle tone; hypotonic and flaccid describe decreased tone.","t":"Assessment & Treatment Planning"},{"q":"Which type of ROM testing is used to evaluate the end-feel of a joint?","c":["Passive ROM","Active ROM","Resisted ROM","Isometric testing"],"a":0,"why":"End-feel is assessed when the therapist moves the joint at the end of its range while the client is relaxed.","t":"Assessment & Treatment Planning"},{"q":"A painful resisted isometric test most likely indicates a problem in which tissue?","c":["Skin","Contractile tissue (muscle or tendon)","Lymph node","Joint capsule only"],"a":1,"why":"Resisted contraction stresses muscles and tendons, so pain suggests a contractile tissue problem.","t":"Assessment & Treatment Planning"},{"q":"When should the health history intake form be completed and updated?","c":["After the first massage only","During the massage","Never after the first visit","Before the first session and updated regularly"],"a":3,"why":"Intake information guides safe treatment and should be reviewed at each visit to catch any changes.","t":"Assessment & Treatment Planning"},{"q":"A treatment plan should be based primarily on:","c":["The therapist's preferred routine","The session length only","The latest technique learned","Assessment findings and the client's stated goals"],"a":3,"why":"Effective plans respond to what the assessment shows and what the client wants to achieve.","t":"Assessment & Treatment Planning"},{"q":"The straight leg raise test is commonly used to assess:","c":["Shoulder impingement","Hamstring length and lumbar nerve root tension","Carpal tunnel compression","Ankle instability"],"a":1,"why":"Raising the extended leg passively tests hamstring flexibility and can reveal sciatic nerve irritation.","t":"Assessment & Treatment Planning"},{"q":"Phalen's test, holding the wrists in flexion, is used to screen for:","c":["Carpal tunnel syndrome","Thoracic outlet syndrome","Tennis elbow","Rotator cuff tear"],"a":0,"why":"Sustained wrist flexion compresses the median nerve and reproduces symptoms if carpal tunnel syndrome is present.","t":"Assessment & Treatment Planning"},{"q":"The Thomas test is used to assess shortness of the:","c":["Hamstrings","Piriformis","Hip flexors","Gastrocnemius"],"a":2,"why":"In the Thomas test, if the opposite thigh lifts off the table as one knee is brought to the chest, the hip flexors are tight.","t":"Assessment & Treatment Planning"},{"q":"What is the normal adult resting heart rate range?","c":["40 to 60 beats per minute","60 to 100 beats per minute","100 to 120 beats per minute","120 to 140 beats per minute"],"a":1,"why":"A typical resting adult heart rate is 60 to 100 beats per minute.","t":"Assessment & Treatment Planning"},{"q":"What is the main value of a 0 to 10 pain scale rating in client records?","c":["Tracking changes in perceived pain across sessions","Diagnosing the source of pain","Replacing the need for palpation","Setting the session price"],"a":0,"why":"The pain scale is a subjective measure that lets the therapist compare client-reported pain over time.","t":"Assessment & Treatment Planning"},{"q":"After a session, a therapist asks the client about changes in pain and mobility and records them. This is called:","c":["Intake","Referral","Reassessment","Draping"],"a":2,"why":"Reassessment evaluates the effects of treatment and informs adjustments to the treatment plan.","t":"Assessment & Treatment Planning"},{"q":"Which massage system is based on the strokes effleurage, petrissage, friction, tapotement and vibration?","c":["Shiatsu","Reflexology","Rolfing","Swedish massage"],"a":3,"why":"These five categories of strokes form the foundation of Swedish massage.","t":"Massage History & Modalities"},{"q":"Shiatsu, meaning 'finger pressure,' originated in which country?","c":["Sweden","India","Japan","Greece"],"a":2,"why":"Shiatsu is a Japanese bodywork form that applies pressure along energy pathways (meridians) with the fingers, thumbs and palms.","t":"Massage History & Modalities"},{"q":"Reflexology is based on the premise that points on the feet, hands and ears correspond to:","c":["Only the skin layers","Only the muscles of the arm","Only the joints","Organs and body systems"],"a":3,"why":"Reflexology applies pressure to reflex areas believed to correspond to specific body organs and systems.","t":"Massage History & Modalities"},{"q":"Myofascial release techniques typically involve:","c":["Rapid percussion","Sustained pressure and stretch applied to fascia","Rhythmic lymph pumping","Acupressure on meridian points"],"a":1,"why":"Myofascial release uses slow, sustained pressure to lengthen restricted fascia and improve mobility.","t":"Massage History & Modalities"},{"q":"A trigger point is best described as a hyperirritable spot in a taut band of muscle that can produce:","c":["Referred pain","Fever","Generalized edema","Decreased sensation"],"a":0,"why":"Trigger points can cause local tenderness and pain felt in a distant area, known as referred pain.","t":"Massage History & Modalities"},{"q":"Manual lymphatic drainage uses which type of technique?","c":["Very light, slow, rhythmic skin-stretching strokes","Deep, fast, percussive pounding","Heavy sustained compression on muscles","Aggressive cross-fiber friction"],"a":0,"why":"Light pressure is used because lymph capillaries lie just beneath the skin.","t":"Massage History & Modalities"},{"q":"Contrast hydrotherapy involves:","c":["Applying only dry heat","Alternating hot and cold water applications","Applying cold only for one hour","Immersion in salt water only"],"a":1,"why":"Alternating hot and cold produces repeated vasodilation and vasoconstriction, sometimes called a vascular pump effect.","t":"Massage History & Modalities"},{"q":"A client asks a massage therapist to diagnose the cause of persistent knee pain. Diagnosing is:","c":["Permitted if the client requests it","Permitted after five years of experience","Outside a massage therapist's scope of practice","Required before treatment begins"],"a":2,"why":"Massage therapists do not diagnose medical conditions; they assess soft tissue and refer when needed.","t":"Ethics, Boundaries & Law"},{"q":"A dual relationship exists when a therapist:","c":["Treats two clients at once","Works at two locations","Holds two credentials","Has another role with the client besides therapist, such as friend or employer"],"a":3,"why":"Dual relationships can blur boundaries and create conflicts of interest or exploitation risks.","t":"Ethics, Boundaries & Law"},{"q":"A client's health information may be shared with a third party when:","c":["The person is a relative of the client","The client's employer asks about the session","The therapist thinks it may interest a colleague","The client gives written consent"],"a":3,"why":"Confidentiality requires written permission from the client, except where law requires disclosure.","t":"Ethics, Boundaries & Law"},{"q":"HIPAA primarily protects:","c":["Therapist income","Business names","Privacy of individually identifiable health information","Insurance premiums"],"a":2,"why":"HIPAA sets standards for safeguarding individually identifiable health information.","t":"Ethics, Boundaries & Law"},{"q":"Informed consent means the client:","c":["Understands the nature, benefits and risks of treatment and agrees voluntarily","Signed once and may never withdraw","Trusts the therapist without questions","Has paid in advance"],"a":0,"why":"Consent must be informed and voluntary, and the client can withdraw it at any time.","t":"Ethics, Boundaries & Law"},{"q":"During a full-body massage, which area must always remain covered by the drape?","c":["The upper back","The genitals","The shoulders","The lower legs"],"a":1,"why":"Professional draping keeps the genitals covered at all times and only the area being worked is undraped.","t":"Ethics, Boundaries & Law"},{"q":"A client makes a sexual comment during a session. What is the best response?","c":["Ignore it and continue","State the boundary clearly and end the session if the behavior continues","Reciprocate to avoid offense","Joke about it"],"a":1,"why":"The therapist must establish clear boundaries, and sexual behavior is never part of professional massage.","t":"Ethics, Boundaries & Law"},{"q":"How should client records be handled?","c":["Kept at the front desk for easy access","Discarded when payment clears","Stored securely so only authorized people can access them","Posted on the studio wall"],"a":2,"why":"Records contain private health information and must be kept confidential and secure.","t":"Ethics, Boundaries & Law"},{"q":"A client asks whether to change a prescribed medication dose. What is the best response?","c":["Suggest a lower dose","Recommend herbal alternatives","Offer a dosage based on experience","Refer the question to the prescribing physician or pharmacist"],"a":3,"why":"Advising on medication is outside massage scope; the prescriber or pharmacist is the appropriate source.","t":"Ethics, Boundaries & Law"},{"q":"When may a therapist ethically decline to treat a client?","c":["When the treatment is outside their training or would be unsafe","When the client follows a particular religion","When the client is of another ethnicity","When the client is one minute late"],"a":0,"why":"Therapists may refuse treatment that exceeds their competence or is unsafe, but may not discriminate.","t":"Ethics, Boundaries & Law"},{"q":"Which statement about the therapist-client power differential is correct?","c":["The client alone is responsible for maintaining boundaries","Boundaries matter only with new clients","The therapist holds greater power and is responsible for maintaining boundaries","The differential ends once they become friends"],"a":2,"why":"Because clients are vulnerable and trusting, the therapist bears responsibility for professional boundaries.","t":"Ethics, Boundaries & Law"},{"q":"Which practice is consistent with ethical business conduct regarding fees?","c":["Quoting fees only after the session","Clearly communicating fees and policies before services begin","Changing fees during the session","Keeping fees secret from clients"],"a":1,"why":"Transparency about fees and policies allows clients to make informed choices.","t":"Ethics, Boundaries & Law"},{"q":"A client's condition is beyond the therapist's scope of practice. What should the therapist do?","c":["Refer the client to an appropriate healthcare provider","Treat the condition anyway","Ignore the condition","Make a diagnosis"],"a":0,"why":"Referral protects the client and keeps the therapist within their scope of practice.","t":"Ethics, Boundaries & Law"},{"q":"Which advertising claim is ethically acceptable for a massage therapist?","c":["Cures cancer","Guaranteed to eliminate arthritis","Replaces your doctor's treatments","Massage can help relieve muscle tension"],"a":3,"why":"Advertising must be truthful and avoid unsupported medical claims or guarantees.","t":"Ethics, Boundaries & Law"},{"q":"How should the therapist protect client privacy during undressing?","c":["Leave the room while the client undresses and gets on the table","Stay to help the client","Watch to ensure safety","Require the client to be nude"],"a":0,"why":"Clients should be given privacy to undress to their comfort level and be draped before the therapist returns.","t":"Ethics, Boundaries & Law"},{"q":"Which behavior is a violation of professional boundaries?","c":["Asking whether the pressure is comfortable","Washing hands before the session","Keeping appointment records","Discussing the therapist's personal sexual problems with a client"],"a":3,"why":"Sharing intimate personal information shifts the focus away from the client and blurs professional boundaries.","t":"Ethics, Boundaries & Law"},{"q":"Which stance supports good body mechanics at the massage table?","c":["Feet together with locked knees","Staggered stance with soft knees and weight shifting","Bending at the waist with a rounded back","Twisting the trunk while keeping feet planted"],"a":1,"why":"A staggered stance with soft knees lets the therapist use body weight rather than the arms and protects the back.","t":"Professional Practice"},{"q":"For general massage work, table height is typically adjusted so that it is about:","c":["Level with the therapist's chest","Level with the therapist's shoulders","The height of the therapist's fingertips or knuckles with arms relaxed","Level with the therapist's knees"],"a":2,"why":"This height allows the therapist to use body weight effectively without excessive reaching or bending.","t":"Professional Practice"},{"q":"When should a massage therapist wash their hands?","c":["Only at the end of the day","Only if visibly soiled","Only before the first client","Before and after every client session"],"a":3,"why":"Handwashing before and after each client is the most effective way to prevent spreading pathogens.","t":"Professional Practice"},{"q":"How should linens that have touched a client be handled?","c":["Laundered between clients using hot water and detergent","Shaken out and reused","Reused for the same client without washing","Spot cleaned only"],"a":0,"why":"Used linens must be laundered between clients to prevent cross-contamination.","t":"Professional Practice"},{"q":"Professional liability insurance protects a massage therapist against:","c":["Lost income during vacations","Personal income taxes","Claims of client injury or negligence","Depreciation of equipment"],"a":2,"why":"Liability insurance covers legal costs and damages from claims that a client was harmed through the therapist's services.","t":"Professional Practice"},{"q":"Which practice best helps prevent overuse injury for a therapist?","c":["Using only the thumbs for all deep work","Varying techniques and taking breaks between sessions","Working without breaks","Ignoring pain and continuing"],"a":1,"why":"Varying techniques and allowing recovery time reduce repetitive strain.","t":"Professional Practice"},{"q":"What is the term for destroying most harmful microorganisms on nonporous surfaces?","c":["Sterilization","Disinfection","Washing","Deodorizing"],"a":1,"why":"Disinfection destroys most pathogens, while sterilization destroys all microbial life.","t":"Professional Practice"},{"q":"An independent contractor therapist is generally responsible for:","c":["Receiving employer-paid benefits","Having taxes withheld by the business","Following a schedule set by an employer","Paying their own self-employment taxes"],"a":3,"why":"Independent contractors are self-employed and handle their own taxes, insurance and business expenses.","t":"Professional Practice"},{"q":"Which draping practice best maintains client comfort and modesty?","c":["Undraping only the area being worked and re-covering it when finished","Removing the sheet completely for easier access","Draping only if the client requests it","Leaving the drape loose across the table"],"a":0,"why":"Undraping only the area being worked keeps the client covered and respects privacy.","t":"Professional Practice"},{"q":"Why is a bolster placed under a supine client's knees?","c":["It increases the lumbar curve","It compresses the calf muscles","It eases the lower back by slightly flexing the hips and knees","It limits the client's breathing"],"a":2,"why":"Slight hip and knee flexion relaxes the hip flexors and reduces strain on the lumbar spine.","t":"Professional Practice"}],"braider":[{"q":"Washing combs with soap and water to remove visible hair and debris is best described as which step?","c":["Sterilization","Disinfection","Cleaning","Bloodborne decontamination"],"a":2,"why":"Cleaning physically removes soil and debris using soap and water. It must be done before disinfecting, but it does not kill germs on its own.","t":"Disinfection"},{"q":"What must be done to a comb before it is placed in disinfectant?","c":["Wash it with soap and water to remove debris","Rinse it quickly with plain cool water only","Wrap it in a clean towel and let it dry first","Coat it lightly with oil to prevent rust"],"a":0,"why":"Disinfectants cannot work properly on soiled surfaces, so tools must be cleaned of hair and residue first.","t":"Disinfection"},{"q":"How should an EPA-registered disinfectant be used on non-porous braiding tools?","c":["Mixed weaker than directed to save product","Rinsed off in a few seconds after dipping","Applied over tools that still have hair on them","Used at label strength for the full contact time"],"a":3,"why":"Disinfectants only work when mixed as directed and left in contact with a clean surface for the full time listed on the label.","t":"Disinfection"},{"q":"Which item must be thrown away after one client because it cannot be properly disinfected?","c":["Plastic sectioning clip","Disposable neck strip","Metal rattail comb","Hard rubber comb"],"a":1,"why":"Paper and other porous items absorb liquids and cannot be disinfected, so they are single-use. Non-porous tools can be cleaned and disinfected.","t":"Disinfection"},{"q":"Which group lists bloodborne pathogens?","c":["Ringworm, favus and scabies","Hepatitis B, hepatitis C and HIV","Dandruff, eczema and psoriasis","Head lice, nits and mites"],"a":1,"why":"Hepatitis B, hepatitis C and HIV are spread through blood and certain body fluids. The other lists are skin conditions or parasites.","t":"Bloodborne Pathogens"},{"q":"A tool nicks a client's scalp and it bleeds slightly. What should the braider do first?","c":["Wipe it with a towel and keep braiding","Cover the cut with a layer of edge gel","Rinse it with cold water and keep working","Stop, put on gloves, clean the cut and bandage it"],"a":3,"why":"Blood contact is an exposure risk. Stop work, wear gloves, clean the area and cover it before continuing, and dispose of contaminated items safely.","t":"Bloodborne Pathogens"},{"q":"Which routine is best for hand hygiene before a braiding service?","c":["Wash with liquid soap and water for about 20 seconds","Rinse quickly under water without using soap","Dry hands on a towel used for earlier clients","Rub a small amount of styling gel on the hands"],"a":0,"why":"Thorough handwashing with soap and water, including between fingers, removes germs and reduces the risk of cross-contamination.","t":"Hand Hygiene"},{"q":"What information does a Safety Data Sheet (SDS) provide about a product?","c":["A list of nearby suppliers and prices","The product's advertising claims","Hazards, safe handling and first-aid information","Proof that the product is approved for scalp use"],"a":2,"why":"An SDS explains a product's hazards, how to handle and store it safely, and what to do after exposure.","t":"Safety Data Sheets"},{"q":"Where should used braiding tools be kept until they can be cleaned and disinfected?","c":["In a closed container labeled for used tools","In the same drawer with the clean tools","In an open jar on the station counter","In the pocket of the braider's apron"],"a":0,"why":"Separating used tools in a labeled, closed container prevents cross-contamination of clean, disinfected tools.","t":"Cross-Contamination"},{"q":"A client arrives with live lice crawling in her hair. What is the correct response?","c":["Braid quickly so the lice are trapped","Spray the scalp with disinfectant","Decline service and suggest she seek treatment","Shampoo her hair, then continue with braids"],"a":2,"why":"Head lice are contagious, so service should be declined until the infestation has been treated. Disinfectants must never be sprayed on a client's scalp.","t":"Contagious Conditions"},{"q":"Which statement best describes universal (standard) precautions?","c":["Treat only clients who look visibly ill as infectious","Treat all blood and body fluids as potentially infectious","Wear gloves only when performing chemical services","Refuse service to every client who has an infection"],"a":1,"why":"Universal precautions mean treating every client's blood and body fluids as if they could carry infection, so protection is consistent.","t":"Bloodborne Pathogens"},{"q":"How should a cotton pad soaked with blood be handled after a service?","c":["Dropped in the regular trash with no precautions","Rinsed and reused on the next client","Placed in a pocket to discard later at home","Sealed in a bag or labeled biohazard container"],"a":3,"why":"Items contaminated with blood should be contained in sealed bags or labeled biohazard containers to protect others from exposure. Exact disposal rules vary, so follow your state board's requirements.","t":"Bloodborne Pathogens"},{"q":"How should capes and towels be handled after use on a client?","c":["Shaken out and then reused for the next client","Folded and put away with the other clean towels","Hung on the back of the chair until closing time","Put in a closed container and laundered before reuse"],"a":3,"why":"Used linens carry hair, oils and germs. They go into a closed container and are laundered before they touch another client.","t":"Cross-Contamination"},{"q":"Which statement correctly describes sterilization?","c":["Reducing germs on the skin with a hand rub","Destroying all microbial life, including spores","Removing visible soil from tools with soap","Killing most germs on a non-porous surface"],"a":1,"why":"Sterilization destroys all microorganisms, including bacterial spores. Disinfection kills most, but not all, pathogens on non-porous surfaces.","t":"Disinfection"},{"q":"What does the contact time on a disinfectant label refer to?","c":["How long the bottle may be stored once opened","How long tools must air dry after soaking","How long the surface must stay wet with the product","How long the braider must wear gloves"],"a":2,"why":"Contact time is the period a surface must remain visibly wet with the disinfectant for it to kill the listed organisms.","t":"Disinfection"},{"q":"Which situation is an exposure incident?","c":["Blood or body fluid contacting broken skin or mucous membranes","Any visit from a client who mentions a skin condition","Using a tool more than once during the same workday","A client declining a service after the consultation ends"],"a":0,"why":"An exposure incident is contact of blood or other infectious material with broken skin, eyes, mouth or other mucous membranes.","t":"Bloodborne Pathogens"},{"q":"When should disposable gloves be changed?","c":["Only after they have visibly torn","Only at the end of each workday","After each client or when contaminated","Only when a client asks for new ones"],"a":2,"why":"Gloves protect only when fresh. They must be removed and replaced between clients and after contact with blood or body fluids.","t":"Hand Hygiene"},{"q":"Where should clean, disinfected tools be stored?","c":["In an open basket beside the station","In the braider's bag with used tools","On the counter next to the product spray","In a clean, closed and labeled container"],"a":3,"why":"A closed, labeled container keeps disinfected tools from being contaminated by dust, hair or contact with used items.","t":"Cross-Contamination"},{"q":"Why should different disinfectants or cleaning products never be mixed together?","c":["The mixture will stop smelling clean","The mixture may release harmful fumes","The mixture will only change color","The mixture will cost more to use"],"a":1,"why":"Mixing chemicals can cause dangerous reactions and toxic fumes. Always use products one at a time exactly as the label directs.","t":"Chemical Safety"},{"q":"Which practice best prevents cross-contamination at the station between clients?","c":["Disinfecting the chair and work surface","Wiping the station with a dry paper towel","Spraying fragrance on the chair","Handing the same towel to the next client"],"a":0,"why":"Cleaning and disinfecting all surfaces the client touched removes pathogens before the next client sits down.","t":"Cross-Contamination"},{"q":"What is the visible portion of the hair above the scalp called?","c":["Hair shaft","Hair bulb","Hair follicle","Papilla"],"a":0,"why":"The shaft is the part of the hair that extends above the skin. The follicle, bulb and papilla are located beneath the scalp surface.","t":"Hair Structure"},{"q":"Which hair layer is made of overlapping scales that protect the inner strand?","c":["Medulla","Cuticle","Cortex","Papilla"],"a":1,"why":"The cuticle is the outermost layer. Its overlapping scales protect the cortex and control how much moisture enters the strand.","t":"Hair Structure"},{"q":"Which layer holds most of the hair's pigment, strength and elasticity?","c":["Cuticle","Medulla","Epidermis","Cortex"],"a":3,"why":"The cortex is the middle layer that gives hair its strength, elasticity and natural color.","t":"Hair Structure"},{"q":"What is the anagen phase of the hair growth cycle?","c":["The resting phase","The transition phase","The active growth phase","The shedding phase"],"a":2,"why":"Anagen is the active growth phase. Catagen is the short transition phase, and telogen is the resting phase.","t":"Growth Cycle"},{"q":"About how many hairs does a person normally shed each day?","c":["10 to 20 hairs","50 to 100 hairs","200 to 300 hairs","More than 500 hairs"],"a":1,"why":"Losing roughly 50 to 100 hairs a day is normal shedding as hairs finish their growth cycle and are replaced.","t":"Growth Cycle"},{"q":"Hair porosity refers to the hair's ability to do what?","c":["Absorb and hold moisture","Stretch and return to its length","Show how tightly it curls","Produce its own natural oil"],"a":0,"why":"Porosity describes how easily moisture and products pass into and out of the hair, which depends on the condition of the cuticle.","t":"Porosity"},{"q":"Which description fits high-porosity hair?","c":["It resists water entering the strand","It holds its shape without any product","It absorbs water quickly but dries out fast","It has a tightly closed cuticle layer"],"a":2,"why":"High-porosity hair has a raised or damaged cuticle, so it takes in moisture easily but also loses it quickly.","t":"Porosity"},{"q":"What does hair density describe?","c":["The width of each individual strand","How tightly each strand curls in a pattern","How far a strand stretches without breaking","The number of hairs per square inch of scalp"],"a":3,"why":"Density is how many hairs grow in a given area of scalp, often described as thin, medium or thick. It is different from strand texture.","t":"Hair Analysis"},{"q":"How can hair elasticity be checked?","c":["Weighing a single strand on a tiny scale","Measuring the length of a strand with a ruler","Rinsing the hair with warm water and drying","Gently stretching a strand to see if it returns"],"a":3,"why":"Healthy hair stretches and then returns to its original length. Hair that stretches and stays stretched, or snaps, has poor elasticity.","t":"Hair Analysis"},{"q":"Fine, medium and coarse are terms used to describe a hair's what?","c":["Density","Porosity","Texture","Elasticity"],"a":2,"why":"Texture refers to the diameter of an individual strand. Density counts hairs per area, and porosity refers to moisture absorption.","t":"Hair Analysis"},{"q":"What causes traction alopecia?","c":["Repeated pulling and tension on the follicles","A fungal infection of the scalp","An autoimmune reaction at the follicle","An allergy to a hair fiber"],"a":0,"why":"Traction alopecia is hair loss from long-term tension on the follicles, often from tight braids, ponytails or heavy extensions.","t":"Scalp Conditions"},{"q":"Which are early warning signs of traction alopecia?","c":["Greasy yellow flakes spread across the whole crown","Tenderness, small bumps and thinning at the hairline","Smooth round bald patches on the top of the scalp","Sudden thick growth of hair along the jawline"],"a":1,"why":"Soreness, bumps and thinning along the hairline are early signs of tension damage. Catching them early allows the hair to recover.","t":"Scalp Conditions"},{"q":"Which statement best describes folliculitis?","c":["A parasitic infestation of the hair","Inflammation or infection of hair follicles","A ring-shaped fungal patch on the scalp","Increased shedding after a stressful event"],"a":1,"why":"Folliculitis is inflammation or infection of the follicles, often showing as small red bumps or pustules around hairs.","t":"Scalp Conditions"},{"q":"What is tinea capitis commonly called?","c":["Dandruff","Head lice","Scalp ringworm","Eczema"],"a":2,"why":"Tinea capitis is a contagious fungal infection of the scalp, commonly known as scalp ringworm.","t":"Scalp Conditions"},{"q":"A client has scaly, round patches with broken hairs on her scalp. What should the braider do?","c":["Braid over the patches with extra gel","Apply scalp oil to soothe the area","Go ahead but avoid touching the patches","Decline service and refer her to a physician"],"a":3,"why":"These signs suggest a contagious fungal infection. Service must be declined, and the client referred for medical diagnosis and treatment.","t":"Scalp Conditions"},{"q":"Which statement correctly describes dandruff?","c":["Dry or oily flakes shed from the scalp, not contagious","Painful pus-filled sores that spread by touch","Live insects and eggs attached to the hair","Round bald patches with broken hairs"],"a":0,"why":"Dandruff causes flaking of the scalp and is not contagious, so service can usually be performed. Severe or persistent cases may need a referral.","t":"Scalp Conditions"},{"q":"What are nits?","c":["Eggs of head lice attached to the hair","Adult head lice moving on the scalp","Fungal spores found on the scalp","Dried flakes of scalp skin"],"a":0,"why":"Nits are the small eggs laid by head lice and cemented to the hair shaft near the scalp.","t":"Scalp Conditions"},{"q":"Type 4 hair is typically described as having what pattern?","c":["Straight strands with no bend","Loose S-shaped waves","Defined spiral ringlets","Tight coils or zigzag patterns"],"a":3,"why":"Type 4 hair is the most tightly coiled category, with small coils or a zigzag pattern. Type 1 is straight, type 2 wavy and type 3 curly.","t":"Curl Patterns"},{"q":"Why is tightly coiled hair often prone to dryness?","c":["It produces far more sebum than other hair","Its cuticle is always thicker","Natural oils travel slowly down the curved strand","It has no oil glands at the scalp"],"a":2,"why":"The bends of a coil make it hard for sebum to travel down the shaft, so lengths and ends can lack moisture.","t":"Curl Patterns"},{"q":"What is the role of the papilla in the hair follicle?","c":["Producing sebum to lubricate the hair shaft","Feeding the growing hair with blood supply","Raising the hair upright when the body is cold","Storing sweat inside the scalp until needed"],"a":1,"why":"The papilla contains the blood supply that nourishes the cells of the hair bulb so new hair can form.","t":"Hair Structure"},{"q":"What should a braider do before beginning any braiding service?","c":["Start sectioning right away to save time","Choose the extension color without asking the client","Hold a consultation and examine the hair and scalp","Apply edge control before checking the scalp"],"a":2,"why":"A consultation and analysis of the hair and scalp reveal conditions, hair strength and client goals before work starts.","t":"Consultation"},{"q":"Why does a braider part the hair before braiding?","c":["To remove tangles from the ends","To create clean, even sections","To tighten the hair for lasting hold","To add moisture to each section"],"a":1,"why":"Clean, even parting gives the braids a neat pattern, balances the weight and helps keep tension consistent.","t":"Parting and Sectioning"},{"q":"How are traditional cornrows made?","c":["Close to the scalp in continuous rows, picking up hair along the part","Loose and free-hanging from the roots down","Wrapped around rods and set with heat tools","Only on the ends of the natural hair strands"],"a":0,"why":"Cornrows are braided close to the scalp in continuous rows, with hair picked up from the scalp as the braid moves along the part.","t":"Cornrows"},{"q":"Which describes a standard three-strand braid?","c":["Two strands twisted around each other in a spiral","Four strands woven together into a flat square","One long strand coiled around a heated rod","Three strands crossed over the middle in turn"],"a":3,"why":"A three-strand plait is formed by repeatedly crossing the outer strands over (or under) the middle strand in turn.","t":"Braiding Basics"},{"q":"What defines box braids?","c":["Rows that lie flat against the whole scalp","Two-strand twists left with unsealed ends","Hair rolled and pinned into a bun on the head","Free-hanging braids on square-parted sections"],"a":3,"why":"Box braids hang freely from the scalp and are parted in squares or boxes, with or without extensions.","t":"Box Braids"},{"q":"How does a knotless braid begin?","c":["With natural hair, then extension is fed in slowly","With a firm knot of extension hair tied at the root","With a rubber band wrapped tightly at the scalp base","With a bead slid over the whole section first"],"a":0,"why":"Knotless braids start with the client's own hair and add small amounts of extension as the braid goes down, so no bulky knot sits at the root.","t":"Knotless Braids"},{"q":"Why do many braiders choose knotless braids for clients with sensitive scalps?","c":["They always take much less time to install","They avoid a bulky extension knot sitting at the root","They require no parting of the natural hair","They remove the need for any later aftercare"],"a":1,"why":"Starting with natural hair and feeding in extension gradually avoids a bulky knot at the base, which can reduce pulling and weight on the follicle. Tension still depends on how tightly the braid is installed.","t":"Knotless Braids"},{"q":"What does the feed-in technique mean for cornrows?","c":["Extension hair is applied all at once at the start","Extension hair is attached to the scalp with adhesive","Extension hair is added gradually in small pieces","Extension hair is left out so only natural hair shows"],"a":2,"why":"Feeding in small amounts of hair gradually creates a natural-looking start, lighter weight and a smoother, flatter braid.","t":"Feed-In Technique"},{"q":"What is the main hazard of sealing synthetic braid ends with an open flame?","c":["Fading of the extension color","Burns and fire from melting fiber","Softer, frizzier braid ends","Slower drying of the braids"],"a":1,"why":"Synthetic fiber melts and can drip or ignite, causing burns to the client or fire. Heat sealing must be done carefully and away from skin and hair.","t":"Heat Sealing Safety"},{"q":"Which is a sound guideline for safe braiding tension?","c":["Tighter braids at the temples last the longest","Pulling until the skin lifts gives the neatest finish","Small bumps at the base show the braid is secure","Braids should feel secure without pain, bumps or skin pulling"],"a":3,"why":"Braids that cause pain, bumps or skin pulling are too tight and risk damage. Secure but comfortable tension protects the follicles.","t":"Safe Tension"},{"q":"A client says her scalp hurts during braiding. What should the braider do?","c":["Say it will loosen in a few days","Add oil to the scalp when finished","Loosen or redo the braid causing the pain","Suggest she take pain medication"],"a":2,"why":"Pain during braiding is a sign of too much tension. Respond right away by loosening or redoing the braid to prevent damage.","t":"Safe Tension"},{"q":"Which area of the head is most vulnerable to tension damage?","c":["The fine hair at the hairline and temples","The thick hair at the mid-crown","The coarse hair at the back of the head","The longest lengths at the ends"],"a":0,"why":"Hair at the hairline and temples is finer and more fragile, so tension there leads to breakage and traction alopecia quickest.","t":"Safe Tension"},{"q":"Kanekalon is best described as what?","c":["Natural human hair collected from many donors","A natural blend of cotton and wool threads","A lightweight synthetic fiber used for braiding","A thin metal wire wrapped in human hair"],"a":2,"why":"Kanekalon is a synthetic fiber widely used for braids, twists and locs extensions because it is light and holds a style well.","t":"Extension Hair"},{"q":"Which statement about standard synthetic braiding fiber is true?","c":["It can melt or fuse if exposed to high heat","It absorbs moisture the way natural hair does","It can be permanently colored with hair dye","It grows and sheds like the client's hair"],"a":0,"why":"Most synthetic fibers are plastic-based, so high heat can melt or fuse them. They also do not absorb products or color like human hair.","t":"Extension Hair"},{"q":"Pre-stretched braiding hair is popular because it does what?","c":["Is permanently colored and heat resistant","Has tapered ends that blend and reduce bulk","Never needs to be separated before braiding","Needs no sealing at the ends once braided"],"a":1,"why":"Pre-stretched hair has tapered, softer ends, so it blends into the braid with less bulk and saves preparation time.","t":"Extension Hair"},{"q":"What can extension hair that is too heavy for the client's natural hair cause?","c":["Faster hair growth","Improved moisture retention","Stronger edges","Strain on follicles and breakage"],"a":3,"why":"Heavy extensions pull on the roots, which can cause pain, breakage and traction alopecia.","t":"Extension Hair"},{"q":"What should a braider consider most when choosing the size of the sections?","c":["The color of the extension hair she picks","The length of time the client has booked","The brand name of the braiding hair used","The strength and density of her natural hair"],"a":3,"why":"Section size must suit the natural hair's strength and density, or the weight and tension could damage fragile hair.","t":"Parting and Sectioning"},{"q":"When detangling coily hair before braiding, where is the best place to start?","c":["At the roots, pulling the comb down in long strokes","At the ends, working gradually up toward the roots","At the middle, pulling the hair outward","At the nape, using a fine-tooth comb on dry hair"],"a":1,"why":"Detangling from the ends up prevents knots from tightening and reduces breakage and pain.","t":"Preparation"},{"q":"Which tool is best for detangling tightly coiled hair?","c":["A wide-tooth comb","A fine-tooth comb","A metal rattail comb","A stiff bristle brush"],"a":0,"why":"A wide-tooth comb passes through coils with less snagging and breakage than a fine-tooth comb or stiff brush.","t":"Preparation"},{"q":"Which is a common way to start locs?","c":["Gluing extension hair to the scalp","Pressing the hair straight each day","Making coils or two-strand twists in sections","Applying a chemical relaxer to the hair"],"a":2,"why":"Locs are commonly started with comb coils, two-strand twists or braids in sections, which then mature over time.","t":"Locs"},{"q":"What does interlocking refer to in loc maintenance?","c":["Pulling the loc through its base to hold new growth","Brushing the loc open to remove frizz and lint","Cutting new growth back flush with the scalp","Soaking the loc in water to loosen the coil"],"a":0,"why":"Interlocking threads the loc through its base in a pattern to hold new growth in place without relying on twisting alone.","t":"Locs"},{"q":"What can retwisting or interlocking locs too tightly at the roots cause?","c":["Quicker scalp cleansing","Better moisture retention","Traction on the follicles","Faster curl definition"],"a":2,"why":"Repeated tight maintenance pulls on the follicles and can cause soreness, breakage and traction alopecia.","t":"Locs"},{"q":"How are two-strand twists made?","c":["Weaving three strands over and under","Wrapping a whole section around a rod","Rolling a single strand into a spiral","Twisting two strands around each other"],"a":3,"why":"A section is divided into two strands, each twisted in one direction and then wrapped around the other in the opposite direction.","t":"Twists"},{"q":"Why are the ends of synthetic braids sealed?","c":["To add color to the ends","To keep the ends from unraveling","To make the braids longer","To help the scalp breathe"],"a":1,"why":"Sealing the ends of synthetic fiber fuses it and keeps the braid from coming undone.","t":"Sealing Ends"},{"q":"Which method is commonly used to seal the ends of synthetic braids?","c":["Soaking the ends in cold water overnight","Rubbing the ends with oil and a towel","Dipping in hot water or using a sealing tool","Wrapping the ends tightly in foil paper"],"a":2,"why":"Hot water or controlled heat sets synthetic fiber ends so they hold. Keep heat and hot liquids away from the client's skin.","t":"Sealing Ends"},{"q":"When removing box braids, where should scissors be used?","c":["Right at the scalp to release the braid quickly","Through the middle of the natural hair","Anywhere along the braid, since hair is protected","Only in the extension portion, away from natural hair"],"a":3,"why":"Cut only the extension hair, well away from the natural hair, to avoid cutting the client's own strands.","t":"Take-Down"},{"q":"How can breakage be reduced during take-down?","c":["Soften hair with a detangler as sections are released","Pull each section free quickly in a single motion","Brush the hair dry from the roots to the ends","Keep it completely dry so the fingers grip better"],"a":0,"why":"Moisture and slip help shed hair come out of the braid and detangle gently, which lowers breakage.","t":"Take-Down"},{"q":"What can happen when braids are left in for too long?","c":["Stronger and healthier roots overall","Matting and breakage at the new growth","Faster hair growth at the new roots","Fewer shed hairs inside the braids"],"a":1,"why":"As new growth appears, shed hair and buildup collect and mat, making take-down harder and risking breakage.","t":"Maintenance"},{"q":"In braiding, what are the edges?","c":["The ends of the longest hair","The fine, delicate hair along the hairline","The hair at the center of the crown","The hair at the back of the neck only"],"a":1,"why":"The edges are the fine, fragile hairs along the front and sides of the hairline. They are the easiest to damage with tension.","t":"Edges"},{"q":"Which practice best protects the edges?","c":["Using lighter, looser braids at the hairline","Pulling the edges back tightly for neatness","Installing the heaviest braids at the temples","Brushing the edges firmly with a stiff brush"],"a":0,"why":"Light, gentle braids at the hairline limit pulling on the fine hair, helping prevent breakage and thinning.","t":"Edges"},{"q":"A client returns with painful, pimple-like bumps at the base of her braids. What is the best advice?","c":["Add more gel and grease to soothe the roots","Re-braid the sore sections slightly more tightly","Cover the bumps with thick oil and keep braids in","Loosen the braids and see a doctor if it persists"],"a":3,"why":"Bumps and soreness suggest too much tension or follicle irritation. Relieving tension and seeking medical advice for persistent problems is safest.","t":"Aftercare"},{"q":"Why is it recommended to rest the hair between protective styles?","c":["To keep the extension hair from relaxing","To make the next style hold even tighter","To let the follicles recover from tension","To save money on future product purchases"],"a":2,"why":"A break allows the scalp and hairline to recover from tension and gives the braider a chance to check for damage.","t":"Aftercare"},{"q":"What defines a protective style?","c":["It needs heat styling daily to maintain it","It leaves the ends out to face the weather","It uses a chemical coating to seal the hair","It tucks ends away and limits daily handling"],"a":3,"why":"Protective styles keep the fragile ends tucked away and reduce daily handling. They still cause damage if installed too tightly.","t":"Protective Styling"},{"q":"In an underhand (inverted) cornrow, each outer strand crosses which way over the middle strand?","c":["Over","Around","Under","Beside"],"a":2,"why":"In an underhand cornrow, the outer strands are crossed under the middle strand, creating a raised braid on top of the scalp.","t":"Cornrows"},{"q":"Why can braiding on very wet hair be a problem?","c":["The hair becomes more elastic and loosens","The hair shrinks as it dries and tightens the braid","The hair grows faster and pushes out the braid","The hair repels the extension fiber"],"a":1,"why":"Wet hair stretches and then shrinks as it dries, which increases tension on the scalp. Hair is best braided damp, not soaking wet.","t":"Safe Tension"},{"q":"A client wants long, heavy braids but has thin, fragile hair. What should the braider do?","c":["Recommend a lighter style her hair can support","Install them anyway to satisfy the client","Braid tightly so the weight holds","Add extra extension hair at the roots"],"a":0,"why":"Heavy braids can pull out fragile hair. A good braider offers a lighter, safer style rather than risking damage.","t":"Consultation"},{"q":"Which tool is commonly used to make a clean part?","c":["The tail of a rattail comb","A pair of shears","A wide-tooth pick","A bristle paddle brush"],"a":0,"why":"The fine tail of a rattail comb creates straight, precise parts for neat sections.","t":"Parting and Sectioning"},{"q":"A client has thinning at her temples from past tension. What is the best approach?","c":["Braid it the same as the rest of the hair","Skip the area or use very light, loose braids","Pull the braids tighter to hold in place","Use heavy extensions to cover the thin area"],"a":1,"why":"Fragile areas need rest and light handling. Minimal tension gives the follicles a chance to recover.","t":"Consultation"},{"q":"How is extension hair attached in a crochet braid install?","c":["With a bonding glue along the hairline","With a heated metal clip on each strand","With a latch hook looped onto cornrows","With rubber bands tied at every root"],"a":2,"why":"In crochet braiding, the natural hair is braided flat and a latch hook or needle loops the extension hair onto the braids.","t":"Crochet Braids"},{"q":"What should the braider check before the client leaves?","c":["Only that the payment was received in full","Only the length of the finished braids","Only the shine of the extension fiber on top","Symmetry, comfortable tension and skin health"],"a":3,"why":"A final check for even pattern, comfortable tension and healthy skin ensures quality and safety before the client leaves.","t":"Finishing"},{"q":"Where is a patch test for a new product or extension fiber usually performed?","c":["On the scalp at the crown of the head","Along the hairline near the temples","Behind the ear or on the inner forearm","On one strand of hair at the nape"],"a":2,"why":"A patch test checks the skin's reaction to a small amount of product or fiber in an inconspicuous place before use on a larger area.","t":"Patch Tests"},{"q":"A client has redness, swelling and itching at the patch test site. What does this mean?","c":["A possible allergy; avoid using the product","A good fit between the product and her skin","Normal tolerance, so the product is safe","The need to apply a much stronger amount"],"a":0,"why":"Redness, swelling or itching indicates a possible allergic reaction. Do not use the product on that client.","t":"Patch Tests"},{"q":"A client reports past scalp irritation from extension fibers. What should the braider do?","c":["Ignore it, as the cause was probably unrelated","Use the same fiber without mentioning it to her","Apply a thick gel to the scalp before installing","Discuss it and patch test or choose another fiber"],"a":3,"why":"Past irritation is a warning of sensitivity. Discuss alternatives and patch test before proceeding to prevent a reaction.","t":"Allergies"},{"q":"Which is a safe practice when using hair adhesive near the hairline?","c":["Apply it to skin that has cuts or irritation","Use only hair-labeled products and avoid broken skin","Mix glues from different brands for stronger hold","Substitute craft glue if the salon product runs out"],"a":1,"why":"Only use products made for hair, follow the directions and avoid broken or irritated skin to reduce chemical burns and allergic reactions.","t":"Adhesives"},{"q":"What can heavy gels or thick greases on the scalp cause?","c":["Better airflow to the follicles","Buildup that clogs the follicles","Healthier follicles overall","Faster drying of the hair"],"a":1,"why":"Heavy products can build up on the scalp, clog follicles and attract dirt, which can lead to irritation and folliculitis.","t":"Products"},{"q":"Before applying an oil or gel, what should the braider ask the client about?","c":["Her upcoming travel plans this month","Her favorite artist or kind of music","Her work schedule for the next week","Known allergies to nuts or fragrance"],"a":3,"why":"Asking about allergies before applying products helps prevent reactions caused by common allergens in oils, gels and fragrances.","t":"Allergies"},{"q":"How should oil be applied to the scalp after braiding?","c":["Sparingly, since too much causes buildup","Daily in large amounts","Only on freshly shampooed wet hair","As a replacement for ever washing the scalp"],"a":0,"why":"A light application moisturizes without clogging follicles. Scalp oil does not replace cleansing.","t":"Products"},{"q":"How should professional products be stored for safety?","c":["Uncapped near a heat source","In an unlabeled container to save space","In a closed, labeled container away from heat","Mixed together in one bottle"],"a":2,"why":"Closed, labeled containers kept away from heat prevent spills, contamination and mix-ups that could harm clients.","t":"Chemical Safety"},{"q":"A product splashes into a client's eyes. What is the first step?","c":["Wipe the eyes firmly with a dry towel","Rub oil around the eyes to soothe them","Cover both eyes with a bandage for a day","Flush with clean water and consult the SDS"],"a":3,"why":"Flushing the eyes with clean water right away reduces harm, and the SDS gives first-aid steps and tells whether medical care is needed.","t":"Chemical Safety"},{"q":"Why should products never be applied over open sores or broken skin?","c":["It can cause irritation and infection","It will lighten the hair","It makes braids shrink","It loosens the extension hair"],"a":0,"why":"Broken skin lets irritants and germs enter the body, which can cause pain, infection or an allergic reaction.","t":"Products"},{"q":"Which service generally falls outside natural hair braiding and requires a cosmetology license in most states?","c":["Cornrows","Two-strand twists","Applying a chemical relaxer","Sealing the ends of braids"],"a":2,"why":"In most states, braiding and natural hair care licenses or exemptions do not cover chemical services such as relaxers, perms or color. Confirm your own state's rules.","t":"Scope of Practice"},{"q":"Which aftercare advice is appropriate for new box braids?","c":["Avoid washing the scalp for at least three months","Keep the scalp clean and cover braids at night","Pull the braids tight each morning for neatness","Apply heavy grease to the scalp every single day"],"a":1,"why":"Keeping the scalp clean and lightly moisturized, and covering braids at night with a satin scarf or bonnet, protects the style and the hair.","t":"Aftercare"},{"q":"Why should a braider keep client records?","c":["To note allergies, scalp conditions and services","To justify charging higher prices to clients","To avoid needing a consultation at later visits","To share with other clients as style examples"],"a":0,"why":"Records of allergies, hair and scalp conditions, products and services help provide safe, consistent care at future visits.","t":"Record Keeping"},{"q":"What does client confidentiality require of a braider?","c":["Posting photos of scalp conditions with names","Sharing her history with other clients","Discussing her health in front of coworkers","Keeping her personal and health information private"],"a":3,"why":"Client information is private. Respecting confidentiality builds trust and protects the client's dignity.","t":"Ethics"},{"q":"When should a braider give the client the price and the time estimate?","c":["After the service is completely finished","Before starting, during the consultation","When the client is ready to pay at the end","Once the braids are about halfway done"],"a":1,"why":"Stating the cost and time before work begins prevents misunderstandings and lets the client agree to the terms.","t":"Pricing and Time"},{"q":"A client asks for a style the braider believes will damage her hair. What is the best response?","c":["Do the style she asked for without comment","Refuse the service and ask her to leave","Explain the risk and suggest safer options","Offer a discount and braid it a bit tighter"],"a":2,"why":"Honest, respectful communication lets the client make an informed choice and protects the braider's professional integrity.","t":"Client Communication"},{"q":"Which action is part of professional ethics for a braider?","c":["Diagnosing scalp disease and prescribing treatment","Being honest about skills and referring when needed","Guaranteeing that braids will make hair grow","Criticizing other braiders to attract clients"],"a":1,"why":"Ethical professionals stay within their scope, tell the truth and refer clients to the right provider when needed. Diagnosing is a medical task.","t":"Ethics"},{"q":"Why is a clear late and cancellation policy helpful?","c":["It lets the braider avoid talking with clients","It guarantees every client arrives early","It sets clear expectations for both client and braider","It replaces the need for appointments"],"a":2,"why":"A stated policy lets everyone know the expectations in advance, protecting the braider's time and reducing disputes.","t":"Pricing and Time"},{"q":"Why is a realistic time estimate important for long braiding services?","c":["It helps the client plan and keeps the braider from rushing","It lets the braider raise the price after the service","It allows the braider to skip breaks between clients","It removes the need for a client consultation first"],"a":0,"why":"Accurate estimates let the client plan and keep the braider from rushing, which can cause uneven or overly tight braiding.","t":"Pricing and Time"},{"q":"A client complains about her braids after leaving. What is the most professional response?","c":["Blame the problem on the client's hair type","Ignore the complaint and avoid her messages","Refund everything immediately without discussion","Listen, assess the concern and try to resolve it"],"a":3,"why":"Listening, evaluating and responding fairly maintains trust and professionalism and may reveal a safety problem to fix.","t":"Client Communication"}],"mua":[{"q":"Which method best prevents contamination when removing cream foundation from a pot?","c":["Dip a clean fingertip straight into the pot","Press a used sponge firmly into the cream","Scoop product with a clean spatula onto a palette","Swirl the client's used brush around the pot"],"a":2,"why":"A clean spatula moves product to a palette without introducing bacteria from skin or tools into the container.","t":"Infection Control"},{"q":"Between clients, reusable makeup brushes should be:","c":["Cleaned, then disinfected with an EPA-registered product","Wiped once with a dry tissue and stored in the kit","Rinsed with cold water and put away while still wet","Left out in open air for an hour between clients"],"a":0,"why":"Reusable tools must be cleaned first and then disinfected with an EPA-registered disinfectant used per label directions.","t":"Infection Control"},{"q":"Which item must be discarded after being used on one client?","c":["A reusable powder brush","A stainless steel spatula","A metal eyelash curler","A disposable mascara wand"],"a":3,"why":"Disposable applicators are single-use and are thrown away after one client; reusable tools are cleaned and disinfected instead.","t":"Infection Control"},{"q":"Why must an applicator never go back into a product container after touching the client's skin?","c":["It slowly thins the formula over time","It transfers bacteria into the product","It makes the pigment look lighter","It dries out the product in the pot"],"a":1,"why":"Double-dipping carries microbes from the client's skin into the container, contaminating it for the next client.","t":"Infection Control"},{"q":"Why should a mascara wand not be pumped in and out of its tube?","c":["It makes the bristles stiff and clumpy","It forces in air, drying product and promoting bacteria","It changes the color of the formula","It loosens the brush from its handle"],"a":1,"why":"Pumping pushes air into the tube, which dries the formula faster and promotes microbial growth.","t":"Infection Control"},{"q":"What is the most hygienic way to apply lipstick to multiple clients?","c":["Wipe the bullet with a tissue between clients","Twist up fresh product and apply it directly","Have each client blot the color on a hand first","Move product to a palette with a spatula and use a clean lip brush"],"a":3,"why":"Removing product with a spatula and applying with a clean or disposable brush keeps the original bullet from touching any client's lips.","t":"Infection Control"},{"q":"A client's eyes are red, watery and crusted, suggesting conjunctivitis. What should you do?","c":["Decline eye services and advise her to see a physician","Use waterproof liner to seal in the redness","Proceed using only disposable applicators","Apply concealer around the eye to hide the redness"],"a":0,"why":"Conjunctivitis is contagious, so eye services must be refused and the client referred to a physician.","t":"Infection Control"},{"q":"A client has a visible stye on her upper eyelid. What is the correct action?","c":["Cover it with concealer and continue the service","Gently drain it before applying any shadow","Avoid eye makeup and refer her to a physician","Apply strip lashes to hide it from view"],"a":2,"why":"A stye is an infection; eye makeup could spread it and irritate it, and treating it is outside a makeup artist's scope.","t":"Infection Control"},{"q":"A client has an active cold sore on her lip. What should you do?","c":["Apply lipstick over it for full coverage","Dab concealer over it with a cotton swab","Outline it with lip liner to disguise it","Skip the area and suggest she wait until it heals"],"a":3,"why":"Cold sores are contagious and can spread through tools and products, so the area should not be serviced.","t":"Infection Control"},{"q":"Which virus causes cold sores (fever blisters)?","c":["Human papillomavirus","Herpes simplex virus","Rotavirus","Hepatitis A virus"],"a":1,"why":"Cold sores are caused by the herpes simplex virus, which spreads by direct contact and contaminated items.","t":"Infection Control"},{"q":"Disinfectant 'contact time' is the length of time a surface must:","c":["Be scrubbed before disinfectant is used","Air-dry after wiping with the product","Remain visibly wet with the disinfectant","Be stored away before it is reused"],"a":2,"why":"The surface must stay wet with disinfectant for the full time on the label for the product to be effective.","t":"Infection Control"},{"q":"Which is the correct way to use an EPA-registered disinfectant?","c":["Follow the manufacturer's dilution and contact-time directions","Mix it with other cleaners to boost its strength","Use a stronger dilution than the label recommends","Dilute it further so the container lasts longer"],"a":0,"why":"Dilution and contact time on the label are what make the product effective and safe; changing them defeats its registration.","t":"Infection Control"},{"q":"When should a makeup artist wash her hands?","c":["Before and after every client","Only at the start of the day","Only when hands look soiled","Only after the final client"],"a":0,"why":"Hand washing before and after each client is the most effective way to prevent spreading pathogens.","t":"Infection Control"},{"q":"Which pair of bloodborne pathogens is of greatest concern in beauty services?","c":["Ringworm and head lice","Strep and staph","HIV and hepatitis B","Influenza and the common cold"],"a":2,"why":"HIV and hepatitis B are spread through blood and are the key bloodborne pathogens addressed in infection control.","t":"Infection Control"},{"q":"You accidentally nick a client and the skin bleeds. What is the correct response?","c":["Wipe it with the foundation sponge and carry on","Put on gloves, stop the bleeding, cover it, bag soiled items","Rinse the tool under water and use it right away","Ask her to hold a tissue while you finish the look"],"a":1,"why":"Gloves, controlling the bleeding, covering the wound and properly discarding contaminated items protect both people.","t":"Infection Control"},{"q":"A small open-jar symbol marked '12M' on cosmetic packaging means:","c":["The product was made 12 months before opening","It should be used within 12 weeks of purchase","It expires 12 months after the date bought","It is best used within 12 months of opening"],"a":3,"why":"This is the period-after-opening (PAO) symbol, showing how many months a product stays good after it is first opened.","t":"Infection Control"},{"q":"Which product usually needs replacing soonest because of bacterial risk?","c":["Pressed powder eyeshadow","Lipstick bullet","Liquid mascara","Dry bronzer"],"a":2,"why":"Liquid products used near the eyes, such as mascara, are moist and prone to microbial growth, so they are replaced most often.","t":"Infection Control"},{"q":"Why do cream and liquid products carry more contamination risk than dry powders?","c":["Their water and oil content supports microbial growth","They always contain more pigment than powders","They are applied with heavier brushes or sponges","They never contain any preservatives at all"],"a":0,"why":"Moisture and oils give microbes an environment to grow, while dry powders are less hospitable.","t":"Infection Control"},{"q":"A metal spatula used to remove product from containers should be:","c":["Wiped with a tissue and reused","Rinsed under water only","Left in the product between uses","Cleaned and disinfected after each use"],"a":3,"why":"Nonporous reusable tools such as metal spatulas must be cleaned and disinfected between uses.","t":"Infection Control"},{"q":"A porous wedge sponge used on a client should be:","c":["Sprayed with disinfectant and reused","Discarded after that client","Rinsed in water and air-dried","Wiped with a damp cloth"],"a":1,"why":"Porous items cannot be properly disinfected, so they are thrown away after one use.","t":"Infection Control"},{"q":"Standard (universal) precautions mean treating:","c":["Only visible wounds as potentially infectious","All blood and body fluids as potentially infectious","Only clients with known illnesses as infectious","Only used tools and sponges as contaminated"],"a":1,"why":"Standard precautions assume any blood or body fluid could carry disease, regardless of the client's apparent health.","t":"Infection Control"},{"q":"A stye is most commonly caused by:","c":["A virus spread through the air","A fungus growing on the skin","A parasite living on the lashes","A bacterial infection of a follicle"],"a":3,"why":"Styes are usually a bacterial (staphylococcal) infection of an eyelash follicle or oil gland.","t":"Infection Control"},{"q":"Which level of infection control destroys all microbial life, including spores?","c":["Sterilization","Disinfection","Sanitation","Cleaning"],"a":0,"why":"Sterilization is the highest level and kills every living microorganism; disinfection and sanitation do not guarantee that.","t":"Infection Control"},{"q":"Which is a sign that a cosmetic product has become contaminated and should be discarded?","c":["A slightly dusty outer box","A cool feel when it is applied","A change in odor, color or texture","A glossy, shiny label"],"a":2,"why":"A change in smell, color, consistency or separation indicates spoilage or contamination, so the product should be thrown away.","t":"Infection Control"},{"q":"What is the correct order for disinfecting a nonporous tool?","c":["Disinfect first, rinse, then wash with soap","Dry it first, then wipe it with plain water","Spray it lightly, then wipe it off at once","Wash with soap, rinse, then disinfect for full contact time"],"a":3,"why":"Cleaning removes debris first so the disinfectant can work, and it must stay on for the full contact time.","t":"Infection Control"},{"q":"Which skin type produces little sebum and often feels tight or looks flaky?","c":["Oily","Dry","Combination","Normal"],"a":1,"why":"Dry skin has low oil production, which leads to tightness and flaking.","t":"Skin & Anatomy"},{"q":"An oily T-zone with normal-to-dry cheeks describes which skin type?","c":["Dry","Normal","Combination","Mature"],"a":2,"why":"Combination skin is oily in the forehead, nose and chin area but normal or dry elsewhere.","t":"Skin & Anatomy"},{"q":"The Fitzpatrick scale classifies skin according to its:","c":["Reaction to sun exposure","Amount of sebum it produces","Warm or cool undertone","Level of moisture in skin"],"a":0,"why":"The scale rates skin types I to VI by how readily they burn or tan with UV exposure.","t":"Skin & Anatomy"},{"q":"Which describes Fitzpatrick Type I skin?","c":["Very fair; burns easily and rarely tans","Medium; tans well and burns only mildly","Brown; tans easily and rarely burns","Deep brown; very rarely burns at all"],"a":0,"why":"Type I is the fairest type, burning easily and almost never tanning.","t":"Skin & Anatomy"},{"q":"The purpose of a patch test before a service is to:","c":["Match the foundation shade to skin","Measure the moisture level of skin","Check for an allergic reaction to a product","Confirm the SPF strength of a product"],"a":2,"why":"A small test application on skin shows whether the client reacts to a product before full use.","t":"Skin & Anatomy"},{"q":"Which is a typical sign of an allergic reaction to a cosmetic?","c":["Even, smooth skin tone","Itching, redness, swelling or hives","A smooth, dewy-looking finish","A temporary cool sensation on skin"],"a":1,"why":"Itching, redness, swelling and hives are classic signs of an allergic or sensitivity reaction.","t":"Skin & Anatomy"},{"q":"A client develops swelling and itching during a service. What should you do first?","c":["Cover the area with powder to calm it","Switch to a different foundation formula","Keep going but work faster to finish","Stop, remove product gently, get medical help if severe"],"a":3,"why":"Stopping and removing the product limits exposure, and a severe reaction needs medical attention.","t":"Skin & Anatomy"},{"q":"A face widest at the cheekbones with a narrow forehead and chin is called:","c":["Square","Oblong","Diamond","Round"],"a":2,"why":"A diamond face is widest across the cheekbones, with a narrower forehead and chin.","t":"Skin & Anatomy"},{"q":"Which face shape has a broad forehead and a strong, angular jaw of similar width?","c":["Square","Heart","Diamond","Pear"],"a":0,"why":"A square face has forehead and jaw of about equal width with an angular jawline.","t":"Skin & Anatomy"},{"q":"A heart-shaped face is typically widest at the:","c":["Jawline","Chin","Cheek hollows","Forehead"],"a":3,"why":"A heart-shaped face has a wide forehead that tapers to a narrower chin.","t":"Skin & Anatomy"},{"q":"The zygomatic bone is commonly known as the:","c":["Jawbone","Cheekbone","Nose bridge","Brow bone"],"a":1,"why":"The zygomatic bone forms the cheekbone, a key landmark for contour and highlight placement.","t":"Skin & Anatomy"},{"q":"A client with rosacea has persistent facial redness. Which approach is most appropriate?","c":["Use abrasive scrubs before applying","Use gentle products and avoid harsh friction","Apply a strong astringent before makeup","Rub in foundation with firm pressure"],"a":1,"why":"Rosacea-prone skin is easily irritated, so gentle products and light handling are best.","t":"Skin & Anatomy"},{"q":"Which condition is a contraindication for makeup application over the affected area?","c":["Freckles","Mild dryness","A flat natural birthmark","Open or infected lesions"],"a":3,"why":"Makeup should not be applied over open or infected skin because it can worsen the condition and spread infection.","t":"Skin & Anatomy"},{"q":"Which change occurs in mature skin?","c":["Reduced collagen, elastin and oil production","Increased sebum and oil production","Faster cell turnover and renewal","A thicker, firmer epidermis overall"],"a":0,"why":"With age, collagen, elastin and oil decline, leading to thinner, drier skin with more lines.","t":"Skin & Anatomy"},{"q":"Which pigment is mainly responsible for skin color?","c":["Carotene","Keratin","Melanin","Collagen"],"a":2,"why":"Melanin, made by melanocytes, is the primary pigment that determines skin color.","t":"Skin & Anatomy"},{"q":"The primary colors in traditional pigment color theory are:","c":["Red, green and blue","Orange, green and violet","Red, yellow and green","Red, yellow and blue"],"a":3,"why":"Red, yellow and blue cannot be made by mixing other pigments and are the primaries on the traditional color wheel.","t":"Color Theory"},{"q":"Mixing equal parts blue and yellow produces:","c":["Orange","Green","Violet","Brown"],"a":1,"why":"Blue and yellow are primaries whose mixture creates the secondary color green.","t":"Color Theory"},{"q":"On the traditional red-yellow-blue color wheel, which pair are complementary colors?","c":["Red and orange","Blue and green","Yellow and violet","Red and violet"],"a":2,"why":"Complementary colors sit opposite each other on the traditional red-yellow-blue wheel; yellow is opposite violet.","t":"Color Theory"},{"q":"Green corrector is used to neutralize:","c":["Redness from blemishes or irritation","Blue-purple under-eye shadows","Sallow, yellowish skin tones","Dull, grayish skin tones"],"a":0,"why":"Green is opposite red on the color wheel, so it cancels redness.","t":"Color Theory"},{"q":"Which corrector best neutralizes bluish under-eye darkness on medium-to-deep skin?","c":["Peach or orange","Green or mint","Lavender or lilac","White or ivory"],"a":0,"why":"Orange and peach are opposite blue on the wheel and cancel bluish discoloration.","t":"Color Theory"},{"q":"Lavender corrector helps neutralize:","c":["Redness or flushing","Blue shadows or veins","Sallow yellow tones","Brown sun spots"],"a":2,"why":"Lavender is opposite yellow on the wheel, so it softens sallow or yellow tones.","t":"Color Theory"},{"q":"Skin undertone is best described as:","c":["Surface color that shifts with tanning","The subtle hue beneath the surface that stays constant","Redness caused by irritation or heat","The depth or lightness of the skin"],"a":1,"why":"Undertone is the constant underlying hue of skin, unlike surface color, which changes with sun and irritation.","t":"Color Theory"},{"q":"Which undertone is described as golden, peach or yellow?","c":["Cool","Neutral","Ashen","Warm"],"a":3,"why":"Warm undertones have golden, peachy or yellow hues.","t":"Color Theory"},{"q":"Which undertone has pink, rosy or bluish hues?","c":["Warm","Neutral","Cool","Golden"],"a":2,"why":"Cool undertones lean pink, red or blue, in contrast with golden warm undertones.","t":"Color Theory"},{"q":"In color theory, 'value' refers to a color's:","c":["Lightness or darkness","Family name","Intensity or purity","Temperature"],"a":0,"why":"Value is how light or dark a color is; hue is its name and chroma its intensity.","t":"Color Theory"},{"q":"Chroma (saturation) describes a color's:","c":["Lightness or darkness","Name on the color wheel","Warmth or coolness","Intensity or purity"],"a":3,"why":"Chroma is how vivid or pure a color is, compared with a dull or grayed version.","t":"Color Theory"},{"q":"Adding white to a pure hue creates a:","c":["Shade","Tint","Tone","Primary"],"a":1,"why":"A tint is a hue lightened with white; a shade is darkened with black and a tone is mixed with gray.","t":"Color Theory"},{"q":"For the most accurate match, foundation should be tested on the:","c":["Back of the hand","Jawline in natural light","Inner wrist","Forearm in dim light"],"a":1,"why":"The jawline sits between face and neck, and natural light shows the true match.","t":"Color Theory"},{"q":"A correctly matched foundation should:","c":["Look lighter than the neck to brighten","Look darker than the neck for warmth","Leave a defined line at the jaw","Blend into jaw and neck with no visible line"],"a":3,"why":"A good match disappears into the skin, with no mask-like line at the jaw or neck.","t":"Color Theory"},{"q":"Which makes an area appear to recede or look smaller?","c":["Deeper, matte shades","Light shimmery shades","Bright warm shades","Frosted white shades"],"a":0,"why":"Dark, matte shades absorb light and make an area recede, while light and shimmer bring it forward.","t":"Color Theory"},{"q":"Which foundation formula typically provides the fullest coverage?","c":["Tinted moisturizer","Sheer liquid tint","Cream or stick foundation","Light serum foundation"],"a":2,"why":"Cream and stick foundations contain more pigment and are the most heavily covering of these.","t":"Products & Ingredients"},{"q":"Which foundation is generally best for oily skin?","c":["Heavy, rich cream","Oil-based emollient cream","Dewy cream-to-liquid","Oil-free, mattifying liquid"],"a":3,"why":"Oil-free matte formulas control shine and avoid adding oil to already oily skin.","t":"Products & Ingredients"},{"q":"A makeup primer is applied after moisturizer mainly to:","c":["Replace the need for sunscreen","Smooth skin and help makeup last","Remove excess makeup residue","Add full coverage to skin"],"a":1,"why":"Primer creates a smoother base and helps foundation wear longer.","t":"Products & Ingredients"},{"q":"Translucent setting powder is used primarily to:","c":["Add deep color to the skin","Hydrate dry areas of skin","Set cream products and control shine","Replace the foundation entirely"],"a":2,"why":"A colorless setting powder locks in liquid and cream makeup and reduces shine without changing the shade much.","t":"Products & Ingredients"},{"q":"Which ingredient is listed first in a typical water-based foundation?","c":["Water","Mineral oil","Talc","Silicone"],"a":0,"why":"Ingredients are listed by amount, and water is the main ingredient in a water-based formula.","t":"Products & Ingredients"},{"q":"Iron oxides in cosmetics are used mainly as:","c":["Pigments","Preservatives","Emulsifiers","Fragrances"],"a":0,"why":"Iron oxides are mineral pigments that provide yellow, red, brown and black color in makeup.","t":"Products & Ingredients"},{"q":"Preservatives in cosmetics are included to:","c":["Add shine to the formula","Thicken the formula's texture","Slow growth of bacteria and mold","Boost the color payoff"],"a":2,"why":"Preservatives inhibit microbial growth and extend a product's safe shelf life.","t":"Products & Ingredients"},{"q":"A client has a latex allergy. Which lash adhesive should you choose?","c":["A latex-based adhesive with a barrier","A latex-free adhesive","Any adhesive after a rinse","A latex adhesive used sparingly"],"a":1,"why":"Latex-allergic clients must avoid latex entirely, so a latex-free adhesive is required.","t":"Products & Ingredients"},{"q":"The SPF number on a sunscreen indicates protection mainly against:","c":["UVA aging rays","Infrared heat","Visible light","UVB burning rays"],"a":3,"why":"SPF measures protection from UVB rays, which cause sunburn.","t":"Products & Ingredients"},{"q":"A 'broad-spectrum' label means a sunscreen protects against:","c":["UVB rays only","UVC rays only","Both UVA and UVB rays","Visible light only"],"a":2,"why":"Broad-spectrum products shield against both UVA and UVB radiation.","t":"Products & Ingredients"},{"q":"Oil and water in a foundation are kept blended by:","c":["An emulsifier","A pigment","A fragrance","A powder filler"],"a":0,"why":"An emulsifier stabilizes the mixture so oil and water do not separate.","t":"Products & Ingredients"},{"q":"Humectants such as glycerin in cosmetics:","c":["Add color to the product","Block UV rays from skin","Kill bacteria on the skin","Attract and hold moisture"],"a":3,"why":"Humectants draw water to the skin and help products feel hydrating.","t":"Products & Ingredients"},{"q":"Waterproof mascara is best removed with:","c":["Plain water and a cloth","An oil-based or waterproof-specific remover","A dry tissue wiped quickly","An alcohol-based astringent toner"],"a":1,"why":"Waterproof formulas resist water, so an oil-based or specially formulated remover is needed to dissolve them gently.","t":"Products & Ingredients"},{"q":"Shimmer highlighters get their light-reflecting effect mainly from:","c":["Kaolin clay","Mica","Glycerin","Dimethicone"],"a":1,"why":"Mica is a mineral with reflective particles used for shimmer and glow.","t":"Products & Ingredients"},{"q":"Setting spray is typically used:","c":["Before applying the moisturizer","As a facial cleanser before makeup","To thin out a thick foundation","After makeup to help it last and meld layers"],"a":3,"why":"A setting spray is a finishing step that helps makeup wear longer and look more cohesive.","t":"Products & Ingredients"},{"q":"What is the correct skin prep order before makeup?","c":["Cleanse, tone, moisturize, prime","Prime, cleanse, tone, moisturize","Moisturize, prime, cleanse, tone","Tone, prime, cleanse, moisturize"],"a":0,"why":"A clean, balanced and hydrated surface comes first, and primer is the last prep step before foundation.","t":"Application"},{"q":"To brighten under-eye shadows, concealer is generally chosen:","c":["Two shades darker than foundation","Matched to the lip color","About one shade lighter than foundation","Much lighter than the face"],"a":2,"why":"Concealer slightly lighter than foundation lifts shadows; going much lighter looks unnatural.","t":"Application"},{"q":"Where is contour typically placed?","c":["On the highest points of the cheekbones","Across the center of the forehead","On the apples of the cheeks","In hollows, such as under the cheekbones"],"a":3,"why":"Contour uses darker shades in the hollows to create shadow and depth.","t":"Application"},{"q":"Highlighter on high points of the face makes them:","c":["Appear smaller and recede","Catch light and appear more prominent","Look matte and flat","Blend into the surrounding shadow"],"a":1,"why":"Light-reflecting products bring areas forward and make them look more prominent.","t":"Application"},{"q":"Contour looks harsh and streaky. What is the best fix?","c":["Add more product over the streaks","Apply heavy loose powder on top","Blend edges with a clean brush or sponge","Wipe off the entire face and restart"],"a":2,"why":"Blending softens the edges so contour looks like natural shadow rather than lines.","t":"Application"},{"q":"For hooded eyes, where should shadow depth be placed?","c":["Slightly above the crease, visible when eyes are open","Only on the lid, well below the crease line","Along the lower waterline and lash line only","In the inner corner and tear duct only"],"a":0,"why":"Depth placed slightly above the crease stays visible when the eyes are open, because the lid is partly covered by skin.","t":"Application"},{"q":"Which shadow technique helps bring deep-set eyes forward?","c":["Light or shimmery shades on the lid","Dark matte shades over the whole lid","Heavy dark liner on the lower lid","Dark shadow in the socket"],"a":0,"why":"Light and shimmery shades on the lid reflect light and bring recessed eyes forward.","t":"Application"},{"q":"In the common brow-mapping method, the brow is usually started in line with the:","c":["Outer corner of the eye","Center of the pupil","Inner corner of the eye","Tip of the nose"],"a":2,"why":"In the widely taught mapping method, a vertical line from the side of the nostril through the inner eye corner marks where the brow begins; artists adjust to the individual face.","t":"Application"},{"q":"In one common brow-mapping guide, the highest point of the arch sits above the:","c":["Inner corner of the eye","Outer edge of the iris","Center of the nose","Outer corner of the eye"],"a":1,"why":"One widely taught guide runs a line from the nostril past the outer edge of the iris to mark the arch; placement is a guideline that artists adapt to the client's bone structure.","t":"Application"},{"q":"In the common brow-mapping method, the brow tail is usually ended where a line from the nostril passes through the:","c":["Pupil","Inner corner of the eye","Edge of the iris","Outer corner of the eye"],"a":3,"why":"In the widely taught mapping method, the diagonal from the nostril through the outer corner of the eye marks where the brow typically ends; artists adjust to the individual face.","t":"Application"},{"q":"Before applying a strip lash, you should:","c":["Apply adhesive to the client's lash roots","Curl the strip with a heated tool","Measure the strip and trim it to fit the eye","Dip the strip in remover to soften it"],"a":2,"why":"Measuring and trimming the band ensures a comfortable, natural fit before adhesive is applied.","t":"Application"},{"q":"After adhesive is applied to a strip lash band, you should:","c":["Wait until it becomes tacky","Place it immediately while wet","Let it dry completely hard","Apply a second coat right away"],"a":0,"why":"Adhesive grips best once it turns tacky, which also reduces slipping and irritation.","t":"Application"},{"q":"A strip lash should be positioned:","c":["On the eyelid crease above the lashes","Through the natural lashes themselves","At the very tips of the natural lashes","Along the lash line, as close to the base as possible"],"a":3,"why":"Placing the band at the lash line looks natural and stays comfortable.","t":"Application"},{"q":"Which brush is best for softly blending eyeshadow in the crease?","c":["Small flat concealer brush","Fluffy tapered blending brush","Stiff angled liner brush","Dense kabuki face brush"],"a":1,"why":"A fluffy tapered brush diffuses color softly for a gradient effect.","t":"Application"},{"q":"Which step helps prevent lipstick from feathering?","c":["Applying gloss first","Outlining with lip liner","Using a very thick layer","Applying it over dry flakes"],"a":1,"why":"Lip liner creates a barrier at the edge of the lips that keeps color in place.","t":"Application"},{"q":"Before lipstick, dry flaky lips should be:","c":["Peeled by hand to remove dryness","Dusted with loose powder","Scrubbed hard with a washcloth","Gently exfoliated and moisturized"],"a":3,"why":"Gentle exfoliation and moisture smooth the lips for even color without irritation.","t":"Application"},{"q":"Which approach suits HD photography or video?","c":["Thin, well-blended layers with little heavy powder","Thick foundation to hide every pore","Heavy shimmer applied all over the face","Generous loose powder baked over everything"],"a":0,"why":"HD cameras reveal texture and heavy layers, so thin, well-blended makeup looks the most natural.","t":"Application"},{"q":"Which ingredient can cause white 'flashback' in flash photos?","c":["Iron oxide pigments","Glycerin humectants","Titanium dioxide or zinc oxide","Dimethicone silicone"],"a":2,"why":"Titanium dioxide and zinc oxide (often in SPF products) reflect flash and can leave a white cast.","t":"Application"},{"q":"Bridal makeup should generally be:","c":["A dramatic trend unlike her usual look","Applied very heavily to read on camera","Loaded with shimmer for the photos","Long-wearing and photographs well in varied light"],"a":3,"why":"A bride's makeup must last through the day and photograph well while still looking like her.","t":"Application"},{"q":"Which choice best flatters mature skin?","c":["Thick matte foundation in several layers","Hydrating formulas applied sparingly","Loose powder pressed into lines","Heavy dark contour"],"a":1,"why":"Hydrating, lightweight formulas avoid settling into lines and keep mature skin looking fresh.","t":"Application"},{"q":"What should come first in every makeup service?","c":["Applying primer across the whole face","Choosing the lipstick shade for the look","A consultation about needs and allergies","Cleansing with a toner and a cloth"],"a":2,"why":"A consultation identifies the client's goals, sensitivities and any contraindications before work begins.","t":"Professional Practice"},{"q":"A client intake form should record:","c":["Allergies, sensitivities and skin conditions","Her annual household income","Her marital or relationship status","Her social media passwords"],"a":0,"why":"Health and sensitivity information is needed to provide a safe service.","t":"Professional Practice"},{"q":"Which is within a makeup artist's scope of practice?","c":["Applying cosmetics to enhance appearance","Diagnosing a skin disease","Prescribing an acne treatment","Treating eczema with medical products"],"a":0,"why":"Makeup artists enhance appearance; diagnosis and treatment belong to medical professionals.","t":"Professional Practice"},{"q":"A client asks whether your concealer will cure her eczema. How should you respond?","c":["Say yes, it will help heal her damaged skin","Say it will treat eczema gradually with use","Say no cure is promised; refer her to a physician","Recommend a prescription-strength cream for it"],"a":2,"why":"Cosmetics cannot be promoted as treating medical conditions, so the client should be referred to a physician.","t":"Professional Practice"},{"q":"Which practice best ensures client comfort and safety?","c":["Keep the chair flat for the entire service","Drape the client and explain steps before touching","Work quickly and avoid talking to the client","Skip draping to save time between clients"],"a":1,"why":"Draping and explaining steps keep the client comfortable, protect clothing and build trust.","t":"Professional Practice"},{"q":"Which is good aftercare advice following a makeup service?","c":["Sleep in the makeup for longevity","Share lip products with friends","Pull off lashes when they feel loose","Remove makeup thoroughly before bed"],"a":3,"why":"Removing makeup before sleep keeps skin and eyes healthy and prevents irritation.","t":"Professional Practice"},{"q":"Professional liability insurance helps protect an artist against:","c":["Slow business seasons or lost bookings","Loss of products and kit supplies only","Claims of injury or damage from services","Income tax owed on earnings"],"a":2,"why":"Liability insurance covers claims that a client was harmed or suffered damage because of a service.","t":"Professional Practice"},{"q":"When setting service prices, an artist should consider:","c":["Time, skill, product costs and overhead","Only the client's income and job","Only the lowest price in her area","Only how she feels on that day"],"a":0,"why":"Fair pricing reflects the artist's time, expertise, supplies and business expenses.","t":"Professional Practice"},{"q":"Which action is ethical?","c":["Posting a client's photo without asking","Discussing a client's skin concerns with others","Pressuring clients to buy extras","Getting permission before sharing before-and-after photos"],"a":3,"why":"Respecting privacy and obtaining consent are basic professional ethics.","t":"Professional Practice"},{"q":"Why keep clean and used tools in separate areas of a kit?","c":["To save space","To prevent cross-contamination","To lower costs","To speed up shade matching"],"a":1,"why":"Separating clean and used items prevents transferring microbes between clients.","t":"Professional Practice"}]};
